//! Unicode character property helpers for the regex engine.

use super::unicode_tables::{CATEGORY_NAMES, GC_RANGES};

// Category indices (must match tools/gen_unicode.py ordering).
pub const LU: u8 = 0;
pub const LL: u8 = 1;
pub const LT: u8 = 2;
pub const LM: u8 = 3;
pub const LO: u8 = 4;
pub const MN: u8 = 5;
pub const MC: u8 = 6;
pub const ME: u8 = 7;
pub const ND: u8 = 8;
pub const NL: u8 = 9;
pub const NO: u8 = 10;
pub const PC: u8 = 11;
pub const ZS: u8 = 22;
pub const CC: u8 = 25;
pub const CF: u8 = 26;
pub const CS: u8 = 27;
pub const CO: u8 = 28;
pub const CN: u8 = 29;

pub fn category(c: char) -> u8 {
    let cp = c as u32;
    let mut lo = 0usize;
    let mut hi = GC_RANGES.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b, cat) = GC_RANGES[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return cat;
        }
    }
    CN
}

pub fn cat_mask(c: char) -> u32 {
    1u32 << category(c)
}

pub const MASK_L: u32 = (1 << LU) | (1 << LL) | (1 << LT) | (1 << LM) | (1 << LO);
pub const MASK_M: u32 = (1 << MN) | (1 << MC) | (1 << ME);
pub const MASK_N: u32 = (1 << ND) | (1 << NL) | (1 << NO);
pub const MASK_P: u32 = 0b1111111 << PC;
pub const MASK_S: u32 = 0b1111 << 18;
pub const MASK_Z: u32 = 0b111 << ZS;
pub const MASK_C: u32 = 0b11111 << CC;

/// Binary / composite properties.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Prop {
    Cats(u32),
    Alpha,
    Word,
    Digit,
    Space,
    XDigit,
    Upper,
    Lower,
    Alnum,
    Punct,
    Print,
    Graph,
    Cntrl,
    Blank,
    Ascii,
    Any,
    Hex, // \h
}

pub fn is_space(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\x0B' | '\x0C' | '\r' | ' ' | '\u{85}' | '\u{A0}' | '\u{1680}'
        | '\u{2000}'..='\u{200A}' | '\u{2028}' | '\u{2029}' | '\u{202F}' | '\u{205F}' | '\u{3000}')
}

pub fn is_word(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    if c.is_alphabetic() {
        return true;
    }
    let m = cat_mask(c);
    m & (MASK_M | (1 << ND) | (1 << PC)) != 0 || c == '\u{200C}' || c == '\u{200D}'
}

impl Prop {
    pub fn matches(self, c: char) -> bool {
        match self {
            Prop::Cats(mask) => cat_mask(c) & mask != 0,
            Prop::Alpha => c.is_alphabetic(),
            Prop::Word => is_word(c),
            Prop::Digit => {
                if c.is_ascii() {
                    c.is_ascii_digit()
                } else {
                    category(c) == ND
                }
            }
            Prop::Space => is_space(c),
            Prop::XDigit | Prop::Hex => c.is_ascii_hexdigit(),
            Prop::Upper => c.is_uppercase(),
            Prop::Lower => c.is_lowercase(),
            Prop::Alnum => c.is_alphabetic() || Prop::Digit.matches(c),
            Prop::Punct => {
                if c.is_ascii() {
                    c.is_ascii_punctuation()
                } else {
                    cat_mask(c) & MASK_P != 0
                }
            }
            Prop::Graph => {
                if is_space(c) {
                    return false;
                }
                let cat = category(c);
                !(cat == CC || cat == CS || cat == CN)
            }
            Prop::Print => {
                if c == ' ' {
                    return true;
                }
                let cat = category(c);
                if cat == ZS {
                    return true;
                }
                Prop::Graph.matches(c)
            }
