pub const NO: u8 = 10;
pub const PC: u8 = 11;
pub const ZS: u8 = 22;
pub const CC: u8 = 25;
pub const CF: u8 = 26;
pub const CS: u8 = 27;
pub const CO: u8 = 28;
pub const CN: u8 = 29;

pub fn category(c: char) -> u8 {
    let cp = c as u32;
    let mut lo = 0usize;
    let mut hi = GC_RANGES.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b, cat) = GC_RANGES[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return cat;
        }
    }
