//! A backtracking regular expression engine implementing the subset of the
//! Oniguruma (Ruby syntax) dialect that is used by Sublime Text syntax
//! definitions: captures, named groups, lookaround, atomic groups,
//! possessive/lazy quantifiers, back-references, subexpression calls,
//! inline options, Unicode properties, POSIX brackets and class intersection.

mod unicode;
mod unicode_tables;

pub use unicode::is_word;
use unicode::{case_variants, fold, lookup_prop, Prop};

type NodeId = usize;
const UNSET: usize = usize::MAX;
const INF: u32 = u32::MAX;

#[derive(Clone, Debug)]
enum Item {
    Range(char, char),
    Prop(Prop, bool),
    Class(Box<Class>),
}

#[derive(Clone, Debug)]
struct Class {
    neg: bool,
    icase: bool,
    items: Vec<Item>,
    and: Vec<Class>,
    ascii: u128,
}

impl Class {
    fn raw_match(&self, c: char) -> bool {
        let mut r = self.items.iter().any(|it| match it {
            Item::Range(a, b) => *a <= c && c <= *b,
            Item::Prop(p, n) => p.matches(c) != *n,
            Item::Class(cl) => cl.matches(c),
        });
        if r {
            for a in &self.and {
                if !a.matches(c) {
                    r = false;
                    break;
                }
            }
        }
        r
    }

    fn matches_slow(&self, c: char) -> bool {
        let r = if self.icase {
            case_variants(c).into_iter().any(|v| self.raw_match(v))
        } else {
            self.raw_match(c)
        };
        r != self.neg
    }

    #[inline]
    fn matches(&self, c: char) -> bool {
        let cp = c as u32;
        if cp < 128 {
            return (self.ascii >> cp) & 1 == 1;
        }
        self.matches_slow(c)
    }

    fn finalize(&mut self) {
        for it in self.items.iter_mut() {
            if let Item::Class(c) = it {
                c.finalize();
            }
        }
        for a in self.and.iter_mut() {
            a.finalize();
        }
        let mut bits = 0u128;
        for cp in 0u32..128 {
            if self.matches_slow(char::from_u32(cp).unwrap()) {
                bits |= 1u128 << cp;
            }
        }
        self.ascii = bits;
    }
}

#[derive(Clone, Debug)]
enum Node {
    Empty,
    Char(char),
    CharI(char),
    Any,
    AnyNl,
    Class(Box<Class>),
    Seq(Vec<NodeId>),
    Alt(Vec<NodeId>),
    Group(usize, NodeId),
    Repeat { node: NodeId, min: u32, max: u32, greedy: bool, possessive: bool },
    Atomic(NodeId),
    Look { behind: bool, neg: bool, node: NodeId, minlen: usize, maxlen: usize },
    Backref { groups: Vec<usize>, icase: bool },
    Call(usize),
    LineStart,
    LineEnd,
    BufStart,
    BufEnd,
    BufEndNl,
    WordB,
    NotWordB,
    SearchStart,
    Keep,
}

#[derive(Clone, Copy)]
struct Flags {
    icase: bool,
    extended: bool,
    dotall: bool,
}

enum PendingCall {
    Name(String),
    Abs(usize),
}

struct Parser<'a> {
    c: Vec<char>,
    i: usize,
    nodes: Vec<Node>,
    ngroups: usize,
    total_groups: usize,
    names: Vec<(String, usize)>,
    group_nodes: Vec<NodeId>,
    calls: Vec<(NodeId, PendingCall)>,
    named_backrefs: Vec<(NodeId, String)>,
    _p: std::marker::PhantomData<&'a ()>,
}

pub struct Regex {
    nodes: Vec<Node>,
    root: NodeId,
    ngroups: usize,
    group_nodes: Vec<NodeId>,
    first: Option<Box<[bool; 128]>>,
    first_nonascii: bool,
    anchor: Anchor,
    pattern: String,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Anchor {
    None,
    LineStart,
    BufStart,
    SearchStart,
}

#[derive(Clone, Debug, Default)]
pub struct Region {
    pub pos: Vec<usize>,
}

impl Region {
    pub fn new() -> Region {
        Region { pos: Vec::new() }
    }
    pub fn get(&self, i: usize) -> Option<(usize, usize)> {
        if 2 * i + 1 < self.pos.len() && self.pos[2 * i] != UNSET && self.pos[2 * i + 1] != UNSET {
            Some((self.pos[2 * i], self.pos[2 * i + 1]))
        } else {
            None
        }
    }
    pub fn len(&self) -> usize {
        self.pos.len() / 2
    }
}

fn count_groups(c: &[char]) -> usize {
    let mut n = 0;
    let mut i = 0;
    let mut in_class = 0;
    while i < c.len() {
        match c[i] {
            '\\' => {
                i += 2;
                continue;
            }
            '[' => in_class += 1,
            ']' if in_class > 0 => in_class -= 1,
            '(' if in_class == 0 => {
                if i + 1 < c.len() && c[i + 1] == '?' {
                    if i + 2 < c.len() && (c[i + 2] == '\'' || (c[i + 2] == '<' && i + 3 < c.len() && c[i + 3] != '=' && c[i + 3] != '!')) {
                        n += 1;
                    }
                } else {
                    n += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    n
}

impl<'a> Parser<'a> {
    fn add(&mut self, n: Node) -> NodeId {
        self.nodes.push(n);
        self.nodes.len() - 1
    }
    fn peek(&self) -> Option<char> {
        self.c.get(self.i).copied()
    }
    fn peek_at(&self, k: usize) -> Option<char> {
        self.c.get(self.i + k).copied()
    }
    fn eat(&mut self, ch: char) -> bool {
        if self.peek() == Some(ch) {
            self.i += 1;
            true
        } else {
            false
        }
    }

    fn skip_extended(&mut self, f: Flags) {
        if !f.extended {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0C' || c == '\x0B' => self.i += 1,
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.i += 1;
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    fn parse_alt(&mut self, f: Flags) -> Result<NodeId, String> {
        let mut alts = vec![self.parse_seq(f)?];
        while self.peek() == Some('|') {
            self.i += 1;
            alts.push(self.parse_seq(f)?);
        }
        if alts.len() == 1 {
            Ok(alts[0])
        } else {
            Ok(self.add(Node::Alt(alts)))
        }
    }

    fn parse_seq(&mut self, f: Flags) -> Result<NodeId, String> {
        let mut items: Vec<NodeId> = Vec::new();
        loop {
            self.skip_extended(f);
            match self.peek() {
                None | Some('|') | Some(')') => break,
                _ => {}
            }
            // Isolated option group: (?imx-imx)
            if self.peek() == Some('(') && self.peek_at(1) == Some('?') {
                if let Some((nf, len, isolated)) = self.try_parse_options(f) {
                    if isolated {
                        self.i += len;
                        let rest = self.parse_alt(nf)?;
                        items.push(rest);
                        break;
                    }
                }
            }
            let atom = self.parse_atom(f)?;
            let atom = match atom {
                Some(a) => a,
                None => continue,
            };
            let q = self.parse_quantifiers(atom, f)?;
            items.push(q);
        }
        if items.len() == 1 {
            Ok(items[0])
        } else if items.is_empty() {
            Ok(self.add(Node::Empty))
        } else {
            Ok(self.add(Node::Seq(items)))
        }
    }

    /// Try to parse `(?imx-imx)` or `(?imx-imx:`; returns new flags, length consumed and
    /// whether it is an isolated option (terminated by ')').
    fn try_parse_options(&self, f: Flags) -> Option<(Flags, usize, bool)> {
        let mut j = self.i + 2;
        let mut nf = f;
        let mut on = true;
        let mut any = false;
        while j < self.c.len() {
            match self.c[j] {
                'i' => nf.icase = on,
                'x' => nf.extended = on,
                'm' => nf.dotall = on,
                's' => nf.dotall = on,
                '-' => on = false,
                ')' => {
                    if !any && on {
                        return None;
                    }
                    return Some((nf, j + 1 - self.i, true));
                }
                ':' => {
                    if !any && on {
                        return None;
                    }
                    return Some((nf, j + 1 - self.i, false));
                }
                _ => return None,
            }
            any = true;
            j += 1;
        }
        None
    }

    fn parse_quantifiers(&mut self, mut atom: NodeId, f: Flags) -> Result<NodeId, String> {
        loop {
            self.skip_extended(f);
            let (min, max, is_brace) = match self.peek() {
                Some('*') => {
                    self.i += 1;
                    (0, INF, false)
                }
                Some('+') => {
                    self.i += 1;
                    (1, INF, false)
                }
                Some('?') => {
                    self.i += 1;
                    (0, 1, false)
                }
                Some('{') => match self.try_brace() {
                    Some((mn, mx, len)) => {
                        self.i += len;
                        (mn, mx, true)
                    }
                    None => return Ok(atom),
                },
                _ => return Ok(atom),
            };
            let mut greedy = true;
            let mut possessive = false;
            if self.peek() == Some('?') {
                self.i += 1;
                greedy = false;
            } else if !is_brace && self.peek() == Some('+') {
                self.i += 1;
                possessive = true;
            }
            atom = self.add(Node::Repeat { node: atom, min, max, greedy, possessive });
        }
    }

    fn try_brace(&self) -> Option<(u32, u32, usize)> {
        let mut j = self.i + 1;
        let mut a = String::new();
        while j < self.c.len() && self.c[j].is_ascii_digit() {
            a.push(self.c[j]);
            j += 1;
        }
        let mut b = String::new();
        let mut comma = false;
        if j < self.c.len() && self.c[j] == ',' {
            comma = true;
            j += 1;
            while j < self.c.len() && self.c[j].is_ascii_digit() {
                b.push(self.c[j]);
                j += 1;
            }
        }
        if j >= self.c.len() || self.c[j] != '}' {
            return None;
        }
        if a.is_empty() && b.is_empty() {
            return None;
        }
        let mn: u32 = if a.is_empty() { 0 } else { a.parse().ok()? };
        let mx: u32 = if !comma {
            mn
        } else if b.is_empty() {
            INF
        } else {
            b.parse().ok()?
        };
        Some((mn, mx, j + 1 - self.i))
    }

    fn lit(&mut self, ch: char, f: Flags) -> NodeId {
        if f.icase && case_variants(ch).len() > 1 {
            self.add(Node::CharI(fold(ch)))
        } else {
            self.add(Node::Char(ch))
        }
    }

    fn class_node(&mut self, mut cl: Class) -> NodeId {
        cl.finalize();
        self.add(Node::Class(Box::new(cl)))
    }

    fn prop_class(&mut self, p: Prop, neg: bool, f: Flags) -> NodeId {
        let cl = Class { neg: false, icase: f.icase, items: vec![Item::Prop(p, neg)], and: vec![], ascii: 0 };
        self.class_node(cl)
    }

    fn parse_group_name(&mut self, close: char) -> Result<String, String> {
        let mut s = String::new();
        while let Some(c) = self.peek() {
            self.i += 1;
            if c == close {
                return Ok(s);
            }
            s.push(c);
        }
        Err("invalid group name".into())
    }

    fn parse_atom(&mut self, f: Flags) -> Result<Option<NodeId>, String> {
        let ch = self.peek().unwrap();
        self.i += 1;
        let id = match ch {
            '(' => {
                if self.eat('?') {
                    match self.peek() {
                        Some(':') => {
                            self.i += 1;
                            let n = self.parse_alt(f)?;
                            self.expect_close()?;
                            n
                        }
                        Some('=') | Some('!') => {
                            let neg = self.peek() == Some('!');
                            self.i += 1;
                            let n = self.parse_alt(f)?;
                            self.expect_close()?;
                            self.add(Node::Look { behind: false, neg, node: n, minlen: 0, maxlen: 0 })
                        }
                        Some('>') => {
                            self.i += 1;
                            let n = self.parse_alt(f)?;
                            self.expect_close()?;
                            self.add(Node::Atomic(n))
                        }
                        Some('#') => {
                            while let Some(c) = self.peek() {
                                self.i += 1;
                                if c == ')' {
                                    break;
                                }
                            }
                            return Ok(None);
                        }
                        Some('<') if matches!(self.peek_at(1), Some('=') | Some('!')) => {
                            let neg = self.peek_at(1) == Some('!');
                            self.i += 2;
                            let n = self.parse_alt(f)?;
                            self.expect_close()?;
                            let (minlen, maxlen) = self.width(n);
                            self.add(Node::Look { behind: true, neg, node: n, minlen, maxlen: maxlen.min(10000) })
                        }
                        Some('<') | Some('\'') | Some('P') => {
                            if self.peek() == Some('P') {
                                self.i += 1;
                            }
                            let close = if self.peek() == Some('\'') { '\'' } else { '>' };
                            self.i += 1;
                            let name = self.parse_group_name(close)?;
                            self.ngroups += 1;
                            let gi = self.ngroups;
                            self.names.push((name, gi));
                            let placeholder = self.add(Node::Empty);
                            if self.group_nodes.len() <= gi {
                                self.group_nodes.resize(gi + 1, 0);
                            }
                            self.group_nodes[gi] = placeholder;
                            let n = self.parse_alt(f)?;
                            self.expect_close()?;
                            self.nodes[placeholder] = Node::Group(gi, n);
                            placeholder
                        }
                        _ => {
                            if let Some((nf, len, isolated)) = {
                                self.i -= 2;
                                let r = self.try_parse_options(f);
                                self.i += 2;
                                r
                            } {
                                if isolated {
                                    // handled in parse_seq; shouldn't reach here
                                    self.i += len - 2;
                                    return Ok(None);
                                }
                                self.i += len - 2;
                                let n = self.parse_alt(nf)?;
                                self.expect_close()?;
                                n
                            } else {
                                return Err(format!("undefined group option at {}", self.i));
                            }
                        }
                    }
                } else {
                    self.ngroups += 1;
                    let gi = self.ngroups;
                    let placeholder = self.add(Node::Empty);
                    if self.group_nodes.len() <= gi {
                        self.group_nodes.resize(gi + 1, 0);
                    }
                    self.group_nodes[gi] = placeholder;
                    let n = self.parse_alt(f)?;
                    self.expect_close()?;
                    self.nodes[placeholder] = Node::Group(gi, n);
                    placeholder
                }
            }
            '[' => {
                let cl = self.parse_class(f)?;
                self.class_node(cl)
            }
            '.' => {
                if f.dotall {
                    self.add(Node::AnyNl)
                } else {
                    self.add(Node::Any)
                }
            }
            '^' => self.add(Node::LineStart),
            '$' => self.add(Node::LineEnd),
            '\\' => return self.parse_escape(f).map(Some),
            c => self.lit(c, f),
        };
        Ok(Some(id))
    }

    fn expect_close(&mut self) -> Result<(), String> {
        if self.eat(')') {
            Ok(())
        } else {
            Err("end pattern with unmatched parenthesis".into())
        }
    }

    fn parse_hex(&mut self, maxd: usize) -> Option<u32> {
        let mut v = 0u32;
        let mut n = 0;
        while n < maxd {
            match self.peek().and_then(|c| c.to_digit(16)) {
                Some(d) => {
                    v = v * 16 + d;
                    self.i += 1;
                    n += 1;
                }
                None => break,
            }
        }
        if n == 0 {
            None
        } else {
            Some(v)
        }
    }

    /// Parses escapes that denote a single character. Returns None if not a char escape.
    fn char_escape(&mut self, c: char, in_class: bool) -> Option<char> {
        let r = match c {
            'n' => '\n',
            't' => '\t',
            'r' => '\r',
            'f' => '\x0C',
            'v' => '\x0B',
            'a' => '\x07',
            'e' => '\x1B',
            'b' if in_class => '\x08',
            'x' => {
                if self.peek() == Some('{') {
                    let save = self.i;
                    self.i += 1;
                    let v = self.parse_hex(8);
                    if v.is_some() && self.eat('}') {
                        return char::from_u32(v.unwrap());
                    }
                    self.i = save;
                    return Some('x');
                }
                match self.parse_hex(2) {
                    Some(v) => char::from_u32(v).unwrap_or('\0'),
                    None => '\0',
                }
            }
            'u' => {
                let save = self.i;
                match self.parse_hex(4) {
                    Some(v) if self.i - save == 4 => char::from_u32(v).unwrap_or('\u{FFFD}'),
                    _ => {
                        self.i = save;
                        'u'
                    }
                }
            }
            '0' => {
                let mut v = 0u32;
                let mut n = 0;
                while n < 2 {
                    match self.peek().and_then(|c| c.to_digit(8)) {
                        Some(d) => {
                            v = v * 8 + d;
                            self.i += 1;
                            n += 1;
                        }
                        None => break,
                    }
                }
                char::from_u32(v).unwrap()
            }
            'c' => {
                let x = self.peek()?;
                self.i += 1;
                char::from_u32((x as u32) & 0x1F).unwrap()
            }
            _ => return None,
        };
        Some(r)
    }

    fn class_escape_prop(&mut self, c: char) -> Result<Option<(Prop, bool)>, String> {
        Ok(Some(match c {
            'd' => (Prop::Digit, false),
            'D' => (Prop::Digit, true),
            'w' => (Prop::Word, false),
            'W' => (Prop::Word, true),
            's' => (Prop::Space, false),
            'S' => (Prop::Space, true),
            'h' => (Prop::Hex, false),
            'H' => (Prop::Hex, true),
            'p' | 'P' => {
                if self.peek() != Some('{') {
                    return Ok(None);
                }
                self.i += 1;
                let mut neg = c == 'P';
                if self.eat('^') {
                    neg = !neg;
                }
                let mut name = String::new();
                while let Some(x) = self.peek() {
                    self.i += 1;
                    if x == '}' {
                        break;
                    }
                    name.push(x);
                }
                match lookup_prop(&name) {
                    Some(p) => (p, neg),
                    None => return Err(format!("invalid character property name {{{}}}", name)),
                }
            }
            _ => return Ok(None),
        }))
    }

    fn parse_escape(&mut self, f: Flags) -> Result<NodeId, String> {
        let c = match self.peek() {
            Some(c) => c,
            None => return Err("end pattern at escape".into()),
        };
        self.i += 1;
        if let Some((p, neg)) = self.class_escape_prop(c)? {
            return Ok(self.prop_class(p, neg, f));
        }
        let node = match c {
            'b' => Node::WordB,
            'B' => Node::NotWordB,
            'A' => Node::BufStart,
            'z' => Node::BufEnd,
            'Z' => Node::BufEndNl,
            'G' => Node::SearchStart,
            'K' => Node::Keep,
            'R' => {
                // (?>\r\n|[\n\v\f\r\x85\u2028\u2029])
                let cr = self.add(Node::Char('\r'));
                let nl = self.add(Node::Char('\n'));
                let crnl = self.add(Node::Seq(vec![cr, nl]));
                let cl = Class {
                    neg: false,
                    icase: false,
                    items: vec![Item::Range('\n', '\r'), Item::Range('\u{85}', '\u{85}'), Item::Range('\u{2028}', '\u{2029}')],
                    and: vec![],
                    ascii: 0,
                };
                let cln = self.class_node(cl);
                let alt = self.add(Node::Alt(vec![crnl, cln]));
                Node::Atomic(alt)
            }
            'X' => {
                let base = self.prop_class(Prop::Cats(unicode::MASK_M), true, f);
                let m = self.prop_class(Prop::Cats(unicode::MASK_M), false, f);
                let rep = self.add(Node::Repeat { node: m, min: 0, max: INF, greedy: true, possessive: false });
                let seq = self.add(Node::Seq(vec![base, rep]));
                Node::Atomic(seq)
            }
            '1'..='9' => {
                let mut num = c.to_digit(10).unwrap() as usize;
                while let Some(d) = self.peek().and_then(|x| x.to_digit(10)) {
                    let nn = num * 10 + d as usize;
                    if nn <= self.total_groups {
                        num = nn;
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                if num > self.total_groups && num >= 8 {
                    // treat as literal (octal-ish); rare
                    return Ok(self.lit(char::from_u32(num as u32).unwrap_or('?'), f));
                }
                Node::Backref { groups: vec![num], icase: f.icase }
            }
            'k' if matches!(self.peek(), Some('<') | Some('\'')) => {
                let close = if self.peek() == Some('<') { '>' } else { '\'' };
                self.i += 1;
                let name = self.parse_group_name(close)?;
                if let Ok(n) = name.parse::<i64>() {
                    let g = if n < 0 { (self.ngroups as i64 + 1 + n) as usize } else { n as usize };
                    Node::Backref { groups: vec![g], icase: f.icase }
                } else {
                    let id = self.add(Node::Backref { groups: vec![], icase: f.icase });
                    self.named_backrefs.push((id, name));
                    return Ok(id);
                }
            }
            'g' if matches!(self.peek(), Some('<') | Some('\'')) => {
                let close = if self.peek() == Some('<') { '>' } else { '\'' };
                self.i += 1;
                let name = self.parse_group_name(close)?;
                let id = self.add(Node::Call(0));
                if let Ok(n) = name.parse::<i64>() {
                    let g = if name.starts_with('-') || name.starts_with('+') {
                        if n < 0 {
                            (self.ngroups as i64 + 1 + n) as usize
                        } else {
                            (self.ngroups as i64 + n) as usize
                        }
                    } else {
                        n as usize
                    };
                    self.calls.push((id, PendingCall::Abs(g)));
                } else {
                    self.calls.push((id, PendingCall::Name(name)));
                }
                return Ok(id);
            }
            _ => {
                if let Some(ch) = self.char_escape(c, false) {
                    return Ok(self.lit(ch, f));
                }
                return Ok(self.lit(c, f));
            }
        };
        Ok(self.add(node))
    }

    fn parse_class(&mut self, f: Flags) -> Result<Class, String> {
        // '[' already consumed
        let mut neg = false;
        if self.eat('^') {
            neg = true;
        }
        let mut cl = self.parse_class_body(f, true)?;
        cl.neg = neg;
        Ok(cl)
    }

    /// Parse class contents up to and including the closing ']'.
    fn parse_class_body(&mut self, f: Flags, first: bool) -> Result<Class, String> {
        let mut items: Vec<Item> = Vec::new();
        let mut first = first;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return Err("premature end of char-class".into()),
            };
            if c == ']' && !first {
                self.i += 1;
                return Ok(Class { neg: false, icase: f.icase, items, and: vec![], ascii: 0 });
            }
            first = false;
            if c == '&' && self.peek_at(1) == Some('&') {
                self.i += 2;
                let left = Class { neg: false, icase: f.icase, items, and: vec![], ascii: 0 };
                let mut right = if self.peek() == Some('^') {
                    self.i += 1;
                    let mut r = self.parse_class_body(f, false)?;
                    r.neg = true;
                    r
                } else {
                    self.parse_class_body(f, false)?
                };
                if right.items.is_empty() && right.and.is_empty() && !right.neg {
                    // "[a&&]" -> just a
                    right = Class { neg: true, icase: f.icase, items: vec![], and: vec![], ascii: 0 };
                }
                let leftitem = if left.items.is_empty() {
                    // nothing on left: everything
                    Item::Prop(Prop::Any, false)
                } else {
                    Item::Class(Box::new(left))
                };
                return Ok(Class { neg: false, icase: f.icase, items: vec![leftitem], and: vec![right], ascii: 0 });
            }
            // parse a single element (char or class-escape or nested class)
            let start_char: Option<char>;
            if c == '[' {
                self.i += 1;
                if self.peek() == Some(':') {
                    // POSIX bracket?
                    let save = self.i;
                    self.i += 1;
                    let mut pneg = false;
                    if self.eat('^') {
                        pneg = true;
                    }
                    let mut name = String::new();
                    while let Some(x) = self.peek() {
                        if x.is_ascii_alphabetic() {
                            name.push(x);
                            self.i += 1;
                        } else {
                            break;
                        }
                    }
                    if self.peek() == Some(':') && self.peek_at(1) == Some(']') {
                        if let Some(p) = lookup_prop(&name) {
                            self.i += 2;
                            items.push(Item::Prop(p, pneg));
                            continue;
                        }
                    }
                    self.i = save;
                }
                let sub = self.parse_class(f)?;
                items.push(Item::Class(Box::new(sub)));
                continue;
            } else if c == '\\' {
                self.i += 1;
                let e = match self.peek() {
                    Some(e) => e,
                    None => return Err("end pattern at escape".into()),
                };
                self.i += 1;
                if let Some((p, n)) = self.class_escape_prop(e)? {
                    items.push(Item::Prop(p, n));
                    continue;
                }
                if let Some(ch) = self.char_escape(e, true) {
                    start_char = Some(ch);
                } else if e.is_ascii_digit() {
                    // octal
                    let mut v = e.to_digit(8).unwrap_or(0);
                    let mut n = 0;
                    while n < 2 {
                        match self.peek().and_then(|c| c.to_digit(8)) {
                            Some(d) => {
                                v = v * 8 + d;
                                self.i += 1;
                                n += 1;
                            }
                            None => break,
                        }
                    }
                    start_char = char::from_u32(v);
                } else {
                    start_char = Some(e);
                }
            } else {
                self.i += 1;
                start_char = Some(c);
            }
            let a = start_char.unwrap();
            // range?
            if self.peek() == Some('-') && self.peek_at(1).is_some() && self.peek_at(1) != Some(']') {
                let save = self.i;
                self.i += 1;
                let bc = self.peek().unwrap();
                let b: Option<char> = if bc == '\\' {
                    self.i += 1;
                    let e = self.peek().unwrap_or('\\');
                    self.i += 1;
                    if matches!(e, 'd' | 'D' | 'w' | 'W' | 's' | 'S' | 'h' | 'H' | 'p' | 'P') {
                        None
                    } else if let Some(ch) = self.char_escape(e, true) {
                        Some(ch)
                    } else {
                        Some(e)
                    }
                } else if bc == '[' {
                    None
                } else {
                    self.i += 1;
                    Some(bc)
                };
                match b {
                    Some(b) => {
                        if b >= a {
                            items.push(Item::Range(a, b));
                        } else {
                            return Err("empty range in char class".into());
                        }
                        continue;
                    }
                    None => {
                        self.i = save;
                        items.push(Item::Range(a, a));
                        // '-' will be parsed as literal next
                        continue;
                    }
                }
            }
            items.push(Item::Range(a, a));
        }
    }

    /// Compute (min,max) width in chars of a node (for lookbehind).
    fn width(&self, id: NodeId) -> (usize, usize) {
        match &self.nodes[id] {
            Node::Empty => (0, 0),
            Node::Char(_) | Node::CharI(_) | Node::Any | Node::AnyNl | Node::Class(_) => (1, 1),
            Node::Seq(v) => {
                let mut a = 0usize;
                let mut b = 0usize;
                for &x in v {
                    let (p, q) = self.width(x);
                    a += p;
                    b = b.saturating_add(q);
                }
                (a, b)
            }
            Node::Alt(v) => {
                let mut a = usize::MAX;
                let mut b = 0;
                for &x in v {
                    let (p, q) = self.width(x);
                    a = a.min(p);
                    b = b.max(q);
                }
                (a, b)
            }
            Node::Group(_, n) | Node::Atomic(n) => self.width(*n),
            Node::Repeat { node, min, max, .. } => {
                let (p, q) = self.width(*node);
                let mx = if *max == INF { if q == 0 { 0 } else { usize::MAX } } else { q.saturating_mul(*max as usize) };
                (p.saturating_mul(*min as usize), mx)
            }
            Node::Look { .. } => (0, 0),
            Node::Backref { .. } | Node::Call(_) => (0, 10000),
            _ => (0, 0),
        }
    }
}

struct FirstInfo {
    nullable: bool,
    set: [bool; 128],
    nonascii: bool,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let total = count_groups(&chars);
        let mut p = Parser {
            c: chars,
            i: 0,
            nodes: Vec::new(),
            ngroups: 0,
            total_groups: total,
            names: Vec::new(),
            group_nodes: vec![0],
            calls: Vec::new(),
            named_backrefs: Vec::new(),
            _p: std::marker::PhantomData,
        };
        let f = Flags { icase: false, extended: false, dotall: false };
        let mut root = p.parse_alt(f)?;
        while p.i < p.c.len() {
            // unmatched ')': treat as literal and continue
            if p.peek() == Some(')') {
                p.i += 1;
                let lit = p.add(Node::Char(')'));
                let rest = p.parse_alt(f)?;
                root = p.add(Node::Seq(vec![root, lit, rest]));
            } else {
                break;
            }
        }
        p.group_nodes[0] = root;
        p.group_nodes.resize(p.ngroups + 1, 0);
        // resolve calls
        let calls = std::mem::take(&mut p.calls);
        for (id, pc) in calls {
            let g = match pc {
                PendingCall::Abs(g) => g,
                PendingCall::Name(n) => match p.names.iter().rev().find(|(nm, _)| *nm == n) {
                    Some((_, g)) => *g,
                    None => return Err(format!("undefined name <{}> reference", n)),
                },
            };
            if g > p.ngroups {
                return Err("undefined group reference".into());
            }
            p.nodes[id] = Node::Call(g);
        }
        let nbr = std::mem::take(&mut p.named_backrefs);
        for (id, name) in nbr {
            let groups: Vec<usize> = p.names.iter().filter(|(nm, _)| *nm == name).map(|(_, g)| *g).collect();
            if groups.is_empty() {
                return Err(format!("undefined name <{}> reference", name));
            }
            if let Node::Backref { icase, .. } = p.nodes[id] {
                p.nodes[id] = Node::Backref { groups, icase };
            }
        }
        let mut re = Regex {
            nodes: p.nodes,
            root,
            ngroups: p.ngroups,
            group_nodes: p.group_nodes,
            first: None,
            first_nonascii: true,
            anchor: Anchor::None,
            pattern: pattern.to_string(),
        };
        let fi = re.first_info(root, 0);
        if !fi.nullable {
            re.first = Some(Box::new(fi.set));
            re.first_nonascii = fi.nonascii;
        }
        re.anchor = re.find_anchor(root);
        Ok(re)
    }

    pub fn pattern(&self) -> &str {
        &self.pattern
    }

    pub fn captures_len(&self) -> usize {
        self.ngroups + 1
    }

    fn find_anchor(&self, id: NodeId) -> Anchor {
        match &self.nodes[id] {
            Node::LineStart => Anchor::LineStart,
            Node::BufStart => Anchor::BufStart,
            Node::SearchStart => Anchor::SearchStart,
            Node::Seq(v) => {
                if v.is_empty() {
                    Anchor::None
                } else {
                    self.find_anchor(v[0])
                }
            }
            Node::Group(_, n) | Node::Atomic(n) => self.find_anchor(*n),
            Node::Alt(v) => {
                let first = self.find_anchor(v[0]);
                if first != Anchor::None && v.iter().all(|&x| self.find_anchor(x) == first) {
                    first
                } else {
                    Anchor::None
                }
            }
            _ => Anchor::None,
        }
    }

    fn first_info(&self, id: NodeId, depth: usize) -> FirstInfo {
        let all = || FirstInfo { nullable: true, set: [true; 128], nonascii: true };
        if depth > 50 {
            return all();
        }
        match &self.nodes[id] {
            Node::Empty | Node::LineStart | Node::LineEnd | Node::BufStart | Node::BufEnd | Node::BufEndNl
            | Node::WordB | Node::NotWordB | Node::SearchStart | Node::Keep | Node::Look { .. } => {
                FirstInfo { nullable: true, set: [false; 128], nonascii: false }
            }
            Node::Char(c) => {
                let mut set = [false; 128];
                let mut nonascii = false;
                if (*c as u32) < 128 {
                    set[*c as usize] = true;
                } else {
                    nonascii = true;
                }
                FirstInfo { nullable: false, set, nonascii }
            }
            Node::CharI(c) => {
                let mut set = [false; 128];
                let mut nonascii = false;
                for v in case_variants(*c) {
                    if (v as u32) < 128 {
                        set[v as usize] = true;
                    } else {
                        nonascii = true;
                    }
                }
                FirstInfo { nullable: false, set, nonascii }
            }
            Node::Any => {
                let mut set = [true; 128];
                set[10] = false;
                FirstInfo { nullable: false, set, nonascii: true }
            }
            Node::AnyNl => FirstInfo { nullable: false, set: [true; 128], nonascii: true },
            Node::Class(cl) => {
                let mut set = [false; 128];
                for (i, s) in set.iter_mut().enumerate() {
                    *s = (cl.ascii >> i) & 1 == 1;
                }
                FirstInfo { nullable: false, set, nonascii: true }
            }
            Node::Seq(v) => {
                let mut set = [false; 128];
                let mut nonascii = false;
                for &x in v {
                    let fi = self.first_info(x, depth + 1);
                    for i in 0..128 {
                        set[i] |= fi.set[i];
                    }
                    nonascii |= fi.nonascii;
                    if !fi.nullable {
                        return FirstInfo { nullable: false, set, nonascii };
                    }
                }
                FirstInfo { nullable: true, set, nonascii }
            }
            Node::Alt(v) => {
                let mut set = [false; 128];
                let mut nonascii = false;
                let mut nullable = false;
                for &x in v {
                    let fi = self.first_info(x, depth + 1);
                    for i in 0..128 {
                        set[i] |= fi.set[i];
                    }
                    nonascii |= fi.nonascii;
                    nullable |= fi.nullable;
                }
                FirstInfo { nullable, set, nonascii }
            }
            Node::Group(_, n) | Node::Atomic(n) => self.first_info(*n, depth + 1),
            Node::Repeat { node, min, .. } => {
                let mut fi = self.first_info(*node, depth + 1);
                if *min == 0 {
                    fi.nullable = true;
                }
                fi
            }
            Node::Backref { .. } | Node::Call(_) => all(),
        }
    }

    /// Search for a match starting at or after `start`. `text[..]` is the full subject.
    pub fn search(&self, text: &str, start: usize, region: &mut Region) -> bool {
        let bytes = text.as_bytes();
        let end = bytes.len();
        let mut m = Matcher {
            re: self,
            text: bytes,
            search_start: start,
            caps: vec![UNSET; 2 * (self.ngroups + 1)],
            keep: start,
            depth: 0,
        };
        let mut s = start;
        loop {
            if s > end {
                return false;
            }
            let try_here = match self.anchor {
                Anchor::SearchStart => s == start,
                Anchor::BufStart => s == 0,
                Anchor::LineStart => s == 0 || bytes[s - 1] == b'\n',
                Anchor::None => true,
            } && match &self.first {
                None => true,
                Some(set) => {
                    if s >= end {
                        false
                    } else {
                        let b = bytes[s];
                        if b < 128 {
                            set[b as usize]
                        } else {
                            self.first_nonascii
                        }
                    }
                }
            };
            if try_here {
                for c in m.caps.iter_mut() {
                    *c = UNSET;
                }
                m.keep = s;
                let mut match_end = UNSET;
                let ok = m.m(self.root, s, &mut |_, p| {
                    match_end = p;
                    true
                });
                if ok {
                    region.pos.clear();
                    region.pos.push(m.keep);
                    region.pos.push(match_end);
                    region.pos.extend_from_slice(&m.caps[2..]);
                    return true;
                }
            }
            match self.anchor {
                Anchor::SearchStart | Anchor::BufStart => {
                    if s >= start && (self.anchor == Anchor::SearchStart || s >= 0) {
                        if self.anchor == Anchor::SearchStart || s > 0 {
                            return false;
                        }
                    }
                }
                _ => {}
            }
            if s >= end {
                return false;
            }
            // advance to next char boundary
            s += 1;
            while s < end && (bytes[s] & 0xC0) == 0x80 {
                s += 1;
            }
            if self.anchor == Anchor::LineStart {
                // jump to next line start
                while s < end && bytes[s - 1] != b'\n' {
                    s += 1;
                }
                if s >= end && bytes[end - 1] != b'\n' {
                    return false;
                }
            }
        }
    }

    pub fn is_match(&self, text: &str) -> bool {
        let mut r = Region::new();
        self.search(text, 0, &mut r)
    }
}

struct Matcher<'a> {
    re: &'a Regex,
    text: &'a [u8],
    search_start: usize,
    caps: Vec<usize>,
    keep: usize,
    depth: usize,
}

#[inline]
fn decode_at(t: &[u8], pos: usize) -> Option<(char, usize)> {
    if pos >= t.len() {
        return None;
    }
    let b0 = t[pos];
    if b0 < 0x80 {
        return Some((b0 as char, pos + 1));
    }
    let (len, init) = if b0 >= 0xF0 {
        (4, (b0 & 0x07) as u32)
    } else if b0 >= 0xE0 {
        (3, (b0 & 0x0F) as u32)
    } else {
        (2, (b0 & 0x1F) as u32)
    };
    if pos + len > t.len() {
        return Some(('\u{FFFD}', t.len()));
    }
    let mut v = init;
    for k in 1..len {
        v = (v << 6) | (t[pos + k] & 0x3F) as u32;
    }
    Some((char::from_u32(v).unwrap_or('\u{FFFD}'), pos + len))
}

#[inline]
fn prev_boundary(t: &[u8], pos: usize) -> usize {
    let mut p = pos - 1;
    while p > 0 && (t[p] & 0xC0) == 0x80 {
        p -= 1;
    }
    p
}

#[inline]
fn char_before(t: &[u8], pos: usize) -> Option<char> {
    if pos == 0 {
        None
    } else {
        decode_at(t, prev_boundary(t, pos)).map(|x| x.0)
    }
}

type Cont<'k, 'a> = dyn FnMut(&mut Matcher<'a>, usize) -> bool + 'k;

impl<'a> Matcher<'a> {
    #[inline]
    fn single(&self, id: NodeId, pos: usize) -> Option<usize> {
        let (c, np) = decode_at(self.text, pos)?;
        let ok = match &self.re.nodes[id] {
            Node::Char(x) => c == *x,
            Node::CharI(x) => fold(c) == *x,
            Node::Any => c != '\n',
            Node::AnyNl => true,
            Node::Class(cl) => cl.matches(c),
            _ => unreachable!(),
        };
        if ok {
            Some(np)
        } else {
            None
        }
    }

    fn is_single(&self, id: NodeId) -> bool {
        matches!(self.re.nodes[id], Node::Char(_) | Node::CharI(_) | Node::Any | Node::AnyNl | Node::Class(_))
    }

    fn seq(&mut self, items: &'a [NodeId], i: usize, pos: usize, k: &mut Cont<'_, 'a>) -> bool {
        if i == items.len() {
            return k(self, pos);
        }
        let id = items[i];
        // fast path for single-char items
        if self.is_single(id) {
            return match self.single(id, pos) {
                Some(np) => self.seq(items, i + 1, np, k),
                None => false,
            };
        }
        self.m(id, pos, &mut |s: &mut Matcher<'a>, p| s.seq(items, i + 1, p, k))
    }

    #[allow(clippy::too_many_arguments)]
    fn rep(&mut self, node: NodeId, min: u32, max: u32, greedy: bool, count: u32, pos: usize, k: &mut Cont<'_, 'a>) -> bool {
        if greedy {
            if count < max {
                let r = self.m(node, pos, &mut |s: &mut Matcher<'a>, p| {
                    if p == pos && count >= min {
                        return false;
                    }
                    s.rep(node, min, max, greedy, count + 1, p, k)
                });
                if r {
                    return true;
                }
            }
            if count >= min {
                return k(self, pos);
            }
            false
        } else {
            if count >= min && k(self, pos) {
                return true;
            }
            if count < max {
                return self.m(node, pos, &mut |s: &mut Matcher<'a>, p| {
                    if p == pos && count >= min {
                        return false;
                    }
                    s.rep(node, min, max, greedy, count + 1, p, k)
                });
            }
            false
        }
    }

    fn m(&mut self, id: NodeId, pos: usize, k: &mut Cont<'_, 'a>) -> bool {
        let re = self.re;
        match &re.nodes[id] {
            Node::Empty => k(self, pos),
            Node::Char(_) | Node::CharI(_) | Node::Any | Node::AnyNl | Node::Class(_) => match self.single(id, pos) {
                Some(np) => k(self, np),
                None => false,
            },
            Node::Seq(items) => self.seq(items, 0, pos, k),
            Node::Alt(alts) => {
                for &a in alts {
                    if self.m(a, pos, k) {
                        return true;
                    }
                }
                false
            }
            Node::Group(gi, inner) => {
                let gi = *gi;
                let inner = *inner;
                self.depth += 1;
                if self.depth > 20000 {
                    self.depth -= 1;
                    return false;
                }
                let r = self.m(inner, pos, &mut |s: &mut Matcher<'a>, p| {
                    let o0 = s.caps[2 * gi];
                    let o1 = s.caps[2 * gi + 1];
                    s.caps[2 * gi] = pos;
                    s.caps[2 * gi + 1] = p;
                    if k(s, p) {
                        return true;
                    }
                    s.caps[2 * gi] = o0;
                    s.caps[2 * gi + 1] = o1;
                    false
                });
                self.depth -= 1;
                r
            }
            Node::Repeat { node, min, max, greedy, possessive } => {
                let (node, min, max, greedy, possessive) = (*node, *min, *max, *greedy, *possessive);
                if self.is_single(node) {
                    // collect run
                    let mut n = 0u32;
                    let mut p = pos;
                    if greedy || possessive {
                        while n < max {
                            match self.single(node, p) {
                                Some(np) => {
                                    p = np;
                                    n += 1;
                                }
                                None => break,
                            }
                        }
                        if n < min {
                            return false;
                        }
                        if possessive {
                            return k(self, p);
                        }
                        loop {
                            if k(self, p) {
                                return true;
                            }
                            if n == min {
                                return false;
                            }
                            p = prev_boundary(self.text, p);
                            n -= 1;
                        }
                    } else {
                        loop {
                            if n >= min && k(self, p) {
                                return true;
                            }
                            if n >= max {
                                return false;
                            }
                            match self.single(node, p) {
                                Some(np) => {
                                    p = np;
                                    n += 1;
                                }
                                None => return false,
                            }
                        }
                    }
                }
                if possessive {
                    let saved = self.caps.clone();
                    let mut endp = UNSET;
                    let ok = self.rep(node, min, max, true, 0, pos, &mut |_, p| {
                        endp = p;
                        true
                    });
                    if !ok {
                        return false;
                    }
                    if k(self, endp) {
                        return true;
                    }
                    self.caps = saved;
                    return false;
                }
                self.rep(node, min, max, greedy, 0, pos, k)
            }
            Node::Atomic(inner) => {
                let saved = self.caps.clone();
                let saved_keep = self.keep;
                let mut endp = UNSET;
                let ok = self.m(*inner, pos, &mut |_, p| {
                    endp = p;
                    true
                });
                if !ok {
                    return false;
                }
                if k(self, endp) {
                    return true;
                }
                self.caps = saved;
                self.keep = saved_keep;
                false
            }
            Node::Look { behind, neg, node, minlen, maxlen } => {
                let (behind, neg, node, minlen, maxlen) = (*behind, *neg, *node, *minlen, *maxlen);
                let saved = self.caps.clone();
                let saved_keep = self.keep;
                let found = if !behind {
                    self.m(node, pos, &mut |_, _| true)
                } else {
                    let mut found = false;
                    let mut s = pos;
                    let mut nchars = 0usize;
                    loop {
                        if nchars >= minlen && self.m(node, s, &mut |_, p| p == pos) {
                            found = true;
                            break;
                        }
                        if nchars >= maxlen || s == 0 {
                            break;
                        }
                        s = prev_boundary(self.text, s);
                        nchars += 1;
                    }
                    found
                };
                self.keep = saved_keep;
                if neg {
                    self.caps = saved;
                    if found {
                        return false;
                    }
                    k(self, pos)
                } else {
                    if !found {
                        self.caps = saved;
                        return false;
                    }
                    if k(self, pos) {
                        return true;
                    }
                    self.caps = saved;
                    false
                }
            }
            Node::Backref { groups, icase } => {
                for &g in groups.iter().rev() {
                    if 2 * g + 1 >= self.caps.len() {
                        continue;
                    }
                    let (a, b) = (self.caps[2 * g], self.caps[2 * g + 1]);
                    if a == UNSET || b == UNSET {
                        continue;
                    }
                    let t = self.text;
                    if !*icase {
                        let len = b - a;
                        if pos + len <= t.len() && t[a..b] == t[pos..pos + len] {
                            return k(self, pos + len);
                        }
                        return false;
                    } else {
                        let mut i = a;
                        let mut p = pos;
                        while i < b {
                            let (c1, ni) = decode_at(t, i).unwrap();
                            match decode_at(t, p) {
                                Some((c2, np)) if fold(c1) == fold(c2) => {
                                    i = ni;
                                    p = np;
                                }
                                _ => return false,
                            }
                        }
                        return k(self, p);
                    }
                }
                false
            }
            Node::Call(g) => {
                let target = re.group_nodes[*g];
                self.depth += 1;
                if self.depth > 20000 {
                    self.depth -= 1;
                    return false;
                }
                let r = self.m(target, pos, k);
                self.depth -= 1;
                r
            }
            Node::LineStart => {
                if pos == 0 || self.text[pos - 1] == b'\n' {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::LineEnd => {
                if pos == self.text.len() || self.text[pos] == b'\n' {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::BufStart => {
                if pos == 0 {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::BufEnd => {
                if pos == self.text.len() {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::BufEndNl => {
                let l = self.text.len();
                if pos == l || (pos + 1 == l && self.text[pos] == b'\n') {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::WordB | Node::NotWordB => {
                let a = char_before(self.text, pos).map(is_word).unwrap_or(false);
                let b = decode_at(self.text, pos).map(|x| is_word(x.0)).unwrap_or(false);
                let at = a != b;
                let want = matches!(re.nodes[id], Node::WordB);
                if at == want {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::SearchStart => {
                if pos == self.search_start {
                    k(self, pos)
                } else {
                    false
                }
            }
            Node::Keep => {
                let old = self.keep;
                self.keep = pos;
                if k(self, pos) {
                    return true;
                }
                self.keep = old;
                false
            }
        }
    }
}

/// Escape a string so that it matches literally.
pub fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        if matches!(c, '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '|' | '[' | ']' | '{' | '}' | '^' | '$' | '#' | '-' | ' ') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    fn find(p: &str, t: &str) -> Option<(usize, usize)> {
        let re = Regex::new(p).unwrap();
        let mut r = Region::new();
        if re.search(t, 0, &mut r) {
            r.get(0)
        } else {
            None
        }
    }
    #[test]
    fn basics() {
        assert_eq!(find("abc", "xxabcx"), Some((2, 5)));
        assert_eq!(find("a+", "baaa"), Some((1, 4)));
        assert_eq!(find("a+?", "baaa"), Some((1, 2)));
        assert_eq!(find("(?i)ABC", "xabc"), Some((1, 4)));
        assert_eq!(find("^b", "a\nb"), Some((2, 3)));
        assert_eq!(find("a$", "a\nb"), Some((0, 1)));
        assert_eq!(find("(?<=a)b", "abab"), Some((1, 2)));
        assert_eq!(find("(?<!a)b", "abcb"), Some((3, 4)));
        assert_eq!(find("(a)\\1", "xaa"), Some((1, 3)));
        assert_eq!(find("\\((?>[^()]+|\\g<0>)*\\)", "x(a(b)c)"), Some((1, 8)));
        assert_eq!(find("[[:alpha:]]+", "12ab3"), Some((2, 4)));
        assert_eq!(find("[a-z&&[^aeiou]]+", "aabcd"), Some((2, 4)));
        assert_eq!(find("(?x) a b # comment\n c", "abc"), Some((0, 3)));
        assert_eq!(find("\\p{L}+", "12éa3"), Some((2, 5)));
        assert_eq!(find("a{2,3}", "aaaa"), Some((0, 3)));
