//! Scopes are dot-separated lists of atoms ("source.rust", "string.quoted.double").
//! Atoms are interned so that a scope is a small `Copy` value.

use std::cell::RefCell;
use std::collections::HashMap;

pub const MAX_ATOMS: usize = 8;

#[derive(Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct Scope {
    atoms: [u16; MAX_ATOMS],
    len: u8,
}

struct Repo {
    atoms: Vec<String>,
    map: HashMap<String, u16>,
}

thread_local! {
    static REPO: RefCell<Repo> = RefCell::new(Repo { atoms: vec![String::new()], map: HashMap::new() });
}

fn intern(a: &str) -> u16 {
    REPO.with(|r| {
        let mut r = r.borrow_mut();
        if let Some(&i) = r.map.get(a) {
            return i;
        }
        let i = r.atoms.len() as u16;
        r.atoms.push(a.to_string());
        r.map.insert(a.to_string(), i);
        i
    })
}

impl Scope {
    pub fn new(s: &str) -> Scope {
        let mut sc = Scope::default();
        let s = s.trim();
        if s.is_empty() {
            return sc;
        }
        for part in s.split('.') {
            if (sc.len as usize) >= MAX_ATOMS {
                break;
            }
            sc.atoms[sc.len as usize] = intern(part);
            sc.len += 1;
        }
        sc
    }

    #[inline]
    pub fn len(&self) -> u32 {
        self.len as u32
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    #[inline]
    pub fn is_prefix_of(&self, other: Scope) -> bool {
        let n = self.len as usize;
        if n > other.len as usize {
            return false;
        }
        self.atoms[..n] == other.atoms[..n]
    }

    pub fn build_string(&self) -> String {
        REPO.with(|r| {
            let r = r.borrow();
            let parts: Vec<&str> = self.atoms[..self.len as usize].iter().map(|&a| r.atoms[a as usize].as_str()).collect();
            parts.join(".")
        })
    }
}

impl std::fmt::Debug for Scope {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "<{}>", self.build_string())
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ClearAmount {
    TopN(usize),
    All,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ScopeStackOp {
    Push(Scope),
    Pop(usize),
    Clear(ClearAmount),
    Restore,
    Noop,
}

pub enum BasicOp {
    Push,
    Pop,
}

#[derive(Clone, Debug, Default)]
pub struct ScopeStack {
    clear_stack: Vec<Vec<Scope>>,
    pub scopes: Vec<Scope>,
}

impl ScopeStack {
    pub fn new() -> ScopeStack {
        ScopeStack::default()
    }

    pub fn as_slice(&self) -> &[Scope] {
        &self.scopes
    }

    /// Apply an operation, calling `hook` for every elementary push/pop.
    /// Returns false if the operation could not be applied.
    pub fn apply_with_hook<F: FnMut(BasicOp, &[Scope])>(&mut self, op: &ScopeStackOp, mut hook: F) -> bool {
        match op {
            ScopeStackOp::Push(s) => {
                self.scopes.push(*s);
                hook(BasicOp::Push, &self.scopes);
            }
            ScopeStackOp::Pop(n) => {
                for _ in 0..*n {
                    self.scopes.pop();
                    hook(BasicOp::Pop, &self.scopes);
                }
            }
            ScopeStackOp::Clear(amount) => {
                let cleared = match amount {
                    ClearAmount::TopN(n) => {
                        let to_leave = self.scopes.len() - (*n).min(self.scopes.len());
                        self.scopes.split_off(to_leave)
                    }
                    ClearAmount::All => std::mem::take(&mut self.scopes),
                };
                let n = cleared.len();
                self.clear_stack.push(cleared);
                for _ in 0..n {
                    hook(BasicOp::Pop, &self.scopes);
                }
            }
            ScopeStackOp::Restore => match self.clear_stack.pop() {
                Some(to_push) => {
                    for s in to_push {
                        self.scopes.push(s);
                        hook(BasicOp::Push, &self.scopes);
                    }
                }
                None => return false,
            },
            ScopeStackOp::Noop => {}
        }
        true
    }
}
