fn read_ctx_id(r: &mut Reader) -> Res<ContextId> {
    let syntax = r.usize()?;
    let index = r.usize()?;
    Ok(ContextId { syntax, index })
}

fn read_ctx_ref(r: &mut Reader) -> Res<ContextRef> {
    let tag = r.u32()?;
    Ok(match tag {
        0 => {
            r.string()?;
            ContextRef::Unresolved
        }
        1 => {
            r.string()?;
            r.option(|r| r.string())?;
            r.bool()?;
            ContextRef::Unresolved
        }
        2 => {
            r.string()?;
            r.option(|r| r.string())?;
            r.bool()?;
            ContextRef::Unresolved
        }
        3 => {
            r.string()?;
            ContextRef::Unresolved
        }
        4 => ContextRef::Direct(read_ctx_id(r)?),
        _ => return Err(format!("bad context reference tag {}", tag)),
    })
}

fn read_scopes(r: &mut Reader) -> Res<Vec<Scope>> {
    r.vec(|r| Ok(Scope::new(&r.string()?)))
}

fn read_op(r: &mut Reader) -> Res<MatchOperation> {
    let tag = r.u32()?;
    Ok(match tag {
        0 => MatchOperation::Push(r.vec(read_ctx_ref)?),
        1 => MatchOperation::Set(r.vec(read_ctx_ref)?),
        2 => MatchOperation::Pop,
        3 => MatchOperation::None,
        _ => return Err(format!("bad match operation tag {}", tag)),
    })
}

fn read_pattern(r: &mut Reader) -> Res<Pattern> {
    let tag = r.u32()?;
    Ok(match tag {
        0 => {
            let has_captures = r.bool()?;
            let regex_str = r.string()?;
            let scope = read_scopes(r)?;
            let captures = r.option(|r| r.vec(|r| Ok((r.usize()?, read_scopes(r)?))))?;
            let operation = read_op(r)?;
            let with_prototype = r.option(read_ctx_ref)?;
            Pattern::Match(MatchPattern { has_captures, regex_str, regex: OnceCell::new(), scope, captures, operation, with_prototype })
        }
        1 => Pattern::Include(read_ctx_ref(r)?),
        _ => return Err(format!("bad pattern tag {}", tag)),
    })
}

fn read_context(r: &mut Reader) -> Res<Context> {
    let meta_scope = read_scopes(r)?;
    let meta_content_scope = read_scopes(r)?;
    let meta_include_prototype = r.bool()?;
    let clear_scopes = r.option(|r| {
        let t = r.u32()?;
        Ok(match t {
            0 => ClearAmount::TopN(r.usize()?),
            _ => ClearAmount::All,
        })
    })?;
    let prototype = r.option(read_ctx_id)?;
    let uses_backrefs = r.bool()?;
    let patterns = r.vec(read_pattern)?;
    Ok(Context { meta_scope, meta_content_scope, meta_include_prototype, clear_scopes, prototype, uses_backrefs, patterns })
}

impl SyntaxSet {
    pub fn from_dump(data: &[u8]) -> Res<SyntaxSet> {
        let mut r = Reader::new(data);
        let n = r.usize()?;
        let mut syntaxes = Vec::with_capacity(n);
        for _ in 0..n {
            let name = r.string()?;
            let file_extensions = r.vec(|r| r.string())?;
            let scope = Scope::new(&r.string()?);
            let first_line_match = r.option(|r| r.string())?;
            let hidden = r.bool()?;
            let nvars = r.usize()?;
            for _ in 0..nvars {
                r.string()?;
                r.string()?;
            }
            let data = r.bytes()?.to_vec();
            syntaxes.push(SyntaxDef {
                name,
                file_extensions,
                scope,
                first_line_match,
                first_line_regex: OnceCell::new(),
                hidden,
                data,
                contexts: OnceCell::new(),
            });
        }
        Ok(SyntaxSet { syntaxes })
    }

    fn contexts_of(&self, syntax: usize) -> &SyntaxContexts {
        self.syntaxes[syntax].contexts.get_or_init(|| {
            let raw = zlib_decode(&self.syntaxes[syntax].data).expect("corrupt syntax data");
            let mut r = Reader::new(&raw);
            let n = r.usize().unwrap();
            let mut ids = HashMap::new();
            for _ in 0..n {
                let k = r.string().unwrap();
                let id = read_ctx_id(&mut r).unwrap();
                ids.insert(k, id.index);
            }
            let contexts = r.vec(read_context).expect("corrupt syntax contexts");
            SyntaxContexts { ids, contexts }
        })
    }

    pub fn get_context(&self, id: ContextId) -> &Context {
        &self.contexts_of(id.syntax).contexts[id.index]
    }

    pub fn context_id_by_name(&self, syntax: usize, name: &str) -> Option<ContextId> {
        self.contexts_of(syntax).ids.get(name).map(|&index| ContextId { syntax, index })
    }

    pub fn start_context(&self, syntax: usize) -> ContextId {
        self.context_id_by_name(syntax, "__start").expect("syntax without __start context")
    }

    pub fn find_by_name(&self, name: &str) -> Option<usize> {
        self.syntaxes.iter().position(|s| s.name == name)
    }

    pub fn find_by_extension(&self, ext: &str) -> Option<usize> {
        self.syntaxes.iter().rposition(|s| s.file_extensions.iter().any(|e| e.eq_ignore_ascii_case(ext)))
    }

    pub fn find_by_token(&self, token: &str) -> Option<usize> {
        if let Some(i) = self.find_by_extension(token) {
            return Some(i);
        }
        self.syntaxes.iter().rposition(|s| s.name.eq_ignore_ascii_case(token))
    }

    pub fn find_by_first_line(&self, line: &str) -> Option<usize> {
        let line = line.strip_prefix('\u{feff}').unwrap_or(line);
        for i in (0..self.syntaxes.len()).rev() {
            if let Some(re) = self.syntaxes[i].first_line_regex() {
                if re.is_match(line) {
                    return Some(i);
                }
            }
        }
        None
    }

    pub fn plain_text(&self) -> usize {
        self.find_by_name("Plain Text").unwrap_or(0)
    }
}
