            let cur = &self.stack[self.stack.len() - 1];
            let ctx = set.get_context(cur.context);
            if !ctx.meta_content_scope.is_empty() {
                res.push((0, ScopeStackOp::Push(ctx.meta_content_scope[0])));
            }
            self.first_line = false;
        }
        let mut cache: SearchCache = HashMap::with_capacity(128);
        let mut non_consuming_push_at = (0usize, 0usize);
        let mut guard = 0usize;
        while self.parse_next_token(line, set, &mut match_start, &mut cache, &mut non_consuming_push_at, &mut res) {
            guard += 1;
            if guard > 1_000_000 {
                break;
            }
        }
        res
    }

    fn parse_next_token(
        &mut self,
        line: &str,
        set: &SyntaxSet,
        start: &mut usize,
        cache: &mut SearchCache,
        non_consuming_push_at: &mut (usize, usize),
        ops: &mut Vec<(usize, ScopeStackOp)>,
    ) -> bool {
        if self.stack.is_empty() {
            return false;
        }
        let check_pop_loop = {
            let (pos, depth) = *non_consuming_push_at;
            pos == *start && depth == self.stack.len()
        };
        while self.proto_starts.last().map(|&s| s >= self.stack.len()).unwrap_or(false) {
            self.proto_starts.pop();
        }
        let best = self.find_best_match(line, *start, set, cache, check_pop_loop);
        let reg_match = match best {
            Some(m) => m,
            None => return false,
        };
        if reg_match.would_loop {
            let mut it = line[*start..].char_indices();
            it.next();
            if let Some((i, _)) = it.next() {
                *start += i;
                return true;
            } else {
                return false;
            }
        }
        let match_end = reg_match.regions.get(0).unwrap().1;
        let consuming = match_end > *start;
        if !consuming {
            let pat = match_at(reg_match.context, reg_match.pat_index);
            if let MatchOperation::Push(_) = pat.operation {
                *non_consuming_push_at = (match_end, self.stack.len() + 1);
            }
        }
        *start = match_end;
        if reg_match.from_with_prototype {
            self.proto_starts.push(self.stack.len());
        }
        let level_context = set.get_context(self.stack[self.stack.len() - 1].context);
        self.exec_pattern(line, &reg_match, level_context, set, ops);
        true
    }

    fn find_best_match<'a>(
        &self,
        line: &str,
        start: usize,
        set: &'a SyntaxSet,
        cache: &mut SearchCache,
        check_pop_loop: bool,
    ) -> Option<RegexMatch<'a>> {
        let cur = &self.stack[self.stack.len() - 1];
        let context = set.get_context(cur.context);
        let proto_start = self.proto_starts.last().cloned().unwrap_or(0);
        let mut chain: Vec<(bool, ContextId, Option<&(Region, String)>)> = Vec::new();
        for lvl in &self.stack[proto_start..] {
            for p in &lvl.prototypes {
                chain.push((true, *p, lvl.captures.as_ref()));
            }
        }
        if let Some(p) = context.prototype {
            chain.push((false, p, None));
        }
        chain.push((false, cur.context, cur.captures.as_ref()));

        let mut min_start = usize::MAX;
        let mut best: Option<RegexMatch<'a>> = None;
        let mut pop_would_loop = false;
        for (from_proto, ctx_id, captures) in chain {
            let ctx = set.get_context(ctx_id);
            let it = ContextIter { set, stack: vec![(ctx, 0)] };
            for (pat_ctx, pat_index) in it {
                let pat = match_at(pat_ctx, pat_index);
                if let Some(region) = self.search(line, start, pat, captures, cache) {
                    let (ms, me) = region.get(0).unwrap();
                    if ms < min_start || (ms == min_start && pop_would_loop) {
                        min_start = ms;
                        let consuming = me > start;
                        pop_would_loop = check_pop_loop && !consuming && matches!(pat.operation, MatchOperation::Pop);
                        best = Some(RegexMatch {
                            regions: region,
                            context: pat_ctx,
                            pat_index,
                            from_with_prototype: from_proto,
                            would_loop: pop_would_loop,
                        });
                        if ms == start && !pop_would_loop {
                            return best;
                        }
                    }
                }
            }
        }
        best
    }

    fn search(
        &self,
        line: &str,
        start: usize,
        pat: &MatchPattern,
        captures: Option<&(Region, String)>,
        cache: &mut SearchCache,
    ) -> Option<Region> {
        let key = pat as *const MatchPattern;
        if let Some(entry) = cache.get(&key) {
            match entry {
                Some(region) => {
                    let ms = region.get(0).unwrap().0;
                    if ms >= start {
                        return Some(region.clone());
                    }
                }
                None => return None,
            }
        }
        let mut region = Region::new();
        let (matched, can_cache) = match (pat.has_captures, captures) {
            (true, Some((cap_region, cap_text))) => {
                let s = substitute_backrefs(&pat.regex_str, cap_region, cap_text);
                let matched = match Regex::new(&s) {
                    Ok(re) => re.search(line, start, &mut region),
                    Err(_) => false,
                };
                (matched, false)
            }
            _ => {
                let matched = match pat.regex() {
                    Some(re) => re.search(line, start, &mut region),
                    None => false,
                };
                (matched, true)
            }
        };
        if matched {
            let (ms, me) = region.get(0).unwrap();
            let does_something = match pat.operation {
                MatchOperation::None => ms != me,
                _ => true,
            };
            if can_cache && does_something {
                cache.insert(key, Some(region.clone()));
            }
            if does_something {
                return Some(region);
            }
        } else if can_cache {
            cache.insert(key, None);
        }
        None
    }

    fn exec_pattern(&mut self, line: &str, m: &RegexMatch, level_context: &Context, set: &SyntaxSet, ops: &mut Vec<(usize, ScopeStackOp)>) {
        let (match_start, match_end) = m.regions.get(0).unwrap();
        let pat = match_at(m.context, m.pat_index);
        self.push_meta_ops(true, match_start, level_context, &pat.operation, set, ops);
        for s in &pat.scope {
            ops.push((match_start, ScopeStackOp::Push(*s)));
        }
        if let Some(capture_map) = &pat.captures {
            let mut map: Vec<((usize, i64), ScopeStackOp)> = Vec::new();
            for (cap_index, scopes) in capture_map {
                if let Some((cs, ce)) = m.regions.get(*cap_index) {
                    if cs == ce {
                        continue;
                    }
                    for scope in scopes {
                        map.push(((cs, -((ce - cs) as i64)), ScopeStackOp::Push(*scope)));
                    }
                    map.push(((ce, i64::MIN), ScopeStackOp::Pop(scopes.len())));
                }
            }
            map.sort_by(|a, b| a.0.cmp(&b.0));
            for ((idx, _), op) in map {
                ops.push((idx, op));
            }
        }
        if !pat.scope.is_empty() {
            ops.push((match_end, ScopeStackOp::Pop(pat.scope.len())));
        }
        self.push_meta_ops(false, match_end, level_context, &pat.operation, set, ops);
        self.perform_op(line, &m.regions, pat, set);
    }

    fn push_meta_ops(&self, initial: bool, index: usize, cur: &Context, op: &MatchOperation, set: &SyntaxSet, ops: &mut Vec<(usize, ScopeStackOp)>) {
        match op {
            MatchOperation::Pop => {
                let v = if initial { &cur.meta_content_scope } else { &cur.meta_scope };
                if !v.is_empty() {
                    ops.push((index, ScopeStackOp::Pop(v.len())));
                }
                if !initial && cur.clear_scopes.is_some() {
                    ops.push((index, ScopeStackOp::Restore));
                }
            }
            MatchOperation::Push(refs) | MatchOperation::Set(refs) => {
                let is_set = matches!(op, MatchOperation::Set(_));
                let ctxs: Vec<&Context> = refs.iter().filter_map(|r| ctx_ref_id(r).map(|id| set.get_context(id))).collect();
                if initial {
                    if is_set && cur.clear_scopes.is_some() {
                        ops.push((index, ScopeStackOp::Restore));
                    }
                    for ctx in &ctxs {
                        if !is_set {
                            if let Some(amount) = ctx.clear_scopes {
                                ops.push((index, ScopeStackOp::Clear(amount)));
                            }
                        }
                        for s in &ctx.meta_scope {
                            ops.push((index, ScopeStackOp::Push(*s)));
                        }
                    }
                } else {
                    let repush = (is_set && (!cur.meta_scope.is_empty() || !cur.meta_content_scope.is_empty()))
                        || ctxs.iter().any(|ctx| !ctx.meta_content_scope.is_empty() || (ctx.clear_scopes.is_some() && is_set));
                    if repush {
                        let mut num_to_pop: usize = ctxs.iter().map(|c| c.meta_scope.len()).sum();
                        if is_set {
                            num_to_pop += cur.meta_content_scope.len() + cur.meta_scope.len();
                        }
                        if num_to_pop > 0 {
                            ops.push((index, ScopeStackOp::Pop(num_to_pop)));
                        }
                        for ctx in &ctxs {
                            if is_set {
                                if let Some(amount) = ctx.clear_scopes {
                                    ops.push((index, ScopeStackOp::Clear(amount)));
                                }
                            }
                            for s in &ctx.meta_scope {
                                ops.push((index, ScopeStackOp::Push(*s)));
                            }
                            for s in &ctx.meta_content_scope {
                                ops.push((index, ScopeStackOp::Push(*s)));
                            }
                        }
                    }
                }
            }
            MatchOperation::None => {}
        }
    }

    fn perform_op(&mut self, line: &str, regions: &Region, pat: &MatchPattern, set: &SyntaxSet) {
        let (refs, old_protos) = match &pat.operation {
            MatchOperation::Push(refs) => (refs, None),
            MatchOperation::Set(refs) => (refs, self.stack.pop().map(|s| s.prototypes)),
            MatchOperation::Pop => {
                self.stack.pop();
                return;
            }
            MatchOperation::None => return,
        };
        let n = refs.len();
        for (i, r) in refs.iter().enumerate() {
            let mut proto_ids = if i == 0 { old_protos.clone().unwrap_or_default() } else { Vec::new() };
            if i == n - 1 {
                if let Some(wp) = &pat.with_prototype {
                    if let Some(id) = ctx_ref_id(wp) {
                        proto_ids.push(id);
                    }
                }
            }
            let id = match ctx_ref_id(r) {
                Some(id) => id,
                None => continue,
            };
            let ctx = set.get_context(id);
            let mut uses_backrefs = ctx.uses_backrefs;
            if !proto_ids.is_empty() {
                uses_backrefs = uses_backrefs || proto_ids.iter().any(|p| set.get_context(*p).uses_backrefs);
            }
            let captures = if uses_backrefs { Some((regions.clone(), line.to_string())) } else { None };
            self.stack.push(StateLevel { context: id, prototypes: proto_ids, captures });
        }
    }
}
