//! Color themes (decoded from the theme dump) and scope selectors.

use crate::assets::bincode::{Reader, Res};
use crate::syntax::scope::Scope;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub a: u8,
}

impl Color {
    pub const BLACK: Color = Color { r: 0, g: 0, b: 0, a: 0xFF };
    pub const WHITE: Color = Color { r: 0xFF, g: 0xFF, b: 0xFF, a: 0xFF };
}

pub const FONT_BOLD: u8 = 1;
pub const FONT_UNDERLINE: u8 = 2;
pub const FONT_ITALIC: u8 = 4;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Style {
    pub foreground: Color,
    pub background: Color,
    pub font_style: u8,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct StyleModifier {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub font_style: Option<u8>,
}

#[derive(Clone, Debug, Default)]
pub struct ScopeStackSel {
    pub scopes: Vec<Scope>,
}

const ATOM_LEN_BITS: u16 = 16;

impl ScopeStackSel {
    /// Returns the match score if this selector path matches the stack.
    pub fn does_match(&self, stack: &[Scope]) -> Option<f64> {
        let mut sel_index = 0usize;
        let mut score = 0.0f64;
        for (i, scope) in stack.iter().enumerate() {
            let sel_scope = self.scopes[sel_index];
            if sel_scope.is_prefix_of(*scope) {
                let len = sel_scope.len();
                score += f64::from(len) * f64::from(ATOM_LEN_BITS * (i as u16)).exp2();
                sel_index += 1;
                if sel_index >= self.scopes.len() {
                    return Some(score);
                }
            }
        }
        None
    }
    pub fn is_empty(&self) -> bool {
        self.scopes.is_empty()
    }
}

#[derive(Clone, Debug, Default)]
pub struct ScopeSelector {
    pub path: ScopeStackSel,
    pub excludes: Vec<ScopeStackSel>,
}

impl ScopeSelector {
    pub fn does_match(&self, stack: &[Scope]) -> Option<f64> {
        if self.excludes.iter().any(|sel| sel.is_empty() || sel.does_match(stack).is_some()) {
            return None;
        }
        if self.path.is_empty() {
            Some(1.0)
        } else {
            self.path.does_match(stack)
        }
    }
    pub fn extract_single_scope(&self) -> Option<Scope> {
        if self.path.scopes.len() != 1 || !self.excludes.is_empty() {
            return None;
        }
        Some(self.path.scopes[0])
    }
}

#[derive(Clone, Debug)]
pub struct ThemeItem {
    pub selectors: Vec<ScopeSelector>,
    pub style: StyleModifier,
}

#[derive(Clone, Debug, Default)]
pub struct ThemeSettings {
