    pub selection: Option<Color>,
}

#[derive(Clone, Debug)]
pub struct Theme {
    pub name: Option<String>,
    pub author: Option<String>,
    pub settings: ThemeSettings,
    pub scopes: Vec<ThemeItem>,
}

fn read_color(r: &mut Reader) -> Res<Color> {
