    let scopes = r.vec(|r| Ok(Scope::new(&r.string()?)))?;
    Ok(ScopeStackSel { scopes })
}

impl Theme {
    pub fn from_dump(data: &[u8]) -> Res<Theme> {
        let mut r = Reader::new(data);
        let name = r.option(|r| r.string())?;
