        let _accent = r.option(read_color)?;
        let _popup_css = r.option(|r| r.string())?;
        let _phantom_css = r.option(|r| r.string())?;
        let _bracket_contents_foreground = r.option(read_color)?;
        let _bracket_contents_options = r.option(|r| r.u32())?;
        let _brackets_foreground = r.option(read_color)?;
        let _brackets_background = r.option(read_color)?;
        let _brackets_options = r.option(|r| r.u32())?;
        let _tags_foreground = r.option(read_color)?;
        let _tags_options = r.option(|r| r.u32())?;
        let _highlight = r.option(read_color)?;
        let _find_highlight = r.option(read_color)?;
        let _find_highlight_foreground = r.option(read_color)?;
        s.gutter = r.option(read_color)?;
        s.gutter_foreground = r.option(read_color)?;
        s.selection = r.option(read_color)?;
        let _selection_foreground = r.option(read_color)?;
        let _selection_border = r.option(read_color)?;
        let _inactive_selection = r.option(read_color)?;
        let _inactive_selection_foreground = r.option(read_color)?;
        let _guide = r.option(read_color)?;
        let _active_guide = r.option(read_color)?;
        let _stack_guide = r.option(read_color)?;
        let _shadow = r.option(read_color)?;
        let scopes = r.vec(|r| {
            let selectors = r.vec(|r| {
                let path = read_stack(r)?;
                let excludes = r.vec(read_stack)?;
                Ok(ScopeSelector { path, excludes })
            })?;
            let foreground = r.option(read_color)?;
            let background = r.option(read_color)?;
            let font_style = r.option(|r| r.u8())?;
            Ok(ThemeItem { selectors, style: StyleModifier { foreground, background, font_style } })
        })?;
        Ok(Theme { name, author, settings: s, scopes })
    }
}
