//! Converts scope stack operations into styled text regions using a theme.

pub mod theme;

use crate::syntax::parser::ParseState;
use crate::syntax::scope::{BasicOp, Scope, ScopeStack, ScopeStackOp};
use crate::syntax::set::SyntaxSet;
use theme::{Color, ScopeSelector, Style, StyleModifier, Theme};

#[derive(Clone, Copy, Debug)]
struct ScoredStyle {
    foreground: (f64, Color),
    background: (f64, Color),
    font_style: (f64, u8),
}

impl ScoredStyle {
    fn from_style(s: Style) -> ScoredStyle {
        ScoredStyle { foreground: (-1.0, s.foreground), background: (-1.0, s.background), font_style: (-1.0, s.font_style) }
    }
    fn apply(&mut self, score: f64, m: &StyleModifier) {
        if let Some(fg) = m.foreground {
            if score > self.foreground.0 {
                self.foreground = (score, fg);
            }
        }
        if let Some(bg) = m.background {
            if score > self.background.0 {
                self.background = (score, bg);
            }
        }
        if let Some(fs) = m.font_style {
            if score > self.font_style.0 {
                self.font_style = (score, fs);
            }
        }
    }
    fn to_style(self) -> Style {
        Style { foreground: self.foreground.1, background: self.background.1, font_style: self.font_style.1 }
    }
}

pub struct Highlighter<'t> {
    pub theme: &'t Theme,
    single: Vec<(Scope, StyleModifier)>,
    multi: Vec<(ScopeSelector, StyleModifier)>,
}

impl<'t> Highlighter<'t> {
    pub fn new(theme: &'t Theme) -> Highlighter<'t> {
        let mut single = Vec::new();
        let mut multi = Vec::new();
        for item in &theme.scopes {
            for sel in &item.selectors {
                if let Some(sc) = sel.extract_single_scope() {
                    single.push((sc, item.style));
                } else {
                    multi.push((sel.clone(), item.style));
                }
            }
        }
        // deeper selectors first (stable sort)
        single.sort_by(|a, b| b.0.len().cmp(&a.0.len()));
        Highlighter { theme, single, multi }
    }

    pub fn default_style(&self) -> Style {
        Style {
            foreground: self.theme.settings.foreground.unwrap_or(Color::BLACK),
            background: self.theme.settings.background.unwrap_or(Color::WHITE),
            font_style: 0,
        }
    }

    fn update_single_cache_for_push(&self, cur: &ScoredStyle, path: &[Scope]) -> ScoredStyle {
        let mut new_style = *cur;
        let last = path[path.len() - 1];
        for (scope, modif) in self.single.iter().filter(|a| a.0.is_prefix_of(last)) {
            let score = f64::from(scope.len()) * f64::from(16u16 * ((path.len() - 1) as u16)).exp2();
            new_style.apply(score, modif);
        }
        new_style
    }

    fn finalize_style_with_multis(&self, cur: &ScoredStyle, path: &[Scope]) -> Style {
        let mut new_style = *cur;
        for (sel, modif) in &self.multi {
            if let Some(score) = sel.does_match(path) {
                new_style.apply(score, modif);
            }
        }
        new_style.to_style()
    }
}

pub struct HighlightState {
    styles: Vec<Style>,
    caches: Vec<ScoredStyle>,
    path: ScopeStack,
}

impl HighlightState {
    pub fn new(h: &Highlighter) -> HighlightState {
        let d = h.default_style();
        HighlightState { styles: vec![d], caches: vec![ScoredStyle::from_style(d)], path: ScopeStack::new() }
    }
}

/// Splits `text` according to `ops` into styled regions.
pub fn highlight_ops<'a>(state: &mut HighlightState, h: &Highlighter, ops: &[(usize, ScopeStackOp)], text: &'a str) -> Vec<(Style, &'a str)> {
    let mut out = Vec::new();
    let mut pos = 0usize;
    let mut index = 0usize;
    loop {
        if pos == text.len() && index >= ops.len() {
            break;
        }
        let (end, op) = if index < ops.len() { (ops[index].0, ops[index].1.clone()) } else { (text.len(), ScopeStackOp::Noop) };
        let style = *state.styles.last().unwrap_or(&Style { foreground: Color::BLACK, background: Color::WHITE, font_style: 0 });
        let end = end.max(pos).min(text.len());
        let piece = &text[pos..end];
        let styles = &mut state.styles;
        let caches = &mut state.caches;
        let ok = state.path.apply_with_hook(&op, |bop, stack| match bop {
            BasicOp::Push => {
                let new_cache = if let Some(prev) = caches.last() {
                    h.update_single_cache_for_push(prev, stack)
                } else {
                    let mut c = ScoredStyle::from_style(h.default_style());
                    for i in 0..stack.len() {
                        c = h.update_single_cache_for_push(&c, &stack[0..i + 1]);
                    }
                    c
                };
                styles.push(h.finalize_style_with_multis(&new_cache, stack));
                caches.push(new_cache);
            }
            BasicOp::Pop => {
                styles.pop();
                caches.pop();
            }
        });
        if !ok {
            break;
        }
        pos = end;
        index += 1;
        if !piece.is_empty() {
            out.push((style, piece));
        }
    }
    out
}

pub struct HighlightLines<'s, 't> {
    pub set: &'s SyntaxSet,
    pub highlighter: Highlighter<'t>,
    parse_state: ParseState,
    hl_state: HighlightState,
}

impl<'s, 't> HighlightLines<'s, 't> {
    pub fn new(set: &'s SyntaxSet, syntax: usize, theme: &'t Theme) -> Self {
        let highlighter = Highlighter::new(theme);
        let hl_state = HighlightState::new(&highlighter);
        HighlightLines { set, highlighter, parse_state: ParseState::new(set, syntax), hl_state }
    }

    pub fn highlight_line<'a>(&mut self, line: &'a str) -> Vec<(Style, &'a str)> {
        let ops = self.parse_state.parse_line(line, self.set);
        highlight_ops(&mut self.hl_state, &self.highlighter, &ops, line)
    }
}
