//! Line preprocessing: tab expansion, non-printable character replacement and
//! ANSI escape sequence stripping.

use crate::ansi::AnsiCodeIterator;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NonprintableNotation {
    Unicode,
    Caret,
}

/// Expand tabs to spaces. `cursor` counts bytes written so far on this line.
pub fn expand_tabs(line: &str, width: usize, cursor: &mut usize) -> String {
    let mut buffer = String::with_capacity(line.len() * 2);
    for (chunk, is_ansi) in AnsiCodeIterator::new(line) {
        if is_ansi {
            buffer.push_str(chunk);
            continue;
        }
        let mut text = chunk;
        while let Some(index) = text.find('\t') {
            if index > 0 {
                *cursor += index;
                buffer.push_str(&text[..index]);
            }
            let spaces = width - (*cursor % width);
            *cursor += spaces;
            for _ in 0..spaces {
                buffer.push(' ');
            }
            text = &text[index + 1..];
        }
        *cursor += text.len();
        buffer.push_str(text);
    }
    buffer
}

fn try_parse_utf8_char(input: &[u8]) -> Option<(char, usize)> {
    let str_from_utf8 = |seq: &[u8]| std::str::from_utf8(seq).ok().and_then(|s| s.chars().next());
    let decoded = input
        .get(0..1)
        .and_then(|seq| Some((str_from_utf8(seq)?, 1)))
        .or_else(|| input.get(0..2).and_then(|seq| Some((str_from_utf8(seq)?, 2))))
        .or_else(|| input.get(0..3).and_then(|seq| Some((str_from_utf8(seq)?, 3))))
        .or_else(|| input.get(0..4).and_then(|seq| Some((str_from_utf8(seq)?, 4))));
    decoded
}

pub fn replace_nonprintable(input: &[u8], tab_width: usize, notation: NonprintableNotation) -> String {
    let mut output = String::new();
    let tab_width = if tab_width == 0 { 4 } else { tab_width };
    let mut idx = 0;
    let mut line_idx = 0usize;
    let len = input.len();
    let caret = notation == NonprintableNotation::Caret;
    while idx < len {
        if let Some((chr, skip)) = try_parse_utf8_char(&input[idx..]) {
            idx += skip;
            line_idx += 1;
            match chr {
                ' ' => output.push('·'),
                '\t' => {
                    let tab_stop = tab_width - ((line_idx - 1) % tab_width);
                    line_idx = 0;
                    if tab_stop == 1 {
                        output.push('↹');
                    } else {
                        output.push('├');
                        for _ in 0..tab_stop - 2 {
                            output.push('─');
                        }
                        output.push('┤');
                    }
                }
                '\n' => {
                    output.push_str(if caret { "^J\n" } else { "␊\n" });
                    line_idx = 0;
                }
                c if (c as u32) < 0x20 => {
                    if caret {
                        output.push('^');
                        output.push(char::from_u32(c as u32 + 0x40).unwrap());
                    } else {
                        output.push(char::from_u32(0x2400 + c as u32).unwrap());
                    }
                }
                '\x7F' => output.push_str(if caret { "^?" } else { "␡" }),
                c if c.is_ascii() => output.push(c),
                c => output.push_str(&format!("\\u{{{:x}}}", c as u32)),
            }
        } else {
            output.push_str(&format!("\\x{:02X}", input[idx]));
            idx += 1;
        }
    }
    output
}

