pub fn strip_ansi(line: &str) -> String {
    let mut buffer = String::with_capacity(line.len());
    for (chunk, is_ansi) in AnsiCodeIterator::new(line) {
        if !is_ansi {
            buffer.push_str(chunk);
        }
    }
    buffer
}
