//! Parsing of ANSI/VT escape sequences embedded in the input, and tracking of
//! the resulting text attributes so that they can be re-applied.

/// Splits text into (chunk, is_escape_sequence) pieces.
pub struct AnsiCodeIterator<'a> {
    text: &'a str,
    pos: usize,
}

impl<'a> AnsiCodeIterator<'a> {
    pub fn new(text: &'a str) -> Self {
        AnsiCodeIterator { text, pos: 0 }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SeqKind {
    Csi,
    Osc,
    Nf,
    Other,
}

/// Returns the end offset of the escape sequence starting at `start` (which must be ESC).
pub fn sequence_end(text: &str, start: usize) -> (usize, SeqKind) {
    let b = text.as_bytes();
    let len = b.len();
    let mut i = start + 1;
    if i >= len {
        return (len, SeqKind::Other);
    }
    match b[i] {
        b'[' => {
            i += 1;
            while i < len && (0x30..=0x3F).contains(&b[i]) {
                i += 1;
            }
            while i < len && (0x20..=0x2F).contains(&b[i]) {
                i += 1;
            }
            if i < len {
                i += utf8_len(b[i]);
            }
            (i.min(len), SeqKind::Csi)
        }
        b']' => {
            i += 1;
            loop {
                while i < len && b[i] != 0x07 && b[i] != 0x1B {
                    i += 1;
                }
                if i >= len {
                    return (len, SeqKind::Osc);
                }
                if b[i] == 0x07 {
                    return (i + 1, SeqKind::Osc);
                }
                // ESC
                if i + 1 >= len {
                    return (i + 1, SeqKind::Osc);
                }
                if b[i + 1] == b'\\' {
                    return (i + 2, SeqKind::Osc);
                }
                i += 1;
                // skip the char after ESC and continue
                i += utf8_len(b[i]);
            }
        }
        0x20..=0x2F => {
            while i < len && (0x20..=0x2F).contains(&b[i]) {
                i += 1;
            }
            if i < len {
                i += utf8_len(b[i]);
            }
            (i.min(len), SeqKind::Nf)
        }
        c => (i + utf8_len(c), SeqKind::Other),
    }
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >= 0xF0 {
        4
    } else if b >= 0xE0 {
        3
    } else {
        2
    }
}

impl<'a> Iterator for AnsiCodeIterator<'a> {
    type Item = (&'a str, bool);
    fn next(&mut self) -> Option<Self::Item> {
        if self.pos >= self.text.len() {
            return None;
        }
        let b = self.text.as_bytes();
        if b[self.pos] == 0x1B {
            let (end, _) = sequence_end(self.text, self.pos);
            let end = end.min(self.text.len());
            let s = &self.text[self.pos..end];
            self.pos = end;
            return Some((s, true));
        }
        let start = self.pos;
        let mut i = start;
        while i < b.len() && b[i] != 0x1B {
            i += 1;
        }
        self.pos = i;
        Some((&self.text[start..i], false))
    }
}

