//! Line range specifications (`--line-range`, `--highlight-line`).

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Bound {
    Absolute(usize),
    FromEnd(usize),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct LineRange {
    pub lower: Bound,
    pub upper: Bound,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RangeCheck {
    BeforeOrBetween,
    InRange,
    AfterLast,
}

fn pint(s: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|e| e.to_string())
}

impl LineRange {
    pub fn new(lower: usize, upper: usize) -> LineRange {
        LineRange { lower: Bound::Absolute(lower), upper: Bound::Absolute(upper) }
    }

    pub fn parse(s: &str) -> Result<LineRange, String> {
        if s.is_empty() {
            return Err("Empty line range".into());
        }
        let colons = s.matches(':').count();
        if colons > 2 {
            return Err("Line range contained too many ':' characters. Expected format: 'N', 'N:M', 'N::C', or 'N:M:C'".into());
        }
        if let Some(rest) = s.strip_prefix(':') {
            let upper = if let Some(k) = rest.strip_prefix('-') { Bound::FromEnd(pint(k)?) } else { Bound::Absolute(pint(rest)?) };
            return Ok(LineRange { lower: Bound::Absolute(1), upper });
        }
        if let Some(head) = s.strip_suffix(':') {
            let lower = if let Some(k) = head.strip_prefix('-') { Bound::FromEnd(pint(k)?) } else { Bound::Absolute(pint(head)?) };
            return Ok(LineRange { lower, upper: Bound::Absolute(usize::MAX) });
        }
        let parts: Vec<&str> = s.split(':').collect();
        match parts.len() {
            1 => {
                let n = pint(parts[0])?;
                Ok(LineRange::new(n, n))
            }
            2 => {
                let lower = pint(parts[0])?;
                let b = parts[1];
                if let Some(rest) = b.strip_prefix('+') {
                    if !rest.bytes().next().map_or(false, |c| c.is_ascii_digit()) {
                        return Err("Invalid character after +".into());
                    }
                    let more = pint(rest)?;
                    Ok(LineRange::new(lower, lower.saturating_add(more)))
                } else if let Some(rest) = b.strip_prefix('-') {
                    if !rest.bytes().next().map_or(false, |c| c.is_ascii_digit()) {
                        return Err("Invalid character after -".into());
                    }
                    let prior = pint(rest)?;
                    Ok(LineRange::new(lower.saturating_sub(prior), lower))
                } else {
                    Ok(LineRange::new(lower, pint(b)?))
                }
            }
            _ => {
                if parts[1].is_empty() {
                    let n = parts[0].parse::<usize>().map_err(|_| "Invalid line number in N::C format".to_string())?;
                    let c = parts[2].parse::<usize>().map_err(|_| "Invalid context number in N::C format".to_string())?;
                    Ok(LineRange::new(n.saturating_sub(c), n.saturating_add(c)))
                } else {
                    let n = parts[0].parse::<usize>().map_err(|_| "Invalid start line number in N:M:C format".to_string())?;
                    let m = parts[1].parse::<usize>().map_err(|_| "Invalid end line number in N:M:C format".to_string())?;
                    let c = parts[2].parse::<usize>().map_err(|_| "Invalid context number in N:M:C format".to_string())?;
                    Ok(LineRange::new(n.saturating_sub(c), m.saturating_add(c)))
                }
            }
        }
    }

    pub fn needs_total(&self) -> bool {
        matches!(self.lower, Bound::FromEnd(_)) || matches!(self.upper, Bound::FromEnd(_))
    }

    fn resolve(&self, total: Option<usize>) -> (usize, usize) {
        let t = total.unwrap_or(usize::MAX);
        let lower = match self.lower {
            Bound::Absolute(n) => n,
            Bound::FromEnd(k) => (t.saturating_sub(k)).saturating_add(1),
        };
        let upper = match self.upper {
            Bound::Absolute(n) => n,
            Bound::FromEnd(k) => t.saturating_sub(k),
        };
        (lower, upper)
    }
}

#[derive(Clone, Debug)]
pub struct LineRanges {
    ranges: Vec<(usize, usize)>,
    raw: Vec<LineRange>,
    largest_upper: usize,
    pub all: bool,
}

impl LineRanges {
    pub fn none() -> LineRanges {
        LineRanges { ranges: vec![], raw: vec![], largest_upper: 0, all: false }
    }
    pub fn all() -> LineRanges {
        LineRanges { ranges: vec![(1, usize::MAX)], raw: vec![], largest_upper: usize::MAX, all: true }
    }
    pub fn from(raw: Vec<LineRange>) -> LineRanges {
        let mut r = LineRanges { ranges: vec![], raw, largest_upper: 0, all: false };
        r.resolve(None);
        r
    }
    pub fn needs_total(&self) -> bool {
        self.raw.iter().any(|r| r.needs_total())
    }
    pub fn resolve(&mut self, total: Option<usize>) {
        if self.all {
            return;
        }
        self.ranges = self.raw.iter().map(|r| r.resolve(total)).collect();
        self.largest_upper = self.ranges.iter().map(|r| r.1).max().unwrap_or(0);
    }
    pub fn check(&self, line: usize) -> RangeCheck {
        if self.ranges.iter().any(|&(a, b)| a <= line && line <= b) {
            RangeCheck::InRange
        } else if line < self.largest_upper {
            RangeCheck::BeforeOrBetween
        } else {
            RangeCheck::AfterLast
        }
    }
}
