impl InputReader {
    pub fn new(mut inner: Box<dyn BufRead>) -> io::Result<InputReader> {
        let mut first_line = Vec::new();
        inner.read_until(b'\n', &mut first_line)?;
        let content_type = if first_line.is_empty() { None } else { Some(inspect(&first_line)) };
        if content_type == Some(ContentType::Utf16Le) && first_line.last() == Some(&b'\n') {
            let mut b = [0u8; 1];
            if inner.read(&mut b)? == 1 {
                first_line.push(b[0]);
            }
        }
        Ok(InputReader { inner, first_line, content_type, first_consumed: false })
    }

    pub fn read_line(&mut self, buf: &mut Vec<u8>) -> io::Result<bool> {
        if !self.first_consumed {
            self.first_consumed = true;
            buf.extend_from_slice(&self.first_line);
            return Ok(!buf.is_empty());
        }
        let n = self.inner.read_until(b'\n', buf)?;
        if n == 0 {
            return Ok(false);
        }
        if self.content_type == Some(ContentType::Utf16Le) && buf.last() == Some(&b'\n') {
            let mut b = [0u8; 1];
            if self.inner.read(&mut b)? == 1 {
                buf.push(b[0]);
            }
        }
        Ok(true)
    }
}

pub struct OpenedInput {
