                let reader: Box<dyn BufRead> = match stdin {
                    Some(s) => s,
                    None => Box::new(BufReader::new(io::stdin())),
                };
                Ok(OpenedInput {
                    kind: self.kind.clone(),
                    description,
                    size: None,
                    reader: InputReader::new(reader).map_err(|e| crate::error::io_msg(&e))?,
                    path_for_syntax: self.name.clone(),
                })
            }
            InputKind::File(path) => {
                let disp = path.to_string_lossy();
                let meta = std::fs::metadata(path).map_err(|e| format!("'{}': {}", disp, crate::error::io_msg(&e)))?;
                if meta.is_dir() {
                    return Err(format!("'{}' is a directory.", disp));
                }
                let file = File::open(path).map_err(|e| format!("'{}': {}", disp, crate::error::io_msg(&e)))?;
                let reader: Box<dyn BufRead> = Box::new(BufReader::with_capacity(1 << 16, file));
                Ok(OpenedInput {
                    kind: self.kind.clone(),
                    description,
                    size: Some(meta.len()),
                    reader: InputReader::new(reader).map_err(|e| format!("'{}': {}", disp, crate::error::io_msg(&e)))?,
                    path_for_syntax: Some(self.name.clone().unwrap_or_else(|| path.clone())),
                })
            }
        }
    }
}
