//! Glob patterns (as used for syntax mappings), translated to regular expressions.
//! `*` and `?` do not match the path separator; `**` matches across directories.

use crate::regex::Regex;

pub struct Glob {
    re: Regex,
}

fn escape_char(c: char, out: &mut String) {
    if c.is_ascii_alphanumeric() || c == '_' || (c as u32) > 127 {
        out.push(c);
    } else {
        out.push('\\');
        out.push(c);
    }
}

fn translate(chars: &[char], i: &mut usize, out: &mut String, in_alt: bool) -> Result<(), String> {
    while *i < chars.len() {
        let c = chars[*i];
        match c {
            '*' => {
                let at_start = *i == 0 || chars[*i - 1] == '/';
                if *i + 1 < chars.len() && chars[*i + 1] == '*' {
                    let next = chars.get(*i + 2).copied();
                    if at_start && (next == Some('/') || next.is_none()) {
                        let is_first = *i == 0;
                        if next.is_none() {
                            if is_first {
                                out.push_str(".*");
                            } else {
                                // "/**" suffix: we already emitted '/'
                                out.truncate(out.len() - 2); // remove "\/"
                                out.push_str("/.*");
                            }
                            *i += 2;
                            continue;
                        } else if is_first {
                            out.push_str("(?:/?|.*/)");
                            *i += 3;
                            continue;
                        } else {
                            out.truncate(out.len() - 2);
                            out.push_str("(?:/|/.*/)");
                            *i += 3;
                            continue;
                        }
                    }
                    out.push_str("[^/]*");
                    *i += 2;
                    continue;
                }
                out.push_str("[^/]*");
                *i += 1;
            }
            '?' => {
                out.push_str("[^/]");
                *i += 1;
            }
            '[' => {
                let mut j = *i + 1;
                let mut cls = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    cls.push('^');
                    j += 1;
                }
                let start = j;
                while j < chars.len() && (chars[j] != ']' || j == start) {
                    let ch = chars[j];
                    if ch == '\\' || ch == '[' || ch == '&' || ch == '^' {
                        cls.push('\\');
                    }
                    cls.push(ch);
                    j += 1;
                }
                if j >= chars.len() {
                    return Err("unclosed character class".into());
                }
                cls.push(']');
                out.push_str(&cls);
                *i = j + 1;
            }
            '{' => {
                *i += 1;
                out.push_str("(?:");
                loop {
                    translate(chars, i, out, true)?;
                    if *i >= chars.len() {
                        return Err("unclosed alternate group".into());
                    }
                    if chars[*i] == ',' {
                        out.push('|');
                        *i += 1;
                        continue;
                    }
                    if chars[*i] == '}' {
                        out.push(')');
                        *i += 1;
                        break;
                    }
                }
            }
            ',' | '}' if in_alt => return Ok(()),
            '\\' => {
                if *i + 1 < chars.len() {
                    escape_char(chars[*i + 1], out);
                    *i += 2;
                } else {
                    escape_char('\\', out);
                    *i += 1;
                }
            }
            '/' => {
                out.push_str("\\/");
                *i += 1;
            }
            c => {
                escape_char(c, out);
                *i += 1;
            }
        }
    }
    Ok(())
}

impl Glob {
    pub fn new(pattern: &str) -> Result<Glob, String> {
        let chars: Vec<char> = pattern.chars().collect();
        let mut body = String::new();
        let mut i = 0;
        translate(&chars, &mut i, &mut body, false)?;
        let re = Regex::new(&format!("(?i)\\A(?:{})\\z", body))?;
        Ok(Glob { re })
    }

    pub fn is_match(&self, s: &str) -> bool {
        self.re.is_match(s)
    }
}
