//! Mapping of file paths to syntaxes (custom `--map-syntax` rules and builtin rules).

use crate::builtin_mappings::{Target, BUILTIN};
use crate::glob::Glob;
use std::path::{Component, Path, PathBuf};

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum MappingTarget {
    MapTo(String),
    MapToUnknown,
    MapExtensionToUnknown,
}

pub struct SyntaxMapping {
    custom: Vec<(Glob, MappingTarget, String)>,
    builtin: Vec<(Glob, MappingTarget, String)>,
    pub ignored_suffixes: Vec<String>,
}

fn expand_env(template: &str) -> Option<String> {
    let mut out = String::new();
    let mut rest = template;
    while let Some(start) = rest.find("${") {
        out.push_str(&rest[..start]);
        let end = rest[start..].find('}')? + start;
        let var = &rest[start + 2..end];
        let val = std::env::var(var).ok()?;
        if val.is_empty() {
            return None;
        }
        out.push_str(&val);
        rest = &rest[end + 1..];
    }
    out.push_str(rest);
    Some(out)
}

impl SyntaxMapping {
    pub fn new() -> SyntaxMapping {
        let mut builtin = Vec::new();
        for (pat, target) in BUILTIN {
            let pat = match expand_env(pat) {
                Some(p) => p,
                None => continue,
            };
            let t = match target {
                Target::MapTo(n) => MappingTarget::MapTo(n.to_string()),
                Target::Unknown => MappingTarget::MapToUnknown,
                Target::ExtensionUnknown => MappingTarget::MapExtensionToUnknown,
            };
            if let Ok(g) = Glob::new(&pat) {
                builtin.push((g, t, pat));
            }
        }
        SyntaxMapping {
            custom: Vec::new(),
            builtin,
            ignored_suffixes: vec![
                "~".into(),
                ".bak".into(),
                ".old".into(),
                ".orig".into(),
                ".dpkg-dist".into(),
                ".dpkg-old".into(),
                ".ucf-dist".into(),
                ".ucf-new".into(),
                ".ucf-old".into(),
                ".rpmnew".into(),
                ".rpmorig".into(),
                ".rpmsave".into(),
                ".in".into(),
            ],
        }
    }

    /// Insert a custom mapping; later insertions take precedence.
    pub fn insert(&mut self, glob: &str, target: MappingTarget) -> Result<(), String> {
        let g = Glob::new(glob)?;
        self.custom.insert(0, (g, target, glob.to_string()));
        Ok(())
    }

    pub fn insert_ignored_suffix(&mut self, s: &str) {
        self.ignored_suffixes.push(s.to_string());
    }

    /// All mappings in precedence order: (glob string, target)
    pub fn all_mappings(&self) -> Vec<(&str, &MappingTarget)> {
        self.custom.iter().chain(self.builtin.iter()).map(|(_, t, s)| (s.as_str(), t)).collect()
    }

    pub fn get_syntax_for(&self, path: &Path) -> Option<MappingTarget> {
        let full = path.to_string_lossy();
        let file_name = path.file_name().map(|f| f.to_string_lossy().into_owned());
        for (g, t, _) in self.custom.iter().chain(self.builtin.iter()) {
            if g.is_match(&full) || file_name.as_ref().map_or(false, |f| g.is_match(f)) {
                return Some(t.clone());
            }
        }
        None
    }

    /// Strip one of the ignored suffixes from a file name, if present.
    pub fn strip_ignored_suffix(&self, name: &str) -> Option<String> {
        for suffix in &self.ignored_suffixes {
            if let Some(stripped) = name.strip_suffix(suffix.as_str()) {
                if !stripped.is_empty() {
                    return Some(stripped.to_string());
                }
            }
        }
        None
    }
}

/// Make a path absolute and normalize `.`/`..` components lexically.
pub fn absolute_path(path: &Path) -> PathBuf {
    let joined = if path.is_absolute() {
        path.to_path_buf()
    } else {
        match std::env::current_dir() {
            Ok(d) => d.join(path),
            Err(_) => path.to_path_buf(),
        }
    };
    let mut out = PathBuf::new();
    for c in joined.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            other => out.push(other.as_os_str()),
        }
    }
    out
}
