//! Printers: the simple "cat"-like printer and the interactive (decorated,
//! highlighted) printer.

use crate::ansi::{AnsiCodeIterator, AnsiState};
use crate::assets::Assets;
use crate::config::{BinaryBehavior, Config, StripAnsiMode, WrappingMode};
use crate::diff::{LineChange, LineChanges};
use crate::highlight::theme::{Color, Style, Theme};
use crate::highlight::HighlightLines;
use crate::input::{ContentType, OpenedInput};
use crate::line_range::RangeCheck;
use crate::preprocessor::{expand_tabs, replace_nonprintable, strip_ansi};
use crate::terminal::{as_terminal_escaped, to_ansi_color, AnsiColor, AnsiStyle};
use std::io::{self, Write};
use unicode_width::UnicodeWidthChar;

pub type Out<'a> = &'a mut dyn Write;

pub trait Printer {
    fn print_header(&mut self, out: Out, input: &OpenedInput, add_header_padding: bool) -> io::Result<()>;
    fn print_footer(&mut self, out: Out, input: &OpenedInput) -> io::Result<()>;
    fn print_snip(&mut self, out: Out) -> io::Result<()>;
    fn print_line(&mut self, out_of_range: bool, out: Out, line_number: usize, line: &[u8]) -> io::Result<()>;
}

pub struct SimplePrinter<'a> {
    config: &'a Config,
}

impl<'a> SimplePrinter<'a> {
    pub fn new(config: &'a Config) -> Self {
        SimplePrinter { config }
    }
}

impl<'a> Printer for SimplePrinter<'a> {
    fn print_header(&mut self, _out: Out, _input: &OpenedInput, _p: bool) -> io::Result<()> {
        Ok(())
    }
    fn print_footer(&mut self, _out: Out, _input: &OpenedInput) -> io::Result<()> {
        Ok(())
    }
    fn print_snip(&mut self, _out: Out) -> io::Result<()> {
        Ok(())
    }
    fn print_line(&mut self, out_of_range: bool, out: Out, _line_number: usize, line: &[u8]) -> io::Result<()> {
        if out_of_range {
            return Ok(());
        }
        if self.config.show_nonprintable {
            let l = replace_nonprintable(line, self.config.tab_width, self.config.nonprintable_notation);
            out.write_all(l.as_bytes())
        } else {
            out.write_all(line)
        }
    }
}

#[derive(Clone, Copy, Default)]
pub struct Colors {
    pub grid: AnsiStyle,
    pub rule: AnsiStyle,
    pub header_value: AnsiStyle,
    pub git_added: AnsiStyle,
    pub git_removed: AnsiStyle,
    pub git_modified: AnsiStyle,
    pub line_number: AnsiStyle,
}

const DEFAULT_GUTTER_COLOR: u8 = 238;

impl Colors {
    pub fn plain() -> Colors {
        Colors::default()
    }
    pub fn colored(theme: &Theme, true_color: bool) -> Colors {
        let gutter = AnsiStyle {
            fg: match theme.settings.gutter_foreground {
                Some(c) => to_ansi_color(c, true_color),
                None => Some(AnsiColor::Fixed(DEFAULT_GUTTER_COLOR)),
            },
            ..Default::default()
        };
        Colors {
            grid: gutter,
            rule: gutter,
            header_value: AnsiStyle::bold(),
            git_added: AnsiStyle::fg(AnsiColor::Green),
            git_removed: AnsiStyle::fg(AnsiColor::Red),
            git_modified: AnsiStyle::fg(AnsiColor::Yellow),
            line_number: gutter,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Decoration {
    LineNumber,
    Changes,
    Grid,
}

fn char_width(c: char) -> usize {
    c.width().unwrap_or(2)
}

pub struct InteractivePrinter<'a> {
    config: &'a Config,
    colors: Colors,
    decorations: Vec<Decoration>,
    panel_width: usize,
    ansi_state: AnsiState,
    content_type: Option<ContentType>,
    line_changes: Option<LineChanges>,
    highlighter: Option<HighlightLines<'a, 'a>>,
    background_highlight: Option<Color>,
    strip_ansi: bool,
    theme_is_ansi: bool,
}

pub fn byte_size(s: u64) -> String {
    if s < 1024 {
        return format!("{} B", s);
    }
    let units = ["KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    let mut v = s as f64;
    let mut i = 0;
    v /= 1024.0;
    while v >= 1024.0 && i < units.len() - 1 {
        v /= 1024.0;
        i += 1;
    }
    format!("{:.1} {}", v, units[i])
}

impl<'a> InteractivePrinter<'a> {
    pub fn new(
        config: &'a Config,
        assets: &'a Assets,
        theme: Option<&'a Theme>,
        input: &OpenedInput,
        line_changes: Option<LineChanges>,
    ) -> Result<Self, String> {
        let colors = match (config.colored_output, theme) {
            (true, Some(t)) => Colors::colored(t, config.true_color),
            _ => Colors::plain(),
        };
        let mut decorations = Vec::new();
        if config.style.numbers() {
            decorations.push(Decoration::LineNumber);
        }
        if config.style.changes() {
            decorations.push(Decoration::Changes);
        }
        let width_of = |d: &Decoration| match d {
            Decoration::LineNumber => 4,
            Decoration::Changes => 1,
            Decoration::Grid => 1,
        };
        let mut panel_width: usize = decorations.len() + decorations.iter().map(width_of).sum::<usize>();
        if config.style.grid() && !decorations.is_empty() {
            decorations.push(Decoration::Grid);
        }
        if config.term_width < decorations.len() + decorations.iter().map(width_of).sum::<usize>() + 5 {
            decorations.clear();
            panel_width = 0;
        }

        let content_type = input.reader.content_type;
        let is_printing_binary = content_type.map_or(false, |c| c.is_binary()) && !config.show_nonprintable;
        let needs_syntax = (!is_printing_binary || config.binary == BinaryBehavior::AsText)
            && (config.colored_output || config.strip_ansi == StripAnsiMode::Auto);

        let mut highlighter = None;
        let mut is_plain_text = false;
        if needs_syntax {
            let syntax = assets.get_syntax(config, input)?;
            is_plain_text = assets.syntaxes.syntaxes[syntax].name == "Plain Text";
            if config.colored_output {
                if let Some(t) = theme {
                    highlighter = Some(HighlightLines::new(&assets.syntaxes, syntax, t));
                }
            }
        }
        let strip_ansi = match config.strip_ansi {
            _ if config.show_nonprintable => false,
            StripAnsiMode::Always => true,
            StripAnsiMode::Auto if is_plain_text => false,
            StripAnsiMode::Auto => true,
            StripAnsiMode::Never => false,
        };

        Ok(InteractivePrinter {
            config,
            colors,
            decorations,
            panel_width,
            ansi_state: AnsiState::new(),
            content_type,
            line_changes,
            highlighter,
            background_highlight: theme.and_then(|t| t.settings.line_highlight),
            strip_ansi,
            theme_is_ansi: config.theme_name == "ansi",
        })
    }

    fn deco_text(&self, d: Decoration, line_number: usize, wrapped: bool) -> (String, usize) {
        match d {
            Decoration::LineNumber => {
                let text = if wrapped { "    ".to_string() } else { format!("{:4}", line_number) };
                let w = text.chars().count();
                (self.colors.line_number.paint(&text), w)
            }
            Decoration::Changes => {
                if wrapped {
                    return (" ".to_string(), 1);
                }
                let ch = self.line_changes.as_ref().and_then(|c| c.get(&(line_number as u32)).copied());
                match ch {
                    Some(LineChange::Added) => (self.colors.git_added.paint("+"), 1),
                    Some(LineChange::RemovedAbove) => (self.colors.git_removed.paint("‾"), 1),
                    Some(LineChange::RemovedBelow) => (self.colors.git_removed.paint("_"), 1),
                    Some(LineChange::Modified) => (self.colors.git_modified.paint("~"), 1),
                    None => (" ".to_string(), 1),
                }
            }
            Decoration::Grid => (self.colors.grid.paint("│"), 1),
        }
    }

    fn print_horizontal_line_term(&self, out: Out, style: AnsiStyle) -> io::Result<()> {
        writeln!(out, "{}", style.paint(&"─".repeat(self.config.term_width)))
    }

    fn print_horizontal_line(&self, out: Out, grid_char: char) -> io::Result<()> {
        if self.panel_width == 0 {
            self.print_horizontal_line_term(out, self.colors.grid)
        } else {
            let hline = "─".repeat(self.config.term_width.saturating_sub(self.panel_width + 1));
            let s = format!("{}{}{}", "─".repeat(self.panel_width), grid_char, hline);
            writeln!(out, "{}", self.colors.grid.paint(&s))
        }
    }

    fn header_indent(&self, out: Out) -> io::Result<()> {
        if self.config.style.grid() {
            write!(
                out,
                "{}{}",
                " ".repeat(self.panel_width),
                self.colors.grid.paint(if self.panel_width > 0 { "│ " } else { "" })
            )
        } else {
            write!(out, "{}", " ".repeat(self.panel_width))
        }
    }

    fn header_multiline(&self, out: Out, content: &str) -> io::Result<()> {
        use unicode_width::UnicodeWidthStr;
        let mut content: &str = content;
        let content_width = self.config.term_width.saturating_sub(self.panel_width);
        while content.width() > content_width && content_width > 0 {
            let mut idx = content_width.min(content.len());
            while !content.is_char_boundary(idx) {
                idx -= 1;
            }
            if idx == 0 {
                break;
            }
            let (line, rest) = content.split_at(idx);
            writeln!(out, "{}", line)?;
            content = rest;
            self.header_indent(out)?;
        }
        writeln!(out, "{}", content)
    }

    fn create_fake_panel(&self, text: &str) -> String {
        if self.panel_width == 0 {
            return String::new();
        }
        let truncated: String = text.chars().take(self.panel_width - 1).collect();
        let filled = format!("{}{}", truncated, " ".repeat(self.panel_width - 1 - truncated.chars().count()));
        if self.config.style.grid() {
            format!("{} │ ", filled)
        } else {
            filled
        }
    }

    fn preprocess(&self, text: &str, cursor: &mut usize) -> String {
        if self.config.tab_width > 0 {
            return expand_tabs(text, self.config.tab_width, cursor);
        }
        *cursor += text.len();
        text.to_string()
    }

    fn highlight_regions<'l>(&mut self, line: &'l str) -> Vec<(Style, &'l str)> {
        let hl = match self.highlighter.as_mut() {
            Some(h) => h,
            None => {
                return vec![(Style { foreground: Color::default(), background: Color::default(), font_style: 0 }, line)]
            }
        };
        let too_long = line.len() > 1024 * 16;
        if too_long {
            let mut r = hl.highlight_line("\n");
            let st: Vec<(Style, &'l str)> = if r.is_empty() {
                vec![(hl.highlighter.default_style(), line)]
            } else {
                let s = r.remove(0).0;
                vec![(s, line)]
            };
            return st;
        }
        hl.highlight_line(line)
    }

    fn write_text(&self, out: Out, style: Style, text: &str, bg: Option<Color>) -> io::Result<()> {
        let s = format!("{}{}", self.ansi_state.prefix(), text);
        write!(
            out,
            "{}",
            as_terminal_escaped(style, &s, self.config.true_color, self.config.colored_output, self.config.use_italic_text, bg)
        )
    }
}

impl<'a> Printer for InteractivePrinter<'a> {
    fn print_header(&mut self, out: Out, input: &OpenedInput, add_header_padding: bool) -> io::Result<()> {
        if add_header_padding && self.config.style.rule() {
            self.print_horizontal_line_term(out, self.colors.rule)?;
        }
        if !self.config.style.header() {
            if self.content_type == Some(ContentType::Binary) && !self.config.show_nonprintable {
                writeln!(
                    out,
                    "{}: Binary content from {} will not be printed to the terminal (but will be present if the output of 'bat' is piped). You can use 'bat -A' to show the binary file contents.",
                    AnsiStyle::fg(AnsiColor::Yellow).paint("[bat warning]"),
                    input.description.summary
                )?;
            } else if self.config.style.grid() {
                self.print_horizontal_line(out, '┬')?;
            }
            return Ok(());
        }
        let mode = match self.content_type {
            Some(ContentType::Binary) => "   <BINARY>",
            Some(ContentType::Utf16Le) => "   <UTF-16LE>",
            Some(ContentType::Utf16Be) => "   <UTF-16BE>",
            None => "   <EMPTY>",
            _ => "",
        };
        if self.config.style.grid() {
            self.print_horizontal_line(out, '┬')?;
        } else if add_header_padding && !self.config.style.rule() {
            writeln!(out)?;
        }
        if self.config.style.header_filename() {
            self.header_indent(out)?;
            let d = &input.description;
            let s = format!(
                "{}{}{}",
                d.kind.as_ref().map(|k| format!("{}: ", k)).unwrap_or_default(),
                self.colors.header_value.paint(&d.title),
                mode
            );
            self.header_multiline(out, &s)?;
        }
        if self.config.style.header_filesize() {
            self.header_indent(out)?;
            let bsize = input.size.map(byte_size).unwrap_or_else(|| "-".into());
            let s = format!("Size: {}{}", self.colors.header_value.paint(&bsize), mode);
            self.header_multiline(out, &s)?;
        }
        if self.config.style.grid() {
            if self.content_type.map_or(false, |c| c.is_text()) || self.config.show_nonprintable {
                self.print_horizontal_line(out, '┼')?;
            } else {
                self.print_horizontal_line(out, '┴')?;
            }
        }
        Ok(())
    }

    fn print_footer(&mut self, out: Out, _input: &OpenedInput) -> io::Result<()> {
        if self.config.style.grid() && (self.content_type.map_or(false, |c| c.is_text()) || self.config.show_nonprintable) {
            self.print_horizontal_line(out, '┴')
        } else {
            Ok(())
        }
    }

    fn print_snip(&mut self, out: Out) -> io::Result<()> {
        let panel = self.create_fake_panel(" ...");
        let panel_count = panel.chars().count();
        let title = "8<";
        let title_count = 2;
        let tw = self.config.term_width;
        let snip_left = "─ ".repeat(tw.saturating_sub(panel_count + title_count / 2) / 4);
        let snip_left_count = snip_left.chars().count();
        let snip_right = " ─".repeat(tw.saturating_sub(panel_count + snip_left_count + title_count) / 2);
        writeln!(out, "{}", self.colors.grid.paint(&format!("{}{}{}{}", panel, snip_left, title, snip_right)))
    }

    fn print_line(&mut self, out_of_range: bool, out: Out, line_number: usize, line_buffer: &[u8]) -> io::Result<()> {
        let line: String = if self.config.show_nonprintable {
            replace_nonprintable(line_buffer, self.config.tab_width, self.config.nonprintable_notation)
        } else {
            let decoded: String = match self.content_type {
                Some(ContentType::Binary) | None if self.config.binary != BinaryBehavior::AsText => return Ok(()),
                Some(ContentType::Utf16Le) => decode_utf16(line_buffer, true),
                Some(ContentType::Utf16Be) => decode_utf16(line_buffer, false),
                _ => {
                    let l = String::from_utf8_lossy(line_buffer).into_owned();
                    if line_number == 1 {
                        match l.strip_prefix('\u{feff}') {
                            Some(s) => s.to_string(),
                            None => l,
                        }
                    } else {
                        l
                    }
                }
            };
            if self.strip_ansi {
                strip_ansi(&decoded)
            } else {
                decoded
            }
        };

        let regions: Vec<(Style, String)> = self.highlight_regions(&line).into_iter().map(|(s, t)| (s, t.to_string())).collect();
        if out_of_range {
            return Ok(());
        }

        let mut cursor: usize = 0;
        let mut cursor_max: usize = self.config.term_width;
        let mut cursor_total: usize = 0;
        let mut panel_wrap: Option<String> = None;

        let highlight_this_line = self.config.highlighted_lines.check(line_number) == RangeCheck::InRange;
        let ansi_underline = highlight_this_line && self.theme_is_ansi;
        if ansi_underline {
            self.ansi_state.update("\x1b[4m");
        }
        let background = if highlight_this_line { self.background_highlight } else { None };

        if self.panel_width > 0 {
            let decos = self.decorations.clone();
            for d in decos {
                let (text, w) = self.deco_text(d, line_number, false);
                write!(out, "{} ", text)?;
                cursor_max = cursor_max.saturating_sub(w + 1);
            }
        }

        match self.config.wrapping_mode {
            WrappingMode::NoWrapping(_) => {
                for (style, region) in &regions {
                    for (chunk, is_ansi) in AnsiCodeIterator::new(region) {
                        if is_ansi {
                            write!(out, "{}", chunk)?;
                            self.ansi_state.update(chunk);
                            continue;
                        }
                        let text = self.preprocess(chunk, &mut cursor_total);
                        let trimmed = text.trim_end_matches(|c| c == '\r' || c == '\n');
                        self.write_text(out, *style, trimmed, background)?;
                        write!(out, "{}", self.ansi_state.reset_sequence())?;
                        if text.len() != trimmed.len() {
                            if let Some(bg) = background {
                                let st = AnsiStyle { bg: to_ansi_color(bg, self.config.true_color), ..Default::default() };
                                let width = cursor_max.saturating_sub(cursor_total);
                                write!(out, "{}", st.paint(&" ".repeat(width)))?;
                            }
                            write!(out, "{}", &text[trimmed.len()..])?;
                        }
                    }
                }
                if !self.config.style.plain() && !line.ends_with('\n') {
                    writeln!(out)?;
                }
            }
            WrappingMode::Character | WrappingMode::Word => {
                let word = self.config.wrapping_mode == WrappingMode::Word;
                for (style, region) in &regions {
                    for (chunk, is_ansi) in AnsiCodeIterator::new(region) {
                        if is_ansi {
                            write!(out, "{}", chunk)?;
                            self.ansi_state.update(chunk);
                            continue;
                        }
                        let trimmed = chunk.trim_end_matches(|c| c == '\r' || c == '\n');
                        let text = self.preprocess(trimmed, &mut cursor_total);
                        let mut max_width = cursor_max.saturating_sub(cursor);
                        let mut line_buf = String::with_capacity(max_width * 4);
                        let mut current_width = 0usize;
                        for c in text.chars() {
                            let cw = char_width(c);
                            current_width += cw;
                            if current_width > max_width {
                                if panel_wrap.is_none() {
                                    panel_wrap = Some(if self.panel_width > 0 {
                                        let decos = self.decorations.clone();
                                        let parts: Vec<String> =
                                            decos.iter().map(|d| self.deco_text(*d, line_number, true).0).collect();
                                        format!("{} ", parts.join(" "))
                                    } else {
                                        String::new()
                                    });
                                }
                                let mut carry = String::new();
                                if word && !c.is_whitespace() {
                                    if let Some(idx) = line_buf.rfind(|ch: char| ch.is_whitespace()) {
                                        let ws_len = line_buf[idx..].chars().next().unwrap().len_utf8();
                                        carry = line_buf[idx + ws_len..].to_string();
                                        line_buf.truncate(idx);
                                    }
                                }
                                self.write_text(out, *style, &line_buf, background)?;
                                write!(out, "{}", self.ansi_state.reset_sequence())?;
                                write!(out, "\n{}", panel_wrap.as_ref().unwrap())?;
                                cursor = 0;
                                max_width = cursor_max;
                                line_buf.clear();
                                line_buf.push_str(&carry);
                                current_width = carry.chars().map(char_width).sum::<usize>() + cw;
                            }
                            line_buf.push(c);
                        }
                        cursor += current_width;
                        self.write_text(out, *style, &line_buf, background)?;
                        write!(out, "{}", self.ansi_state.reset_sequence())?;
                    }
                }
                if let Some(bg) = background {
                    let st = AnsiStyle { bg: to_ansi_color(bg, self.config.true_color), ..Default::default() };
                    write!(out, "{}", st.paint(&" ".repeat(cursor_max.saturating_sub(cursor))))?;
                }
                writeln!(out)?;
            }
        }

        if ansi_underline {
            self.ansi_state.update("\x1b[24m");
            write!(out, "\x1b[24m")?;
        }
        Ok(())
    }
}

fn decode_utf16(buf: &[u8], le: bool) -> String {
    let mut b = buf;
    if le && b.starts_with(&[0xFF, 0xFE]) {
        b = &b[2..];
    } else if !le && b.starts_with(&[0xFE, 0xFF]) {
        b = &b[2..];
    }
    let units: Vec<u16> = b
        .chunks(2)
        .map(|c| {
            if c.len() == 2 {
                if le {
                    u16::from_le_bytes([c[0], c[1]])
                } else {
                    u16::from_be_bytes([c[0], c[1]])
                }
            } else {
                0xFFFD
            }
        })
        .collect();
    String::from_utf16_lossy(&units)
}
