//! Git integration: line-level modification markers with respect to the index.

use std::collections::HashMap;
use std::path::Path;
use std::process::{Command, Stdio};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LineChange {
    Added,
    RemovedAbove,
    RemovedBelow,
    Modified,
}

pub type LineChanges = HashMap<u32, LineChange>;

fn run_git(dir: &Path, args: &[&str]) -> Option<String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(dir)
        .args(args)
        .env("GIT_PAGER", "cat")
        .env("LC_ALL", "C")
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    String::from_utf8(out.stdout).ok()
}

fn parse_range(s: &str) -> Option<(u32, u32)> {
    let s = &s[1..];
    let mut it = s.splitn(2, ',');
    let start: u32 = it.next()?.parse().ok()?;
    let len: u32 = match it.next() {
        Some(l) => l.parse().ok()?,
        None => 1,
    };
    Some((start, len))
}

pub fn get_git_diff(filename: &Path) -> Option<LineChanges> {
    let abs = std::fs::canonicalize(filename).ok()?;
    let dir = abs.parent()?;
    let top = run_git(dir, &["rev-parse", "--show-toplevel"])?;
    let top = std::fs::canonicalize(top.trim_end_matches('\n')).ok()?;
    let rel = abs.strip_prefix(&top).ok()?;
    let rel_s = rel.to_string_lossy().into_owned();
    let out = run_git(
        &top,
        &[
            "-c",
            "core.quotepath=off",
            "diff",
            "--no-color",
            "--no-ext-diff",
            "--no-textconv",
            "--diff-algorithm=myers",
            "-U0",
            "--",
            &format!(":(literal){}", rel_s),
        ],
    )?;
    let mut changes: LineChanges = HashMap::new();
    let mut mark = |changes: &mut LineChanges, start: u32, end: i64, c: LineChange| {
        let mut l = start as i64;
        while l <= end {
            changes.insert(l as u32, c);
            l += 1;
        }
    };
    for line in out.lines() {
        if !line.starts_with("@@ ") {
            continue;
        }
        let parts: Vec<&str> = line.split(' ').collect();
        if parts.len() < 3 {
            continue;
        }
        let (_old_start, old_lines) = match parse_range(parts[1]) {
            Some(x) => x,
            None => continue,
        };
        let (new_start, new_lines) = match parse_range(parts[2]) {
            Some(x) => x,
            None => continue,
        };
        let new_end = (new_start + new_lines) as i64 - 1;
        if old_lines == 0 && new_lines > 0 {
            mark(&mut changes, new_start, new_end, LineChange::Added);
        } else if new_lines == 0 && old_lines > 0 {
            if new_start == 0 {
                mark(&mut changes, 1, 1, LineChange::RemovedAbove);
            } else {
                mark(&mut changes, new_start, new_start as i64, LineChange::RemovedBelow);
            }
        } else {
            mark(&mut changes, new_start, new_end, LineChange::Modified);
        }
    }
    Some(changes)
}
