//! Configuration / cache directories and the `bat cache` subcommand.

use std::path::{Path, PathBuf};

fn home_dir() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    // Fall back to the password database.
    passwd_home()
}

fn passwd_home() -> Option<PathBuf> {
    let uid = unsafe { getuid() };
    let content = std::fs::read_to_string("/etc/passwd").ok()?;
    for line in content.lines() {
        let f: Vec<&str> = line.split(':').collect();
        if f.len() >= 6 && f[2].parse::<u32>().ok() == Some(uid) {
            return Some(PathBuf::from(f[5]));
        }
    }
    None
}

extern "C" {
    fn getuid() -> u32;
}

fn xdg(var: &str, default_rel: &str) -> Option<PathBuf> {
    if let Some(v) = std::env::var_os(var) {
        let p = PathBuf::from(v);
        if p.is_absolute() {
            return Some(p);
        }
    }
    home_dir().map(|h| h.join(default_rel))
}

pub fn config_dir() -> PathBuf {
    if let Some(d) = std::env::var_os("BAT_CONFIG_DIR") {
        return PathBuf::from(d);
    }
    xdg("XDG_CONFIG_HOME", ".config").map(|d| d.join("bat")).unwrap_or_else(|| PathBuf::from("bat"))
}

pub fn cache_dir() -> PathBuf {
    if let Some(d) = std::env::var_os("BAT_CACHE_PATH") {
        return PathBuf::from(d);
    }
    xdg("XDG_CACHE_HOME", ".cache").map(|d| d.join("bat")).unwrap_or_else(|| PathBuf::from("bat"))
}

pub fn config_file() -> PathBuf {
    if let Some(p) = std::env::var_os("BAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    config_dir().join("config")
}

pub fn system_config_file() -> PathBuf {
    let prefix = std::env::var_os("BAT_SYSTEM_CONFIG_PREFIX").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("/etc"));
    prefix.join("bat").join("config")
}

pub fn cache_is_valid(dir: &Path) -> bool {
    let meta = match std::fs::read_to_string(dir.join("metadata.yaml")) {
        Ok(m) => m,
        Err(_) => return false,
    };
    let version = meta
        .lines()
        .find_map(|l| l.strip_prefix("bat_version:"))
        .map(|v| v.trim().trim_matches('"').to_string());
    match version {
        Some(v) => {
            let mine: Vec<&str> = "0.26.1".split('.').collect();
            let theirs: Vec<&str> = v.split('.').collect();
            theirs.len() >= 2 && theirs[0] == mine[0] && theirs[1] == mine[1] && dir.join("syntaxes.bin").exists()
        }
        None => false,
    }
}

fn clear_file(dir: &Path, name: &str, what: &str) {
    print!("Clearing {} ... ", what);
    let p = dir.join(name);
    if p.exists() {
        match std::fs::remove_file(&p) {
            Ok(_) => println!("okay"),
            Err(_) => println!("skipped (not present)"),
        }
    } else {
        println!("skipped (not present)");
    }
}

pub fn clear(dir: &Path) {
    clear_file(dir, "themes.bin", "theme set cache");
    clear_file(dir, "syntaxes.bin", "syntax set cache");
    clear_file(dir, "metadata.yaml", "metadata file");
}

fn dir_has_files(dir: &Path, ext: &str) -> bool {
    match std::fs::read_dir(dir) {
        Ok(rd) => rd.filter_map(|e| e.ok()).any(|e| e.path().extension().map_or(false, |x| x == ext)),
        Err(_) => false,
    }
}

pub fn build(source: &Path, target: &Path, _blank: bool, syntaxes: &[u8], themes: &[u8]) -> Result<(), String> {
    let theme_dir = source.join("themes");
    if !dir_has_files(&theme_dir, "tmTheme") {
        println!("No themes were found in '{}', using the default set", theme_dir.to_string_lossy());
    }
    let syntax_dir = source.join("syntaxes");
    if !dir_has_files(&syntax_dir, "sublime-syntax") {
        println!("No syntaxes were found in '{}', using the default set.", syntax_dir.to_string_lossy());
    }
    std::fs::create_dir_all(target).map_err(|e| e.to_string())?;
    print!("Writing theme set to {} ... ", target.join("themes.bin").to_string_lossy());
    std::fs::write(target.join("themes.bin"), themes).map_err(|e| e.to_string())?;
    println!("okay");
    print!("Writing syntax set to {} ... ", target.join("syntaxes.bin").to_string_lossy());
    std::fs::write(target.join("syntaxes.bin"), syntaxes).map_err(|e| e.to_string())?;
    println!("okay");
    print!("Writing metadata to folder {} ... ", target.to_string_lossy());
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
    let meta = format!(
        "bat_version: 0.26.1\ncreation_time:\n  secs_since_epoch: {}\n  nanos_since_epoch: {}\n",
        now.as_secs(),
        now.subsec_nanos()
    );
    std::fs::write(target.join("metadata.yaml"), meta).map_err(|e| e.to_string())?;
    println!("okay");
    Ok(())
}
