                    print_error(&m);
                    no_errors = false;
                }
            }
        }
        Ok(no_errors)
    }

    fn print_input(
        &self,
        input: &mut OpenedInput,
        out: &mut dyn Write,
        is_first: bool,
        theme_cache: &mut Option<Option<&'a Theme>>,
    ) -> Result<(), PrintError> {
        let config = self.config;
        let line_changes: Option<LineChanges> =
            if config.visible_lines.diff_mode() || (!config.loop_through && config.style.changes()) {
                match &input.kind {
