                        let diff = get_git_diff(path);
                        if config.visible_lines.diff_mode() && diff.as_ref().map_or(false, |c| c.is_empty()) {
                            return Ok(());
                        }
                        diff
                    }
                    _ if config.visible_lines.diff_mode() => return Ok(()),
                    _ => None,
                }
            } else {
                None
            };

        if config.quiet_empty && input.reader.first_line.is_empty() {
            return Ok(());
        }

        let mut printer: Box<dyn Printer + '_> = if config.loop_through {
            Box::new(SimplePrinter::new(config))
        } else {
            let theme = if config.colored_output {
                if theme_cache.is_none() {
                    *theme_cache = Some(crate::app::resolve_theme(config, self.assets));
                } else if let Some(w) = &config.theme_warning {
                    crate::error::print_warning(w);
                }
                theme_cache.unwrap()
            } else {
                None
            };
            let lc = line_changes.clone().filter(|c| !c.is_empty());
            Box::new(InteractivePrinter::new(config, self.assets, theme, input, lc).map_err(PrintError::Msg)?)
        };

        self.print_file(&mut *printer, out, input, !is_first, &line_changes)?;
        Ok(())
    }

    fn print_file(
        &self,
        printer: &mut dyn Printer,
        out: &mut dyn Write,
        input: &mut OpenedInput,
        add_header_padding: bool,
        line_changes: &Option<LineChanges>,
    ) -> Result<(), PrintError> {
        let config = self.config;
        if !input.reader.first_line.is_empty() || config.style.header() {
            printer.print_header(out, input, add_header_padding)?;
        }
        if !input.reader.first_line.is_empty() {
            let ranges = match &config.visible_lines {
                VisibleLines::Ranges(r) => r.clone(),
                VisibleLines::DiffContext(context) => {
                    let mut v = Vec::new();
                    if let Some(lc) = line_changes {
                        let mut keys: Vec<u32> = lc.keys().copied().collect();
                        keys.sort();
                        for line in keys {
                            let line = line as usize;
                            v.push(LineRange::new(line.saturating_sub(*context), line + context));
                        }
                    }
                    LineRanges::from(v)
                }
            };
            self.print_file_ranges(printer, out, input, ranges)?;
        }
        printer.print_footer(out, input)?;
        Ok(())
    }

    fn print_file_ranges(
        &self,
        printer: &mut dyn Printer,
        out: &mut dyn Write,
        input: &mut OpenedInput,
        mut ranges: LineRanges,
    ) -> Result<(), PrintError> {
        let config = self.config;
        let mut lines_buffered: Option<Vec<Vec<u8>>> = None;
        if ranges.needs_total() {
            let mut all = Vec::new();
            loop {
                let mut buf = Vec::new();
                if !input.reader.read_line(&mut buf).map_err(PrintError::Io)? {
                    break;
                }
                all.push(buf);
            }
            ranges.resolve(Some(all.len()));
            all.reverse();
            lines_buffered = Some(all);
        }
        let mut line_buffer = Vec::new();
        let mut line_number: usize = 1;
        let mut first_range = true;
        let mut mid_range = false;
        let style_snip = config.style.snip();
        let mut blank_count = 0usize;
        loop {
            line_buffer.clear();
            let got = match lines_buffered.as_mut() {
                Some(v) => match v.pop() {
                    Some(l) => {
                        line_buffer = l;
                        true
                    }
                    None => false,
                },
                None => input.reader.read_line(&mut line_buffer).map_err(PrintError::Io)?,
            };
            if !got {
                break;
            }
            if let Some(limit) = config.squeeze_lines {
                let is_blank = {
                    let s = String::from_utf8_lossy(&line_buffer);
                    s.trim_end_matches(|c| c == '\r' || c == '\n').is_empty()
                };
                if is_blank {
                    blank_count += 1;
                    if blank_count > limit {
                        line_number += 1;
                        continue;
                    }
                } else {
                    blank_count = 0;
                }
            }
            match ranges.check(line_number) {
                RangeCheck::BeforeOrBetween => {
                    printer.print_line(true, out, line_number, &line_buffer)?;
                    mid_range = false;
                }
                RangeCheck::InRange => {
                    if style_snip {
                        if first_range {
                            first_range = false;
                            mid_range = true;
                        } else if !mid_range {
                            mid_range = true;
                            printer.print_snip(out)?;
                        }
                    }
                    printer.print_line(false, out, line_number, &line_buffer)?;
                }
                RangeCheck::AfterLast => break,
            }
            line_number += 1;
        }
        Ok(())
    }
}

