//! Translate command line matches and environment into a `Config`.

use crate::assets::Assets;
use crate::config::*;
use crate::highlight::theme::Theme;
use crate::input::Input;
use crate::line_range::{LineRange, LineRanges};
use crate::preprocessor::NonprintableNotation;
use crate::syntax_mapping::{MappingTarget, SyntaxMapping};
use clap::ArgMatches;
use std::collections::HashSet;
use std::env;
use std::ffi::OsString;
use std::path::PathBuf;

pub fn env_no_color() -> bool {
    env::var_os("NO_COLOR").map_or(false, |v| !v.is_empty())
}

pub fn is_truecolor_terminal() -> bool {
    env::var("COLORTERM").map(|c| c == "truecolor" || c == "24bit").unwrap_or(false)
}

pub fn terminal_width() -> usize {
    match terminal_size::terminal_size() {
        Some((w, _)) => w.0 as usize,
        None => 80,
    }
}

pub fn get_inputs(m: &ArgMatches) -> Result<Vec<Input>, String> {
    let names: Option<Vec<PathBuf>> = m.get_many::<OsString>("file-name").map(|v| v.map(PathBuf::from).collect());
    let files: Option<Vec<OsString>> = m.get_many::<OsString>("FILE").map(|v| v.cloned().collect());
    if let (Some(n), Some(f)) = (&names, &files) {
        if n.len() != f.len() {
            return Err("Must be one file name per input type.".into());
        }
    }
    let mut name_iter: Box<dyn Iterator<Item = Option<PathBuf>>> = match names {
        Some(n) => Box::new(n.into_iter().map(Some)),
        None => Box::new(std::iter::repeat(None)),
    };
    let files = match files {
        None => return Ok(vec![Input::stdin().with_name(name_iter.next().unwrap_or(None))]),
        Some(f) => f,
    };
    let mut out = Vec::new();
    for f in files {
        let name = name_iter.next().unwrap_or(None);
        if f == "-" {
            out.push(Input::stdin().with_name(name));
        } else {
