    let extra_plain = plain_count > 1;
    let plain_last = m.indices_of("plain").and_then(|i| i.max()).unwrap_or(0);
    let paging_last = m.indices_of("paging").and_then(|i| i.max()).unwrap_or(0);
    let paging_value = if m.value_source("paging") == Some(clap::parser::ValueSource::CommandLine) {
        m.get_one::<String>("paging").cloned()
    } else {
        env::var("BAT_PAGING").ok().or_else(|| m.get_one::<String>("paging").cloned())
    };
    let paging_mode = match paging_value.as_deref() {
        Some("always") => {
            if extra_plain && plain_last > paging_last {
                PagingMode::Never
            } else {
                PagingMode::Always
            }
        }
        Some("never") => PagingMode::Never,
        _ => {
            if extra_plain || m.get_flag("no-paging") {
                PagingMode::Never
            } else if inputs.iter().any(|i| i.is_stdin()) {
                if interactive && !crate::stdin_is_tty() {
                    PagingMode::QuitIfOneScreen
                } else {
                    PagingMode::Never
                }
            } else if interactive {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        }
    };

    let mut mapping = SyntaxMapping::new();
    if let Some(v) = m.get_many::<String>("ignored-suffix") {
        for s in v {
            mapping.insert_ignored_suffix(s);
        }
    }
    if let Some(v) = m.get_many::<String>("map-syntax") {
        for from_to in v {
            let parts: Vec<&str> = from_to.split(':').collect();
            if parts.len() != 2 {
                return Err("Invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.".into());
            }
            mapping.insert(parts[0], MappingTarget::MapTo(parts[1].to_string())).map_err(|e| e.to_string())?;
        }
    }

    let width_arg = m.get_one::<String>("terminal-width").cloned().or_else(|| env::var("BAT_WIDTH").ok());
    let maybe_term_width: Option<usize> = width_arg.and_then(|w| {
        if w.starts_with('+') || w.starts_with('-') {
            w.parse::<i16>().ok().map(|delta| {
                let old = terminal_width() as i32;
                let new = old + delta as i32;
                if new <= 0 {
                    old as usize
                } else {
                    new as usize
                }
            })
        } else {
            w.parse::<usize>().ok().filter(|w| *w > 0)
        }
    });

    let wrapping_mode = if interactive || maybe_term_width.is_some() {
        if m.get_flag("chop-long-lines") {
            WrappingMode::NoWrapping(true)
        } else {
            match m.get_one::<String>("wrap").map(|s| s.as_str()) {
                Some("character") => WrappingMode::Character,
                Some("word") => WrappingMode::Word,
                Some("never") => WrappingMode::NoWrapping(true),
                _ => WrappingMode::Character,
            }
        }
    } else {
        WrappingMode::NoWrapping(false)
    };

    let color = m.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto");
    let decorations = m.get_one::<String>("decorations").map(|s| s.as_str()).unwrap_or("auto");
    let force = m.get_flag("force-colorization");
    let colored_output = force
        || match color {
            "always" => true,
            "never" => false,
            _ => !env_no_color() && interactive,
