    let loop_through = !(interactive || color == "always" || decorations == "always" || force);

    let tab_width = m
        .get_one::<String>("tabs")
        .cloned()
        .or_else(|| env::var("BAT_TABS").ok())
        .and_then(|t| t.parse::<usize>().ok())
        .unwrap_or(if style.plain() && paging_mode == PagingMode::Never { 0 } else { 4 });

    let visible_lines = if m.get_flag("diff") {
        VisibleLines::DiffContext(m.get_one::<String>("diff-context").and_then(|t| t.parse().ok()).unwrap_or(2))
    } else {
        match m.get_many::<String>("line-range") {
            Some(v) => {
                let mut ranges = Vec::new();
                for s in v {
                    ranges.push(LineRange::parse(s)?);
                }
                VisibleLines::Ranges(LineRanges::from(ranges))
            }
            None => VisibleLines::Ranges(LineRanges::all()),
        }
    };

    let highlighted_lines = match m.get_many::<String>("highlight-line") {
        Some(v) => {
            let mut ranges = Vec::new();
            for s in v {
                ranges.push(LineRange::parse(s)?);
            }
            LineRanges::from(ranges)
        }
        None => LineRanges::none(),
    };

    let theme = choose_theme(m);

    let language = m
        .get_one::<String>("language")
        .cloned()
        .or_else(|| if m.get_flag("show-all") { Some("show-nonprintable".to_string()) } else { None });

    Ok(Config {
        language,
        fallback_syntax: m.get_one::<String>("fallback-syntax").cloned(),
        show_nonprintable: m.get_flag("show-all"),
        nonprintable_notation: match m.get_one::<String>("nonprintable-notation").map(|s| s.as_str()) {
            Some("caret") => NonprintableNotation::Caret,
            _ => NonprintableNotation::Unicode,
        },
        binary: match m.get_one::<String>("binary").map(|s| s.as_str()) {
            Some("as-text") => BinaryBehavior::AsText,
            _ => BinaryBehavior::NoPrinting,
        },
        term_width: maybe_term_width.unwrap_or_else(terminal_width),
        tab_width,
        loop_through,
        colored_output,
        true_color: is_truecolor_terminal(),
        style,
        wrapping_mode,
        paging_mode,
        visible_lines,
        theme_name: theme.name,
        theme_warning: theme.warning,
        syntax_mapping: mapping,
        pager: m.get_one::<String>("pager").cloned(),
        use_italic_text: m.get_one::<String>("italic-text").map(|s| s.as_str()) == Some("always"),
        highlighted_lines,
        squeeze_lines: if m.get_flag("squeeze-blank") {
            Some(m.get_one::<String>("squeeze-limit").and_then(|s| s.parse().ok()).unwrap_or(1))
        } else {
            None
        },
        strip_ansi: match m.get_one::<String>("strip-ansi").map(|s| s.as_str()) {
            Some("always") => StripAnsiMode::Always,
            Some("auto") => StripAnsiMode::Auto,
            _ => StripAnsiMode::Never,
        },
        quiet_empty: m.get_flag("quiet-empty"),
        unbuffered,
        set_terminal_title: m.get_flag("set-terminal-title"),
        use_custom_assets: !m.get_flag("no-custom-assets"),
    })
}
