//! Output handling: standard output or a pager process.

use crate::config::{PagingMode, WrappingMode};
use std::io::{self, Write};
use std::process::{Child, Command, Stdio};

pub enum Output {
    Stdout(io::BufWriter<io::Stdout>),
    Pager(Child, io::BufWriter<std::process::ChildStdin>),
}

impl Output {
    pub fn stdout() -> Output {
        Output::Stdout(io::BufWriter::with_capacity(1 << 16, io::stdout()))
    }

    pub fn writer(&mut self) -> &mut dyn Write {
        match self {
            Output::Stdout(w) => w,
            Output::Pager(_, w) => w,
        }
    }

    pub fn is_pager(&self) -> bool {
        matches!(self, Output::Pager(..))
    }

    pub fn finish(self) {
        match self {
            Output::Stdout(mut w) => {
                let _ = w.flush();
            }
            Output::Pager(mut child, w) => {
                drop(w);
                let _ = child.wait();
            }
        }
    }

    pub fn from_mode(mode: PagingMode, wrapping: WrappingMode, pager_arg: Option<&str>) -> Output {
        if mode == PagingMode::Never {
            return Output::stdout();
        }
        let (cmd, from_env_pager) = match pager_arg {
            Some(p) => (p.to_string(), false),
            None => match std::env::var("BAT_PAGER") {
                Ok(p) => (p, false),
                Err(_) => match std::env::var("PAGER") {
                    Ok(p) => (p, true),
                    Err(_) => ("less".to_string(), false),
                },
            },
        };
        let mut words = match crate::shell_words::split(&cmd) {
            Ok(w) => w,
            Err(_) => return Output::stdout(),
        };
        if words.is_empty() {
            return Output::stdout();
        }
        let bin_name = std::path::Path::new(&words[0]).file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
        if from_env_pager && (bin_name == "more" || bin_name == "most") {
            words = vec!["less".to_string()];
        }
        if bin_name == "builtin" && words.len() == 1 {
            return Output::stdout();
        }
        let bin_name = std::path::Path::new(&words[0]).file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
        let mut command = Command::new(&words[0]);
        if bin_name == "less" {
            if words.len() == 1 {
                command.arg("-R");
                if mode == PagingMode::QuitIfOneScreen {
                    command.arg("-F");
                }
                if wrapping == WrappingMode::NoWrapping(true) {
                    command.arg("-S");
                }
            } else {
                command.args(&words[1..]);
            }
            if std::env::var_os("LESSCHARSET").is_none() {
                command.env("LESSCHARSET", "UTF-8");
            }
        } else {
            command.args(&words[1..]);
        }
        command.stdin(Stdio::piped());
        match command.spawn() {
            Ok(mut child) => {
                let stdin = child.stdin.take().unwrap();
                Output::Pager(child, io::BufWriter::new(stdin))
            }
            Err(_) => {
                crate::error::print_warning(&format!("Pager '{}' not found, outputting to stdout instead", words[0]));
                Output::stdout()
            }
        }
    }
}
EOF
