mod ansi;
mod ansi256;
mod app;
mod assets;
mod builtin_mappings;
mod cache;
mod clap_app;
mod config;
mod controller;
mod diagnostic;
mod diff;
mod error;
mod glob;
mod highlight;
mod input;
mod line_range;
mod listing;
mod output;
mod preprocessor;
mod printer;
mod regex;
mod shell_words;
mod syntax;
mod syntax_mapping;
mod terminal;

use std::ffi::OsString;
use std::io::{IsTerminal, Write};
use std::path::PathBuf;

pub fn stdin_is_tty() -> bool {
    std::io::stdin().is_terminal()
}

pub fn stdout_is_tty() -> bool {
    std::io::stdout().is_terminal()
}

fn main() {
    let child = std::thread::Builder::new().stack_size(1 << 30).spawn(run_main).expect("failed to spawn main thread");
    let code = child.join().unwrap_or(1);
    std::process::exit(code);
}

fn args_from_str(content: &str) -> Result<Vec<OsString>, ()> {
    let mut out = Vec::new();
    for line in content.split('\n') {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        for w in shell_words::split(line)? {
            out.push(OsString::from(w));
        }
    }
    Ok(out)
}

fn collect_args() -> Result<Vec<OsString>, String> {
    let cli: Vec<OsString> = std::env::args_os().collect();
    if cli.get(1).map(|a| a == "cache").unwrap_or(false) || cli.iter().skip(1).any(|a| a == "--no-config") {
        return Ok(cli);
    }
    let mut args: Vec<OsString> = Vec::new();
    args.push(cli[0].clone());
    for path in [cache::system_config_file(), cache::config_file()] {
        if let Ok(content) = std::fs::read_to_string(&path) {
            let a = args_from_str(&content).map_err(|_| "Could not parse configuration file".to_string())?;
            args.extend(a);
        }
    }
    if let Ok(opts) = std::env::var("BAT_OPTS") {
        let a = shell_words::split(&opts).map_err(|_| "Could not parse configuration file".to_string())?;
        args.extend(a.into_iter().map(OsString::from));
    }
    args.extend(cli.into_iter().skip(1));
    Ok(args)
}

fn run_main() -> i32 {
    match run() {
        Ok(true) => 0,
        Ok(false) => 1,
        Err(msg) => {
            error::print_error(&msg);
            1
        }
    }
}

fn run() -> Result<bool, String> {
    let interactive = stdout_is_tty();
    let args = collect_args()?;
    let cmd = clap_app::build_app(interactive);
    let matches = match cmd.try_get_matches_from(&args) {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            let code = if e.use_stderr() { 2 } else { 0 };
            std::process::exit(code);
        }
    };

    if let Some(("cache", cm)) = matches.subcommand() {
        let target = cm.get_one::<String>("target").map(PathBuf::from).unwrap_or_else(cache::cache_dir);
        if cm.get_flag("build") {
            let source = cm.get_one::<String>("source").map(PathBuf::from).unwrap_or_else(cache::config_dir);
            cache::build(&source, &target, cm.get_flag("blank"), assets::BUILTIN_SYNTAXES, assets::BUILTIN_THEMES)?;
        } else if cm.get_flag("clear") {
            cache::clear(&target);
        }
        return Ok(true);
    }

    if matches.get_flag("help") {
        let long = std::env::args_os().skip(1).any(|a| a == "--help");
        return print_help(&matches, interactive, long);
    }

    if matches.get_flag("diagnostic") {
        diagnostic::print();
        return Ok(true);
    }

    let inputs = app::get_inputs(&matches)?;
    let config = app::build_config(&matches, interactive, &inputs)?;

    if let Some(shell) = matches.get_one::<String>("completion") {
        let text: &str = match shell.as_str() {
            "bash" => include_str!("../assets/comp_bash.txt"),
            "fish" => include_str!("../assets/comp_fish.txt"),
            "zsh" => include_str!("../assets/comp_zsh.txt"),
            _ => include_str!("../assets/comp_ps1.txt"),
        };
        print!("{}", text);
        return Ok(true);
    }

    let use_custom = config.use_custom_assets;
    let load_assets = || assets::Assets::load(if use_custom { Some(cache::cache_dir()) } else { None }.as_deref());

    if matches.get_flag("list-languages") {
        let a = load_assets();
        let s = listing::list_languages(&config, &a);
        write_paged(&config, &s);
        return Ok(true);
    }
    if matches.get_flag("list-themes") {
        let a = load_assets();
        listing::list_themes(&config, &a);
        return Ok(true);
    }
    if matches.get_flag("config-file") {
        println!("{}", cache::config_file().to_string_lossy());
        return Ok(true);
    }
    if matches.get_flag("generate-config-file") {
        return generate_config_file();
    }
    if matches.get_flag("config-dir") {
        println!("{}", cache::config_dir().to_string_lossy());
        return Ok(true);
    }
    if matches.get_flag("cache-dir") {
        println!("{}", cache::cache_dir().to_string_lossy());
        return Ok(true);
    }
    if matches.get_flag("acknowledgements") {
        let mut so = std::io::stdout().lock();
        let _ = so.write_all(include_str!("../assets/ack.txt").as_bytes());
        return Ok(true);
    }

    let a = load_assets();
    run_controller(inputs, &config, &a, None)
}

fn write_paged(config: &config::Config, s: &str) {
    let mut out = output::Output::from_mode(config.paging_mode, config.wrapping_mode, config.pager.as_deref());
    let _ = out.writer().write_all(s.as_bytes());
    out.finish();
}

pub fn run_controller(inputs: Vec<input::Input>, config: &config::Config, a: &assets::Assets, stdin_override: Option<Vec<u8>>) -> Result<bool, String> {
    let mut paging_mode = config.paging_mode;
    if paging_mode != config::PagingMode::Never {
        let call_pager = inputs.iter().any(|i| match &i.kind {
            input::InputKind::File(p) => p.exists(),
            _ => true,
        });
        if !call_pager {
            paging_mode = config::PagingMode::Never;
        }
    }
    let mut out = output::Output::from_mode(paging_mode, config.wrapping_mode, config.pager.as_deref());
    let ctrl = controller::Controller::new(config, a);
    let res = ctrl.run(inputs, out.writer(), stdin_override);
    match res {
        Ok(ok) => {
            out.finish();
            Ok(ok)
        }
        Err(controller::RunError::BrokenPipe) => {
            std::process::exit(0);
        }
    }
}

fn generate_config_file() -> Result<bool, String> {
    let path = cache::config_file();
    if path.is_file() {
        println!("A config file already exists at: {}", path.to_string_lossy());
        print!("Overwrite? (y/N): ");
        let _ = std::io::stdout().flush();
        let mut answer = String::new();
        let _ = std::io::stdin().read_line(&mut answer);
        if !answer.trim().eq_ignore_ascii_case("y") {
            return Ok(true);
        }
    }
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            let _ = std::fs::create_dir_all(parent);
        }
    }
    match std::fs::write(&path, include_str!("../assets/default_config.txt")) {
        Ok(_) => {
            println!("Success! Config file written to {}", path.to_string_lossy());
            Ok(true)
        }
        Err(e) => Err(format!("Failed to create config file at '{}': {}", path.to_string_lossy(), e)),
    }
}

fn print_help(matches: &clap::ArgMatches, interactive: bool, long: bool) -> Result<bool, String> {
    let mut cmd = clap_app::build_app(interactive);
    let help = if long { cmd.render_long_help() } else { cmd.render_help() };
    let text = help.to_string();
    let color = matches.get_one::<String>("color").map(|s| s.as_str()).unwrap_or("auto");
    let colored = match color {
        "always" => true,
        "never" => false,
        _ => interactive && !app::env_no_color(),
    };
    let theme = app::choose_theme(matches);
    let paging_mode = match matches.get_one::<String>("paging").map(|s| s.as_str()) {
        Some("always") => config::PagingMode::Always,
        Some("never") => config::PagingMode::Never,
        _ => {
            if matches.get_flag("no-paging") || !interactive {
                config::PagingMode::Never
            } else {
                config::PagingMode::QuitIfOneScreen
            }
        }
    };
    let cfg = config::Config {
        language: Some("help".to_string()),
        fallback_syntax: None,
        show_nonprintable: false,
        nonprintable_notation: preprocessor::NonprintableNotation::Unicode,
        binary: config::BinaryBehavior::NoPrinting,
        term_width: app::terminal_width(),
        tab_width: 0,
        loop_through: !colored,
        colored_output: colored,
        true_color: true,
        style: config::StyleComponents::default(),
        wrapping_mode: config::WrappingMode::NoWrapping(false),
        paging_mode,
        visible_lines: config::VisibleLines::Ranges(line_range::LineRanges::all()),
        theme_name: theme.name,
        theme_warning: theme.warning,
        syntax_mapping: syntax_mapping::SyntaxMapping::new(),
        pager: matches.get_one::<String>("pager").cloned(),
        use_italic_text: matches.get_one::<String>("italic-text").map(|s| s.as_str()) == Some("always"),
        highlighted_lines: line_range::LineRanges::none(),
        squeeze_lines: None,
        strip_ansi: config::StripAnsiMode::Never,
        quiet_empty: false,
        unbuffered: false,
        set_terminal_title: false,
        use_custom_assets: false,
    };
    let a = assets::Assets::load(None);
    run_controller(vec![input::Input::stdin()], &cfg, &a, Some(text.into_bytes()))
}
