//! `--diagnostic` output.

pub fn print() {
    let mut s = String::new();
    s.push_str("#### Software version\n\nbat 0.26.1 (4dd824a)\n\n");
    s.push_str("#### Operating system\n\n");
    let os = std::fs::read_to_string("/etc/os-release").ok().and_then(|c| {
        let name = c.lines().find_map(|l| l.strip_prefix("NAME=")).map(|v| v.trim_matches('"').to_string());
        let ver = c.lines().find_map(|l| l.strip_prefix("VERSION_ID=")).map(|v| v.trim_matches('"').to_string());
        match (name, ver) {
            (Some(n), Some(v)) => Some(format!("{} {}", n, v)),
            (Some(n), None) => Some(n),
            _ => None,
        }
    });
    s.push_str(&format!("- OS: Linux ({})\n", os.unwrap_or_else(|| "Unknown".into())));
    let kernel = std::fs::read_to_string("/proc/sys/kernel/osrelease").unwrap_or_default();
    s.push_str(&format!("- Kernel: {}\n\n", kernel.trim()));
    s.push_str("#### Command-line\n\n```bash\n");
    let args: Vec<String> = std::env::args().collect();
    s.push_str(&format!("{} \n```\n\n", args.join(" ")));
