//! `--list-languages` and `--list-themes`.

use crate::assets::Assets;
use crate::config::{Config, StyleComponents};
use crate::syntax_mapping::MappingTarget;
use std::collections::HashMap;
use std::io::Write;
use std::path::Path;

pub fn list_languages(config: &Config, assets: &Assets) -> String {
    let set = &assets.syntaxes;
    let mut langs: Vec<(String, Vec<String>)> = Vec::new();
    for (idx, s) in set.syntaxes.iter().enumerate() {
        if s.hidden || s.file_extensions.is_empty() {
            continue;
        }
        let mut exts = Vec::new();
        for e in &s.file_extensions {
            if e.starts_with('.') || Path::new(e).extension().is_some() {
                exts.push(e.clone());
                continue;
            }
            let test = Path::new("test").with_extension(e);
            if let Ok(found) = assets.syntax_for_path(&test, &config.syntax_mapping) {
                if set.syntaxes[found].name == s.name {
                    exts.push(e.clone());
                }
            }
        }
        let _ = idx;
        langs.push((s.name.clone(), exts));
    }
    langs.sort_by_key(|l| l.0.to_uppercase());

    let mut by_target: HashMap<String, Vec<String>> = HashMap::new();
    for (glob, target) in config.syntax_mapping.all_mappings() {
        if let MappingTarget::MapTo(name) = target {
            by_target.entry(name.clone()).or_default().push(glob.to_string());
        }
    }
    for l in langs.iter_mut() {
        if let Some(extra) = by_target.get(&l.0) {
            l.1.extend(extra.iter().cloned());
        }
    }

    let mut result = String::new();
    if config.loop_through {
        for (name, exts) in &langs {
            result.push_str(&format!("{}:{}\n", name, exts.join(",")));
        }
    } else {
        let longest = langs.iter().map(|l| l.0.len()).max().unwrap_or(32);
        let comma = ", ";
        let sep = " ";
        let desired_width = config.term_width as i64 - longest as i64 - sep.len() as i64;
        for (name, exts) in &langs {
            result.push_str(&format!("{:width$}{}", name, sep, width = longest));
            let mut num_chars: i64 = 0;
            let mut it = exts.iter().peekable();
            while let Some(word) = it.next() {
                let new_chars = (word.len() + comma.len()) as i64;
                if num_chars + new_chars >= desired_width {
                    num_chars = 0;
                    result.push_str(&format!("\n{:width$}{}", "", sep, width = longest));
                }
                num_chars += new_chars;
                if config.colored_output {
                    result.push_str(&format!("\x1b[32m\x1b[32m{}\x1b[0m", word));
                } else {
                    result.push_str(word);
                }
                if it.peek().is_some() {
                    result.push_str(comma);
                }
            }
            result.push('\n');
        }
    }
    result
}

const THEME_PREVIEW: &str = "  // Output the square of a number.\n  fn print_square(num: f64) {\n      let result = f64::powf(num, 2.0);\n      println!(\"The square of {num:.2} is {result:.2}.\");\n  }\n";

pub fn list_themes(config: &Config, assets: &Assets) {
    let stdout = std::io::stdout();
    let names: Vec<String> = assets.theme_names().to_vec();
