            result.push_str(&format!("{}:{}\n", name, exts.join(",")));
        }
    } else {
        let longest = langs.iter().map(|l| l.0.len()).max().unwrap_or(32);
        let comma = ", ";
        let sep = " ";
        let desired_width = config.term_width as i64 - longest as i64 - sep.len() as i64;
        for (name, exts) in &langs {
            result.push_str(&format!("{:width$}{}", name, sep, width = longest));
            let mut num_chars: i64 = 0;
            let mut it = exts.iter().peekable();
            while let Some(word) = it.next() {
                let new_chars = (word.len() + comma.len()) as i64;
                if num_chars + new_chars >= desired_width {
                    num_chars = 0;
                    result.push_str(&format!("\n{:width$}{}", "", sep, width = longest));
                }
                num_chars += new_chars;
                if config.colored_output {
                    result.push_str(&format!("\x1b[32m\x1b[32m{}\x1b[0m", word));
                } else {
                    result.push_str(word);
                }
                if it.peek().is_some() {
                    result.push_str(comma);
                }
            }
            result.push('\n');
        }
    }
    result
}

const THEME_PREVIEW: &str = "  // Output the square of a number.\n  fn print_square(num: f64) {\n      let result = f64::powf(num, 2.0);\n      println!(\"The square of {num:.2} is {result:.2}.\");\n  }\n";

pub fn list_themes(config: &Config, assets: &Assets) {
    let stdout = std::io::stdout();
    let names: Vec<String> = assets.theme_names().to_vec();
    if !config.colored_output {
        let mut out = stdout.lock();
        for n in &names {
            let _ = writeln!(out, "{}", n);
        }
        return;
    }
    let cfg = Config {
        language: Some("Rust".to_string()),
        fallback_syntax: None,
        show_nonprintable: false,
        nonprintable_notation: config.nonprintable_notation,
        binary: config.binary,
        term_width: config.term_width,
        tab_width: config.tab_width,
        loop_through: false,
        colored_output: true,
        true_color: config.true_color,
        style: StyleComponents::default(),
        wrapping_mode: config.wrapping_mode,
        paging_mode: crate::config::PagingMode::Never,
        visible_lines: crate::config::VisibleLines::Ranges(crate::line_range::LineRanges::all()),
        theme_name: String::new(),
        theme_warning: None,
        syntax_mapping: crate::syntax_mapping::SyntaxMapping::new(),
        pager: None,
        use_italic_text: config.use_italic_text,
        highlighted_lines: crate::line_range::LineRanges::none(),
        squeeze_lines: None,
        strip_ansi: crate::config::StripAnsiMode::Never,
        quiet_empty: false,
        unbuffered: false,
        set_terminal_title: false,
        use_custom_assets: false,
    };
    let mut cfg = cfg;
    for n in &names {
        let marker = if n == "Monokai Extended" {
            " (default)"
        } else if n == "Monokai Extended Light" {
            " (default light)"
        } else {
            ""
        };
        {
            let mut out = stdout.lock();
            let _ = write!(out, "\x1b[1m{}\x1b[0m{}\n\n", n, marker);
            let _ = out.flush();
        }
        cfg.theme_name = n.clone();
        let _ = crate::run_controller(vec![crate::input::Input::stdin()], &cfg, assets, Some(THEME_PREVIEW.as_bytes().to_vec()));
        let mut out = stdout.lock();
        let _ = writeln!(out);
    }
    let mut out = stdout.lock();
    let _ = write!(
        out,
        "\nFurther themes can be installed to '{}', and are added to the cache with `bat cache --build`. For more information, see:\n\n  https://github.com/sharkdp/bat#adding-new-themes",
        crate::cache::config_dir().join("themes").to_string_lossy()
    );
    let _ = out.flush();
}
