//! Building custom theme sets from `.tmTheme` files (for `bat cache --build`).

use crate::assets::bincode::Writer;
use std::collections::BTreeMap;
use std::path::Path;

#[derive(Debug, Clone)]
enum PValue {
    Dict(Vec<(String, PValue)>),
    Array(Vec<PValue>),
    Str(String),
    Other,
}

impl PValue {
    fn get(&self, key: &str) -> Option<&PValue> {
        match self {
            PValue::Dict(v) => v.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> Option<&str> {
        match self {
            PValue::Str(s) => Some(s),
            _ => None,
        }
    }
}

fn unescape_xml(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(i) = rest.find('&') {
        out.push_str(&rest[..i]);
        rest = &rest[i..];
        if let Some(j) = rest.find(';') {
            let ent = &rest[1..j];
            let rep = match ent {
                "amp" => Some('&'),
                "lt" => Some('<'),
                "gt" => Some('>'),
                "quot" => Some('"'),
                "apos" => Some('\''),
                _ => {
                    if let Some(h) = ent.strip_prefix("#x") {
                        u32::from_str_radix(h, 16).ok().and_then(char::from_u32)
                    } else if let Some(d) = ent.strip_prefix('#') {
                        d.parse::<u32>().ok().and_then(char::from_u32)
                    } else {
                        None
                    }
                }
            };
            match rep {
                Some(c) => {
                    out.push(c);
                    rest = &rest[j + 1..];
                }
                None => {
                    out.push('&');
                    rest = &rest[1..];
                }
            }
        } else {
            out.push_str(rest);
            rest = "";
        }
    }
    out.push_str(rest);
    out
}

struct XmlParser<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> XmlParser<'a> {
    fn skip_misc(&mut self) {
        loop {
            let rest = &self.s[self.pos..];
            let trimmed = rest.trim_start();
            self.pos += rest.len() - trimmed.len();
            let rest = &self.s[self.pos..];
            if rest.starts_with("<?") {
                match rest.find("?>") {
                    Some(i) => self.pos += i + 2,
                    None => return,
                }
            } else if rest.starts_with("<!--") {
                match rest.find("-->") {
                    Some(i) => self.pos += i + 3,
                    None => return,
                }
            } else if rest.starts_with("<!") {
                match rest.find('>') {
                    Some(i) => self.pos += i + 1,
                    None => return,
                }
            } else {
                return;
            }
        }
    }

    /// Reads a tag like `<name ...>` or `<name/>`; returns (name, self_closing, is_end).
    fn read_tag(&mut self) -> Option<(String, bool, bool)> {
        self.skip_misc();
        let rest = &self.s[self.pos..];
        if !rest.starts_with('<') {
            return None;
        }
        let end = rest.find('>')?;
        let inner = &rest[1..end];
        self.pos += end + 1;
        let is_end = inner.starts_with('/');
        let self_closing = inner.ends_with('/');
        let name: String = inner
            .trim_start_matches('/')
            .trim_end_matches('/')
            .split_whitespace()
            .next()
            .unwrap_or("")
            .to_string();
        Some((name, self_closing, is_end))
    }

    fn read_text_until_close(&mut self, name: &str) -> Option<String> {
        let close = format!("</{}>", name);
        let rest = &self.s[self.pos..];
        let i = rest.find(&close)?;
        let text = &rest[..i];
        self.pos += i + close.len();
        Some(unescape_xml(text))
    }

    fn parse_value(&mut self) -> Option<PValue> {
        let (name, self_closing, is_end) = self.read_tag()?;
        if is_end {
            return None;
        }
        match name.as_str() {
            "dict" => {
                if self_closing {
                    return Some(PValue::Dict(vec![]));
                }
                let mut items = Vec::new();
                loop {
                    let save = self.pos;
                    let (n, _sc, end) = self.read_tag()?;
                    if end && n == "dict" {
                        break;
                    }
                    if n != "key" {
                        self.pos = save;
                        self.parse_value()?;
                        continue;
                    }
                    let key = self.read_text_until_close("key")?;
                    let v = self.parse_value()?;
                    items.push((key, v));
                }
                Some(PValue::Dict(items))
            }
            "array" => {
                if self_closing {
                    return Some(PValue::Array(vec![]));
                }
                let mut items = Vec::new();
                loop {
                    let save = self.pos;
                    let (n, _sc, end) = self.read_tag()?;
                    if end && n == "array" {
                        break;
                    }
                    self.pos = save;
                    items.push(self.parse_value()?);
                }
                Some(PValue::Array(items))
            }
            "string" => {
                if self_closing {
                    return Some(PValue::Str(String::new()));
                }
                Some(PValue::Str(self.read_text_until_close("string")?))
            }
            "plist" => {
                let v = self.parse_value();
                let _ = self.read_tag();
                v
            }
            other => {
                if !self_closing {
                    self.read_text_until_close(other)?;
                }
                Some(PValue::Other)
            }
        }
    }
}

fn parse_plist(s: &str) -> Option<PValue> {
    let mut p = XmlParser { s, pos: 0 };
    p.parse_value()
}

fn parse_color(s: &str) -> Option<[u8; 4]> {
    let rest = s.strip_prefix('#')?;
    let mut d = Vec::new();
    for c in rest.chars() {
        d.push(c.to_digit(16)? as u8);
    }
    Some(match d.len() {
        3 => [d[0], d[1], d[2], 255],
        6 => [d[0] * 16 + d[1], d[2] * 16 + d[3], d[4] * 16 + d[5], 255],
        8 => [d[0] * 16 + d[1], d[2] * 16 + d[3], d[4] * 16 + d[5], d[6] * 16 + d[7]],
        _ => return None,
    })
}

fn parse_font_style(s: &str) -> Option<u8> {
    let mut fs = 0u8;
    for w in s.split_whitespace() {
        match w {
            "bold" => fs |= 1,
            "underline" => fs |= 2,
            "italic" => fs |= 4,
            "normal" | "regular" => {}
            _ => return None,
        }
    }
    Some(fs)
}

fn parse_underline(s: &str) -> Option<u32> {
    match s {
        "underline" => Some(1),
        "stippled_underline" => Some(2),
        "squiggly_underline" => Some(3),
        _ => None,
    }
}

const SETTING_KEYS: [&str; 30] = [
    "foreground",
    "background",
    "caret",
    "lineHighlight",
    "misspelling",
    "minimapBorder",
    "accent",
    "popupCss",
    "phantomCss",
    "bracketContentsForeground",
    "bracketContentsOptions",
    "bracketsForeground",
    "bracketsBackground",
    "bracketsOptions",
    "tagsForeground",
    "tagsOptions",
    "highlight",
    "findHighlight",
    "findHighlightForeground",
    "gutter",
    "gutterForeground",
    "selection",
    "selectionForeground",
    "selectionBorder",
    "inactiveSelection",
    "inactiveSelectionForeground",
    "guide",
    "activeGuide",
    "stackGuide",
    "shadow",
];

fn write_opt_color(w: &mut Writer, c: Option<[u8; 4]>) {
    match c {
        Some(c) => {
            w.u8(1);
            for b in c {
                w.u8(b);
            }
        }
        None => w.u8(0),
    }
}

fn write_scope_stack(w: &mut Writer, scopes: &[&str]) {
    w.u64(0); // clear_stack
    w.u64(scopes.len() as u64);
    for s in scopes {
        w.bytes(s.as_bytes());
    }
}

/// Parse a selector list; returns None if any scope is invalid.
fn parse_selectors(s: &str) -> Option<Vec<(Vec<String>, Vec<Vec<String>>)>> {
    let mut out = Vec::new();
    for sel in s.split(|c| c == ',' || c == '|') {
        let mut path: Vec<String> = Vec::new();
        let mut excludes = Vec::new();
        for (i, part) in sel.split(" -").enumerate() {
            let scopes: Vec<String> = part.split_whitespace().map(|x| x.to_string()).collect();
            for sc in &scopes {
                if sc.split('.').count() > 8 {
                    return None;
                }
            }
            if i == 0 {
                path = scopes;
            } else {
                excludes.push(scopes);
            }
        }
        out.push((path, excludes));
    }
    Some(out)
}

/// Serialize a theme from its plist representation into the dump format.
fn serialize_theme(v: &PValue) -> Option<Vec<u8>> {
    let mut w = Writer::default();
    match v.get("name").and_then(|x| x.as_str()) {
        Some(n) => {
            w.u8(1);
            w.bytes(n.as_bytes());
        }
        None => w.u8(0),
    }
    match v.get("author").and_then(|x| x.as_str()) {
        Some(n) => {
            w.u8(1);
            w.bytes(n.as_bytes());
        }
        None => w.u8(0),
    }
    let items = match v.get("settings") {
        Some(PValue::Array(a)) => a,
        _ => return None,
    };
    let global = items.first()?.get("settings")?;
    let mut values: Vec<Option<PValue>> = SETTING_KEYS.iter().map(|k| global.get(k).cloned()).collect();
    if let Some(PValue::Dict(gs)) = v.get("gutterSettings") {
        for (k, val) in gs {
            let idx = match k.as_str() {
                "background" => 19,
                "foreground" => 20,
                _ => continue,
            };
            if values[idx].as_ref().and_then(|x| x.as_str()).and_then(parse_color).is_none() {
                values[idx] = Some(val.clone());
            }
        }
    }
    for (i, key) in SETTING_KEYS.iter().enumerate() {
        let val = values[i].as_ref().and_then(|x| x.as_str());
        match *key {
            "popupCss" | "phantomCss" => match val {
                Some(s) => {
                    w.u8(1);
                    w.bytes(s.as_bytes());
                }
                None => w.u8(0),
            },
            "bracketContentsOptions" | "bracketsOptions" | "tagsOptions" => match val.and_then(parse_underline) {
                Some(u) => {
                    w.u8(1);
                    w.out.extend_from_slice(&u.to_le_bytes());
                }
                None => w.u8(0),
            },
            _ => write_opt_color(&mut w, val.and_then(parse_color)),
        }
    }
    let mut scope_items: Vec<Vec<u8>> = Vec::new();
    for item in items.iter().skip(1) {
        let scope = match item.get("scope") {
            Some(PValue::Str(s)) => s.clone(),
            None => String::new(),
            _ => continue,
        };
        let settings = match item.get("settings") {
            Some(s @ PValue::Dict(_)) => s,
            _ => continue,
        };
        let sels = match parse_selectors(&scope) {
            Some(s) => s,
            None => continue,
        };
        let fg = match settings.get("foreground") {
            Some(PValue::Str(s)) => match parse_color(s) {
                Some(c) => Some(c),
                None => continue,
            },
            _ => None,
        };
        let bg = match settings.get("background") {
            Some(PValue::Str(s)) => match parse_color(s) {
                Some(c) => Some(c),
                None => continue,
            },
            _ => None,
        };
        let fs = match settings.get("fontStyle") {
            Some(PValue::Str(s)) => match parse_font_style(s) {
                Some(f) => Some(f),
                None => continue,
            },
            Some(_) => continue,
            None => None,
        };
        let mut iw = Writer::default();
        iw.u64(sels.len() as u64);
        for (path, excludes) in &sels {
            let p: Vec<&str> = path.iter().map(|s| s.as_str()).collect();
            write_scope_stack(&mut iw, &p);
            iw.u64(excludes.len() as u64);
            for e in excludes {
                let ee: Vec<&str> = e.iter().map(|s| s.as_str()).collect();
                write_scope_stack(&mut iw, &ee);
            }
        }
        write_opt_color(&mut iw, fg);
        write_opt_color(&mut iw, bg);
        match fs {
            Some(f) => {
                iw.u8(1);
                iw.u8(f);
            }
            None => iw.u8(0),
        }
        scope_items.push(iw.out);
    }
    w.u64(scope_items.len() as u64);
    for it in scope_items {
        w.out.extend_from_slice(&it);
    }
    Some(w.out)
}

fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for chunk in data.chunks(5552) {
        for &x in chunk {
            a += x as u32;
            b += a;
        }
        a %= 65521;
        b %= 65521;
    }
    (b << 16) | a
}

/// zlib stream using stored (uncompressed) deflate blocks.
pub fn zlib_store(data: &[u8]) -> Vec<u8> {
    let mut out = vec![0x78, 0x01];
    if data.is_empty() {
        out.extend_from_slice(&[1, 0, 0, 0xFF, 0xFF]);
    }
    let mut chunks = data.chunks(65535).peekable();
    while let Some(c) = chunks.next() {
        let last = chunks.peek().is_none();
        out.push(if last { 1 } else { 0 });
        let len = c.len() as u16;
        out.extend_from_slice(&len.to_le_bytes());
        out.extend_from_slice(&(!len).to_le_bytes());
        out.extend_from_slice(c);
    }
    out.extend_from_slice(&adler32(data).to_be_bytes());
    out
}

fn collect_tmthemes(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
    let mut entries: Vec<_> = match std::fs::read_dir(dir) {
        Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).collect(),
        Err(_) => return,
    };
    entries.sort();
    for p in entries {
        if p.is_dir() {
            collect_tmthemes(&p, out);
        } else if p.extension().map_or(false, |e| e == "tmTheme") {
            out.push(p);
        }
    }
}

/// Returns the number of custom themes found and the serialized theme set.
pub fn build_theme_set(theme_dir: &Path, blank: bool, default_set: &[u8]) -> (usize, Vec<u8>) {
    let mut map: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    if !blank {
        let mut r = crate::assets::bincode::Reader::new(default_set);
        if let Ok(n) = r.usize() {
            for _ in 0..n {
                let name = match r.string() {
                    Ok(s) => s,
                    Err(_) => break,
                };
                let data = match r.bytes() {
                    Ok(b) => b.to_vec(),
                    Err(_) => break,
                };
                map.insert(name, data);
            }
        }
    }
    let mut files = Vec::new();
    collect_tmthemes(theme_dir, &mut files);
    let mut count = 0;
    for f in files {
        let content = match std::fs::read_to_string(&f) {
            Ok(c) => c,
            Err(_) => continue,
        };
        let pv = match parse_plist(&content) {
            Some(v) => v,
            None => continue,
        };
        if let Some(data) = serialize_theme(&pv) {
            let name = f.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
            map.insert(name, zlib_store(&data));
            count += 1;
        }
    }
    let mut w = Writer::default();
    w.u64(map.len() as u64);
    for (k, v) in map {
        w.bytes(k.as_bytes());
        w.bytes(&v);
    }
    (count, w.out)
}
