p='src/highlight/mod.rs'
s=open(p).read()

# 1. Highlighter: flatten multi selectors into trackers
s=s.replace("""pub struct Highlighter<'t> {
    pub theme: &'t Theme,
    single: Vec<(Scope, StyleModifier)>,
    multi: Vec<(ScopeSelector, StyleModifier)>,
}""","""pub struct Highlighter<'t> {
    pub theme: &'t Theme,
    single: Vec<(Scope, StyleModifier)>,
    multi: Vec<(ScopeSelector, StyleModifier)>,
    /// Flattened list of selector paths to track incrementally: for each multi
    /// selector, its path followed by its excludes.
    tracked: Vec<Vec<Scope>>,
    /// For each multi selector: (index of path tracker, range of exclude trackers).
    multi_index: Vec<(usize, std::ops::Range<usize>)>,
}

const MAX_TRACK: usize = 8;

/// Incremental (greedy, left-to-right) matching state of one selector path.
#[derive(Clone, Copy, Debug)]
struct Tracker {
    idx: u8,
    nd: u8,
    digits: [(u16, u8); MAX_TRACK],
}

impl Tracker {
    const START: Tracker = Tracker { idx: 0, nd: 0, digits: [(0, 0); MAX_TRACK] };
}""")
s=s.replace("""        // deeper selectors first (stable sort)
        single.sort_by(|a, b| b.0.len().cmp(&a.0.len()));
        Highlighter { theme, single, multi }
    }""","""        // deeper selectors first (stable sort)
        single.sort_by(|a, b| b.0.len().cmp(&a.0.len()));
        let mut tracked = Vec::new();
        let mut multi_index = Vec::new();
        for (sel, _) in &multi {
            let pi = tracked.len();
            tracked.push(sel.path.scopes.clone());
            let es = tracked.len();
            for e in &sel.excludes {
                tracked.push(e.scopes.clone());
            }
            multi_index.push((pi, es..tracked.len()));
        }
        Highlighter { theme, single, multi, tracked, multi_index }
    }

    fn advance_trackers(&self, parent: Option<&[Tracker]>, path: &[Scope]) -> Vec<Tracker> {
        let depth = path.len() - 1;
        let scope = path[depth];
        let mut out = Vec::with_capacity(self.tracked.len());
        for (i, sel) in self.tracked.iter().enumerate() {
            let mut t = match parent {
                Some(p) => p[i],
                None => Tracker::START,
            };
            let idx = t.idx as usize;
            if idx < sel.len() && sel[idx].is_prefix_of(scope) {
                let len = sel[idx].len();
                if len > 0 && (t.nd as usize) < MAX_TRACK {
                    t.digits[t.nd as usize] = (depth as u16, len as u8);
                    t.nd += 1;
                }
                t.idx += 1;
            }
            out.push(t);
        }
        out
    }

    fn finalize_with_trackers(&self, cur: &ScoredStyle, trackers: &[Tracker], path: &[Scope]) -> Style {
        let mut new_style = cur.clone();
        for (j, (sel, modif)) in self.multi.iter().enumerate() {
            let (pi, ref ex) = self.multi_index[j];
            let too_long = sel.path.scopes.len() > MAX_TRACK || sel.excludes.iter().any(|e| e.scopes.len() > MAX_TRACK);
            if too_long {
                if let Some(score) = sel.does_match(path) {
                    new_style.apply(&score, modif);
                }
                continue;
            }
