//! A small YAML parser covering the subset used by `.sublime-syntax` files:
//! block mappings and sequences, flow collections, plain / quoted / block
//! scalars and comments.

use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Yaml {
    Str(String),
    Int(i64),
    Real(String),
    Bool(bool),
    Null,
    Seq(Vec<Yaml>),
    Map(Vec<(Yaml, Yaml)>),
}

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Yaml::Str(s) => Some(s),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Yaml::Bool(b) => Some(*b),
            _ => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match self {
            Yaml::Int(i) => Some(*i),
            _ => None,
        }
    }
    pub fn as_vec(&self) -> Option<&Vec<Yaml>> {
        match self {
            Yaml::Seq(v) => Some(v),
            _ => None,
        }
    }
    pub fn as_map(&self) -> Option<&Vec<(Yaml, Yaml)>> {
        match self {
            Yaml::Map(v) => Some(v),
            _ => None,
        }
    }
    pub fn get(&self, key: &str) -> Option<&Yaml> {
        self.as_map()?.iter().find(|(k, _)| k.as_str() == Some(key)).map(|(_, v)| v)
    }
}

fn plain_to_yaml(v: &str) -> Yaml {
    if let Some(h) = v.strip_prefix("0x") {
        if let Ok(i) = i64::from_str_radix(h, 16) {
            return Yaml::Int(i);
        }
    }
    if let Some(o) = v.strip_prefix("0o") {
        if let Ok(i) = i64::from_str_radix(o, 8) {
            return Yaml::Int(i);
        }
    }
    if let Some(p) = v.strip_prefix('+') {
        if let Ok(i) = p.parse::<i64>() {
            return Yaml::Int(i);
        }
    }
    match v {
        "~" | "null" => return Yaml::Null,
        "true" => return Yaml::Bool(true),
        "false" => return Yaml::Bool(false),
        _ => {}
    }
    if let Ok(i) = v.parse::<i64>() {
        return Yaml::Int(i);
    }
    if !v.is_empty() && v.parse::<f64>().is_ok() && v.chars().any(|c| c.is_ascii_digit()) {
        return Yaml::Real(v.to_string());
    }
    Yaml::Str(v.to_string())
}

struct Line<'a> {
    indent: usize,
    content: &'a str,
    raw: &'a str,
}

pub struct Parser<'a> {
    lines: Vec<Line<'a>>,
    i: usize,
    anchors: HashMap<String, Yaml>,
}

fn is_blank_or_comment(content: &str) -> bool {
    let t = content.trim_start();
    t.is_empty() || t.starts_with('#')
}

/// Strip a trailing comment (" #...") from plain text, respecting quotes and brackets.
fn strip_comment(s: &str) -> &str {
    let b = s.as_bytes();
    let mut in_s = false;
    let mut in_d = false;
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if in_d {
            if c == b'\\' {
                i += 2;
                continue;
            }
            if c == b'"' {
                in_d = false;
            }
        } else if in_s {
            if c == b'\'' {
                if i + 1 < b.len() && b[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                in_s = false;
            }
        } else {
            if c == b'#' && (i == 0 || b[i - 1] == b' ' || b[i - 1] == b'\t') {
                return s[..i].trim_end();
            }
            if c == b'"' && (i == 0 || matches!(b[i - 1], b' ' | b'[' | b'{' | b',' | b':')) {
                in_d = true;
            } else if c == b'\'' && (i == 0 || matches!(b[i - 1], b' ' | b'[' | b'{' | b',' | b':')) {
                in_s = true;
            }
        }
        i += 1;
    }
    s.trim_end()
}

/// Find the position of a mapping-key separator ':' (followed by space or end).
fn find_key_sep(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.is_empty() {
        return None;
    }
    if b[0] == b'"' || b[0] == b'\'' {
        // quoted key
        let q = b[0];
        let mut i = 1;
        while i < b.len() {
            if q == b'"' && b[i] == b'\\' {
                i += 2;
                continue;
            }
            if b[i] == q {
                if q == b'\'' && i + 1 < b.len() && b[i + 1] == b'\'' {
                    i += 2;
                    continue;
                }
                let mut j = i + 1;
                while j < b.len() && b[j] == b' ' {
                    j += 1;
                }
                if j < b.len() && b[j] == b':' && (j + 1 == b.len() || b[j + 1] == b' ' || b[j + 1] == b'\t') {
                    return Some(j);
                }
                return None;
            }
            i += 1;
        }
        return None;
    }
    if b[0] == b'[' || b[0] == b'{' || b[0] == b'#' {
        return None;
    }
    let mut i = 0;
    while i < b.len() {
        if b[i] == b':' && (i + 1 == b.len() || b[i + 1] == b' ' || b[i + 1] == b'\t') {
            return Some(i);
        }
        if b[i] == b'#' && i > 0 && (b[i - 1] == b' ' || b[i - 1] == b'\t') {
            return None;
        }
        i += 1;
    }
    None
}

fn parse_double_quoted(s: &str) -> Option<(String, usize)> {
    // s starts with '"'; returns (value, consumed bytes)
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut out = String::new();
    let mut i = 1;
    let mut pending_ws = String::new();
    while i < chars.len() {
        let c = chars[i].1;
        match c {
            '"' => {
                out.push_str(&pending_ws);
                return Some((out, chars[i].0 + 1));
            }
            '\\' => {
                out.push_str(&pending_ws);
                pending_ws.clear();
                i += 1;
                if i >= chars.len() {
                    return None;
                }
                let e = chars[i].1;
                let hex = |n: usize, i: &mut usize| -> Option<char> {
                    let mut v = 0u32;
                    for _ in 0..n {
                        *i += 1;
                        v = v * 16 + chars.get(*i)?.1.to_digit(16)?;
                    }
                    char::from_u32(v)
                };
                match e {
                    '0' => out.push('\0'),
                    'a' => out.push('\x07'),
                    'b' => out.push('\x08'),
                    't' | '\t' => out.push('\t'),
                    'n' => out.push('\n'),
                    'v' => out.push('\x0B'),
                    'f' => out.push('\x0C'),
                    'r' => out.push('\r'),
                    'e' => out.push('\x1B'),
                    ' ' => out.push(' '),
                    '"' => out.push('"'),
                    '/' => out.push('/'),
                    '\\' => out.push('\\'),
                    'N' => out.push('\u{85}'),
                    '_' => out.push('\u{A0}'),
                    'L' => out.push('\u{2028}'),
                    'P' => out.push('\u{2029}'),
                    'x' => out.push(hex(2, &mut i)?),
                    'u' => out.push(hex(4, &mut i)?),
                    'U' => out.push(hex(8, &mut i)?),
                    '\n' => {
                        // escaped line break: skip leading whitespace on next line
                        while i + 1 < chars.len() && (chars[i + 1].1 == ' ' || chars[i + 1].1 == '\t') {
                            i += 1;
                        }
                    }
                    other => {
                        out.push('\\');
                        out.push(other);
                    }
                }
            }
            '\n' => {
                // line folding
                let mut newlines = 1;
                let mut j = i + 1;
                loop {
                    while j < chars.len() && (chars[j].1 == ' ' || chars[j].1 == '\t') {
                        j += 1;
                    }
                    if j < chars.len() && chars[j].1 == '\n' {
                        newlines += 1;
                        j += 1;
                    } else {
                        break;
                    }
                }
                pending_ws.clear();
                if newlines == 1 {
                    out.push(' ');
                } else {
                    for _ in 1..newlines {
                        out.push('\n');
                    }
                }
                i = j;
                continue;
            }
            ' ' | '\t' => {
                pending_ws.push(c);
            }
            _ => {
                out.push_str(&pending_ws);
                pending_ws.clear();
                out.push(c);
            }
        }
        i += 1;
    }
    None
}

fn parse_single_quoted(s: &str) -> Option<(String, usize)> {
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut out = String::new();
    let mut i = 1;
    let mut pending_ws = String::new();
    while i < chars.len() {
        let c = chars[i].1;
        match c {
            '\'' => {
                if i + 1 < chars.len() && chars[i + 1].1 == '\'' {
                    out.push_str(&pending_ws);
                    pending_ws.clear();
                    out.push('\'');
                    i += 2;
                    continue;
                }
                out.push_str(&pending_ws);
                return Some((out, chars[i].0 + 1));
            }
            '\n' => {
                let mut newlines = 1;
                let mut j = i + 1;
                loop {
                    while j < chars.len() && (chars[j].1 == ' ' || chars[j].1 == '\t') {
                        j += 1;
                    }
                    if j < chars.len() && chars[j].1 == '\n' {
                        newlines += 1;
                        j += 1;
                    } else {
                        break;
                    }
                }
                pending_ws.clear();
                if newlines == 1 {
                    out.push(' ');
                } else {
                    for _ in 1..newlines {
                        out.push('\n');
                    }
                }
                i = j;
                continue;
            }
            ' ' | '\t' => pending_ws.push(c),
            _ => {
                out.push_str(&pending_ws);
                pending_ws.clear();
                out.push(c);
            }
        }
        i += 1;
    }
    None
}

/// Parse a flow collection or scalar from text; returns value and consumed bytes.
fn parse_flow(s: &str, anchors: &HashMap<String, Yaml>) -> Option<(Yaml, usize)> {
    let b = s.as_bytes();
    let mut i = 0;
    let skip_ws = |i: &mut usize| {
        while *i < b.len() && matches!(b[*i], b' ' | b'\t' | b'\n' | b'\r') {
            *i += 1;
        }
    };
    skip_ws(&mut i);
    if i >= b.len() {
        return Some((Yaml::Null, i));
    }
    match b[i] {
        b'[' => {
            i += 1;
            let mut items = Vec::new();
            loop {
                skip_ws(&mut i);
                if i >= b.len() {
                    return None;
                }
                if b[i] == b']' {
                    i += 1;
                    break;
                }
                let (v, n) = parse_flow_item(&s[i..], anchors, true)?;
                i += n;
                skip_ws(&mut i);
                // single-pair mapping inside a sequence: [a: b]
                let v = if i < b.len() && b[i] == b':' {
                    i += 1;
                    let (v2, n2) = parse_flow_item(&s[i..], anchors, true)?;
                    i += n2;
                    Yaml::Map(vec![(v, v2)])
                } else {
                    v
                };
                items.push(v);
                skip_ws(&mut i);
                if i < b.len() && b[i] == b',' {
                    i += 1;
                }
            }
            Some((Yaml::Seq(items), i))
        }
        b'{' => {
            i += 1;
            let mut items = Vec::new();
            loop {
                skip_ws(&mut i);
                if i >= b.len() {
                    return None;
                }
                if b[i] == b'}' {
                    i += 1;
                    break;
                }
                let (k, n) = parse_flow_item(&s[i..], anchors, true)?;
                i += n;
                skip_ws(&mut i);
                let v = if i < b.len() && b[i] == b':' {
                    i += 1;
                    let (v, n2) = parse_flow_item(&s[i..], anchors, true)?;
                    i += n2;
                    v
                } else {
                    Yaml::Null
                };
                items.push((k, v));
                skip_ws(&mut i);
                if i < b.len() && b[i] == b',' {
                    i += 1;
                }
            }
            Some((Yaml::Map(items), i))
        }
        _ => parse_flow_item(s, anchors, false),
    }
}

fn parse_flow_item(s: &str, anchors: &HashMap<String, Yaml>, in_flow: bool) -> Option<(Yaml, usize)> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\r') {
        i += 1;
    }
    if i >= b.len() {
        return Some((Yaml::Null, i));
    }
    match b[i] {
        b'[' | b'{' => {
            let (v, n) = parse_flow(&s[i..], anchors)?;
            Some((v, i + n))
        }
        b'"' => {
            let (v, n) = parse_double_quoted(&s[i..])?;
            Some((Yaml::Str(v), i + n))
        }
        b'\'' => {
            let (v, n) = parse_single_quoted(&s[i..])?;
            Some((Yaml::Str(v), i + n))
        }
        b'*' => {
            let start = i + 1;
            let mut j = start;
            while j < b.len() && !matches!(b[j], b' ' | b',' | b']' | b'}' | b'\n') {
                j += 1;
            }
            let name = &s[start..j];
            Some((anchors.get(name).cloned().unwrap_or(Yaml::Null), j))
        }
        _ => {
            let start = i;
            let mut j = i;
            while j < b.len() {
                let c = b[j];
                if in_flow && matches!(c, b',' | b']' | b'}') {
                    break;
                }
                if c == b':' && (j + 1 == b.len() || matches!(b[j + 1], b' ' | b'\n' | b',' | b']' | b'}')) && in_flow {
                    break;
                }
                if c == b'#' && j > start && matches!(b[j - 1], b' ' | b'\t') {
                    break;
                }
                j += 1;
            }
            let raw = s[start..j].trim();
            // fold internal newlines
            let folded: Vec<&str> = raw.split('\n').map(|l| l.trim()).collect();
            let text = folded.join(" ");
            Some((plain_to_yaml(&text), j))
        }
    }
}

impl<'a> Parser<'a> {
    pub fn new(text: &'a str) -> Parser<'a> {
        let mut lines = Vec::new();
        for raw in text.split('\n') {
            let raw = raw.strip_suffix('\r').unwrap_or(raw);
            let indent = raw.len() - raw.trim_start_matches(' ').len();
            lines.push(Line { indent, content: &raw[indent..], raw });
        }
        Parser { lines, i: 0, anchors: HashMap::new() }
    }

    fn skip_blank(&mut self) {
        while self.i < self.lines.len() && is_blank_or_comment(self.lines[self.i].content) {
            self.i += 1;
        }
    }

    pub fn parse_document(&mut self) -> Option<Yaml> {
        // skip directives and document start
        loop {
            self.skip_blank();
            if self.i >= self.lines.len() {
                return None;
            }
            let c = self.lines[self.i].content;
            if c.starts_with('%') && self.lines[self.i].indent == 0 {
                self.i += 1;
                continue;
            }
            if c == "---" || c.starts_with("--- ") {
                let rest = c[3..].trim();
                self.i += 1;
                if !rest.is_empty() && !rest.starts_with('#') {
                    let (v, _) = parse_flow(rest, &self.anchors)?;
                    return Some(v);
                }
                continue;
            }
            break;
        }
        let ind = self.lines[self.i].indent;
        Some(self.parse_block(ind))
    }

    fn parse_block(&mut self, min_indent: usize) -> Yaml {
        self.skip_blank();
        if self.i >= self.lines.len() {
            return Yaml::Null;
        }
        let line = &self.lines[self.i];
        if line.indent < min_indent || line.content == "---" || line.content == "..." {
            return Yaml::Null;
        }
        let ind = line.indent;
        let content = line.content;
        if content == "-" || content.starts_with("- ") {
            return self.parse_sequence(ind);
        }
        if find_key_sep(strip_comment(content)).is_some() {
            return self.parse_mapping(ind, None);
        }
        // scalar block
        let text = content.to_string();
        self.i += 1;
        self.parse_value_text(&text, ind.saturating_sub(1))
    }

    fn parse_sequence(&mut self, ind: usize) -> Yaml {
        let mut items = Vec::new();
        loop {
            self.skip_blank();
            if self.i >= self.lines.len() {
                break;
            }
            let line = &self.lines[self.i];
            if line.indent != ind || !(line.content == "-" || line.content.starts_with("- ")) {
                break;
            }
            let rest_full = &line.content[1..];
            let rest = rest_full.trim_start();
            let col = ind + 1 + (rest_full.len() - rest.len());
            if is_blank_or_comment(rest) {
                self.i += 1;
                items.push(self.parse_block(ind + 1));
                continue;
            }
            if rest == "-" || rest.starts_with("- ") {
                // nested sequence on the same line: rewrite the line virtually
                let raw = self.lines[self.i].raw;
                self.lines[self.i] = Line { indent: col, content: &raw[col..], raw };
                items.push(self.parse_sequence(col));
                continue;
            }
            if find_key_sep(strip_comment(rest)).is_some() && !rest.starts_with('[') && !rest.starts_with('{') {
                let raw = self.lines[self.i].raw;
                self.lines[self.i] = Line { indent: col, content: &raw[col..], raw };
                items.push(self.parse_mapping(col, None));
                continue;
            }
            let text = rest.to_string();
            self.i += 1;
            items.push(self.parse_value_text(&text, ind));
        }
        Yaml::Seq(items)
    }

    fn parse_mapping(&mut self, ind: usize, _first: Option<()>) -> Yaml {
        let mut items: Vec<(Yaml, Yaml)> = Vec::new();
        loop {
            self.skip_blank();
            if self.i >= self.lines.len() {
                break;
            }
            let line = &self.lines[self.i];
            if line.indent != ind {
                break;
            }
            let content = line.content;
            if content == "---" || content == "..." {
                break;
            }
            let sep = match find_key_sep(content) {
                Some(s) => s,
                None => break,
            };
            let key_text = content[..sep].trim();
            let key = if key_text.starts_with('"') {
                parse_double_quoted(key_text).map(|(v, _)| Yaml::Str(v)).unwrap_or(Yaml::Str(key_text.to_string()))
            } else if key_text.starts_with('\'') {
                parse_single_quoted(key_text).map(|(v, _)| Yaml::Str(v)).unwrap_or(Yaml::Str(key_text.to_string()))
            } else {
                plain_to_yaml(key_text)
            };
            let rest = content[sep + 1..].trim_start();
            let rest_nc = strip_comment(rest);
            self.i += 1;
            let value = if rest_nc.is_empty() {
                // nested block (may be a sequence at the same indentation)
                self.skip_blank();
                if self.i < self.lines.len() {
                    let l = &self.lines[self.i];
                    if l.indent == ind && (l.content == "-" || l.content.starts_with("- ")) {
                        self.parse_sequence(ind)
                    } else if l.indent > ind {
                        self.parse_block(ind + 1)
                    } else {
                        Yaml::Null
                    }
                } else {
                    Yaml::Null
                }
            } else {
                self.parse_value_text(rest, ind)
            };
            items.push((key, value));
        }
        Yaml::Map(items)
    }

    /// Parse a value whose text starts on the current (already consumed) line.
    fn parse_value_text(&mut self, text: &str, parent_indent: usize) -> Yaml {
        let mut text = text.trim_start().to_string();
        // anchors
        let mut anchor: Option<String> = None;
        if text.starts_with('&') {
            let end = text.find(' ').unwrap_or(text.len());
            anchor = Some(text[1..end].to_string());
            text = text[end..].trim_start().to_string();
            if strip_comment(&text).is_empty() {
                let v = self.parse_block(parent_indent + 1);
                if let Some(a) = anchor {
                    self.anchors.insert(a, v.clone());
                }
                return v;
            }
        }
        // tags are ignored
        if text.starts_with("!!") {
            let end = text.find(' ').unwrap_or(text.len());
            text = text[end..].trim_start().to_string();
        }
        let v = if text.starts_with('|') || text.starts_with('>') {
            self.parse_block_scalar(&text, parent_indent)
        } else if text.starts_with('"') || text.starts_with('\'') || text.starts_with('[') || text.starts_with('{') {
            // may span multiple lines
            let mut buf = text.clone();
            loop {
                let parsed = if text.starts_with('"') {
                    parse_double_quoted(&buf).map(|(v, _)| Yaml::Str(v))
                } else if text.starts_with('\'') {
                    parse_single_quoted(&buf).map(|(v, _)| Yaml::Str(v))
                } else {
                    parse_flow(&buf, &self.anchors).map(|(v, _)| v)
                };
                if let Some(p) = parsed {
                    break p;
                }
                if self.i >= self.lines.len() {
                    break Yaml::Str(buf);
                }
                buf.push('\n');
                buf.push_str(self.lines[self.i].raw);
                self.i += 1;
            }
        } else if text.starts_with('*') {
            let name = strip_comment(&text[1..]).trim().to_string();
            self.anchors.get(&name).cloned().unwrap_or(Yaml::Null)
        } else {
            // plain scalar, possibly continued on following more-indented lines
            let mut parts = vec![strip_comment(&text).to_string()];
            while self.i < self.lines.len() {
                let l = &self.lines[self.i];
                if l.content.trim().is_empty() {
                    // blank line inside plain scalar
                    let mut j = self.i + 1;
                    while j < self.lines.len() && self.lines[j].content.trim().is_empty() {
                        j += 1;
                    }
                    if j < self.lines.len() && self.lines[j].indent > parent_indent && !self.lines[j].content.starts_with('#') {
                        for _ in self.i..j {
                            parts.push("\n".to_string());
                        }
                        self.i = j;
                        continue;
                    }
                    break;
                }
                if l.indent <= parent_indent || l.content.starts_with('#') {
                    break;
                }
                if find_key_sep(l.content).is_some() || l.content.starts_with("- ") {
                    break;
                }
                parts.push(strip_comment(l.content).to_string());
                self.i += 1;
            }
            let mut s = String::new();
            let mut prev_nl = true;
            for p in parts {
                if p == "\n" {
                    s.push('\n');
                    prev_nl = true;
                    continue;
                }
                if !prev_nl && !s.is_empty() {
                    s.push(' ');
                }
                s.push_str(p.trim());
                prev_nl = false;
            }
            plain_to_yaml(&s)
        };
        if let Some(a) = anchor {
            self.anchors.insert(a, v.clone());
        }
        v
    }

    fn parse_block_scalar(&mut self, header: &str, parent_indent: usize) -> Yaml {
        let header = strip_comment(header);
        let literal = header.starts_with('|');
        let mut chomp = 'c';
        let mut explicit: Option<usize> = None;
        for c in header[1..].chars() {
            match c {
                '-' => chomp = '-',
                '+' => chomp = '+',
                d if d.is_ascii_digit() => explicit = d.to_digit(10).map(|x| x as usize),
                _ => {}
            }
        }
        // collect lines
        let mut raw_lines: Vec<&str> = Vec::new();
        let mut block_indent: Option<usize> = explicit.map(|e| parent_indent + e);
        while self.i < self.lines.len() {
            let l = &self.lines[self.i];
            let is_blank = l.raw.trim().is_empty();
            if is_blank {
                raw_lines.push(l.raw);
                self.i += 1;
                continue;
            }
            let bi = match block_indent {
                Some(b) => b,
                None => {
                    if l.indent <= parent_indent {
                        break;
                    }
                    block_indent = Some(l.indent);
                    l.indent
                }
            };
            if l.indent < bi {
                break;
            }
            raw_lines.push(l.raw);
            self.i += 1;
        }
        // trailing blank lines belong to the scalar only for chomping purposes
        let bi = block_indent.unwrap_or(parent_indent + 1);
        let mut content_lines: Vec<String> = raw_lines
            .iter()
            .map(|l| if l.len() >= bi { l[bi..].to_string() } else { String::new() })
            .collect();
        let mut trailing_blank = 0;
        while content_lines.last().map_or(false, |l| l.trim().is_empty()) {
            content_lines.pop();
            trailing_blank += 1;
        }
        let mut s = String::new();
        if literal {
            for (k, l) in content_lines.iter().enumerate() {
                if k > 0 {
                    s.push('\n');
                }
                s.push_str(l);
            }
        } else {
            let mut prev_more_indented = false;
            let mut prev_empty = false;
            for (k, l) in content_lines.iter().enumerate() {
                let empty = l.is_empty();
                let more = l.starts_with(' ') || l.starts_with('\t');
                if k > 0 {
                    if empty {
                        s.push('\n');
                    } else if prev_empty {
                        // newlines already emitted for empty lines
                        if more || prev_more_indented {
                            s.push('\n');
                        }
                    } else if more || prev_more_indented {
                        s.push('\n');
                    } else {
                        s.push(' ');
                    }
                }
                s.push_str(l);
                prev_more_indented = more;
                prev_empty = empty;
            }
        }
        match chomp {
            '-' => {}
            '+' => {
                if !content_lines.is_empty() {
                    s.push('\n');
                }
                for _ in 0..trailing_blank {
                    s.push('\n');
                }
            }
            _ => {
                if !content_lines.is_empty() {
                    s.push('\n');
                }
            }
        }
        Yaml::Str(s)
    }
}

pub fn load(text: &str) -> Option<Yaml> {
    let mut p = Parser::new(text);
    p.parse_document()
}
