cat > /workspace/src/syntax_build.rs <<'EOF'
//! Compiling `.sublime-syntax` definitions into the syntax dump format
//! (for `bat cache --build`).

use crate::assets::bincode::{Reader, Res, Writer};
use crate::assets::inflate::zlib_decode;
use crate::theme_build::zlib_store;
use crate::yaml::{self, Yaml};
use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
enum Ref {
    Named(String),
    ByScope { scope: String, sub: Option<String>, esc: bool },
    File { name: String, sub: Option<String>, esc: bool },
    Inline(String),
    Direct(usize, usize),
}

#[derive(Clone, Debug)]
enum Op {
    Push(Vec<Ref>),
    Set(Vec<Ref>),
    Pop,
    None,
}

#[derive(Clone, Debug)]
struct MatchPat {
    has_captures: bool,
    regex: String,
    scope: Vec<String>,
    captures: Option<Vec<(usize, Vec<String>)>>,
    op: Op,
    with_proto: Option<Ref>,
}

#[derive(Clone, Debug)]
enum Pat {
    Match(MatchPat),
    Include(Ref),
}

#[derive(Clone, Copy, Debug)]
enum Clear {
    TopN(usize),
    All,
}

#[derive(Clone, Debug)]
struct Ctx {
    meta_scope: Vec<String>,
    meta_content_scope: Vec<String>,
    mip: bool,
    clear: Option<Clear>,
    proto: Option<(usize, usize)>,
    backrefs: bool,
    patterns: Vec<Pat>,
}

impl Ctx {
    fn new(mip: bool) -> Ctx {
        Ctx { meta_scope: vec![], meta_content_scope: vec![], mip, clear: None, proto: None, backrefs: false, patterns: vec![] }
    }
}

struct Def {
    name: String,
    exts: Vec<String>,
    scope: String,
    flm: Option<String>,
    hidden: bool,
    variables: Vec<(String, String)>,
    contexts: HashMap<String, Ctx>,
    path: String,
}

struct Namer {
    name: String,
    idx: Option<usize>,
}

impl Namer {
    fn new(name: &str) -> Namer {
        Namer { name: name.to_string(), idx: None }
    }
    fn next(&mut self) -> String {
        let n = match self.idx {
            Some(i) => format!("#anon_{}_{}", self.name, i),
            None => self.name.clone(),
        };
        self.idx = Some(self.idx.map(|i| i + 1).unwrap_or(0));
        n
    }
}

struct State {
    variables: HashMap<String, String>,
}

fn scopes_of(s: &str) -> Vec<String> {
    s.split_whitespace().map(|x| x.to_string()).collect()
}

fn resolve_variables(raw: &str, st: &State, depth: usize) -> String {
    let mut out = String::new();
    let mut rest = raw;
    while let Some(start) = rest.find("{{") {
        let after = &rest[start + 2..];
        let name_len = after.bytes().take_while(|b| b.is_ascii_alphanumeric() || *b == b'_').count();
        if name_len > 0 && after[name_len..].starts_with("}}") {
            out.push_str(&rest[..start]);
            let name = &after[..name_len];
            let val = st.variables.get(name).map(|s| s.as_str()).unwrap_or("");
            if depth < 64 {
                out.push_str(&resolve_variables(val, st, depth + 1));
            }
            rest = &after[name_len + 2..];
        } else {
            out.push_str(&rest[..start + 2]);
            rest = after;
        }
    }
    out.push_str(rest);
    out
}

/// Skips a character class starting at `i` (which points at '['); returns the end index.
fn skip_class(b: &[u8], mut i: usize) -> usize {
    i += 1;
    if i < b.len() && b[i] == b'^' {
        i += 1;
    }
    if i < b.len() && b[i] == b']' {
        i += 1;
    }
    let mut nesting = 0;
    while i < b.len() {
        match b[i] {
            b'\\' => {
                i += 2;
                continue;
            }
            b'[' => nesting += 1,
            b']' => {
                if nesting == 0 {
                    return i + 1;
                }
                nesting -= 1;
            }
            _ => {}
        }
        i += 1;
    }
    b.len()
}

fn regex_for_newlines(regex: String) -> String {
    if !regex.contains('$') {
        return regex;
    }
    let b = regex.as_bytes();
    let mut out: Vec<u8> = Vec::with_capacity(b.len() + 16);
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'$' => {
                out.extend_from_slice(b"(?m:$)");
                i += 1;
            }
            b'\\' => {
                out.push(b[i]);
                if i + 1 < b.len() {
                    out.push(b[i + 1]);
                }
                i += 2;
            }
            b'[' => {
                let end = skip_class(b, i);
                out.extend_from_slice(&b[i..end.min(b.len())]);
                i = end;
            }
            c => {
                out.push(c);
                i += 1;
            }
        }
    }
    String::from_utf8(out).unwrap_or_default()
}

fn replace_posix(regex: String) -> String {
    regex
        .replace("[:alpha:]", "\\p{L}")
        .replace("[:alnum:]", "\\p{L}\\p{N}")
        .replace("[:lower:]", "\\p{Ll}")
        .replace("[:upper:]", "\\p{Lu}")
        .replace("[:digit:]", "\\p{Nd}")
}

fn parse_regex(raw: &str, st: &State) -> String {
    regex_for_newlines(replace_posix(resolve_variables(raw, st, 0)))
}

fn consuming_capture_indexes(regex: &str) -> Vec<usize> {
    let b = regex.as_bytes();
    let mut result = vec![0usize];
    let mut stack = vec![false];
    let mut cap = 0usize;
    let mut in_look = false;
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'\\' => i += 2,
            b'[' => i = skip_class(b, i),
            b'(' => {
                i += 1;
                stack.push(in_look);
                if i < b.len() {
                    if b[i] != b'?' {
                        cap += 1;
                        if !in_look {
                            result.push(cap);
                        }
                    } else {
                        i += 1;
                        if i < b.len() {
                            let c3 = b[i];
                            i += 1;
                            if c3 == b'=' || c3 == b'!' {
                                in_look = true;
                            } else if c3 == b'<' {
                                if i < b.len() && (b[i] == b'=' || b[i] == b'!') {
                                    i += 1;
                                    in_look = true;
                                }
                            } else if c3 == b'P' && i < b.len() && b[i] == b'<' {
                                cap += 1;
                                if !in_look {
                                    result.push(cap);
                                }
                            }
                        }
                    }
                }
            }
            b')' => {
                if let Some(v) = stack.pop() {
                    in_look = v;
                }
                i += 1;
            }
            _ => i += 1,
        }
    }
    result
}

fn has_backref(regex: &str) -> bool {
    let b = regex.as_bytes();
    (0..b.len().saturating_sub(1)).any(|i| b[i] == b'\\' && b[i + 1].is_ascii_digit())
}

fn parse_reference(y: &Yaml, st: &State, ctxs: &mut HashMap<String, Ctx>, namer: &mut Namer, esc: bool) -> Result<Ref, String> {
    if let Some(s) = y.as_str() {
        let parts: Vec<&str> = s.split('#').collect();
        let sub = if parts.len() > 1 { Some(parts[1].to_string()) } else { None };
        if let Some(sc) = parts[0].strip_prefix("scope:") {
            Ok(Ref::ByScope { scope: sc.trim().to_string(), sub, esc })
        } else if parts[0].ends_with(".sublime-syntax") {
            let stem = Path::new(parts[0]).file_stem().map(|x| x.to_string_lossy().into_owned()).ok_or("bad file reference")?;
            Ok(Ref::File { name: stem, sub, esc })
        } else {
            Ok(Ref::Named(s.to_string()))
        }
    } else if let Some(v) = y.as_vec() {
        let name = parse_context(v, st, ctxs, false, namer)?;
        Ok(Ref::Inline(name))
    } else {
        Err("type mismatch in context reference".into())
    }
}

fn parse_pushargs(y: &Yaml, st: &State, ctxs: &mut HashMap<String, Ctx>, namer: &mut Namer) -> Result<Vec<Ref>, String> {
    let multi = y.as_vec().map_or(false, |v| {
        !v.is_empty() && (v[0].as_str().is_some() || v[0].as_vec().map_or(false, |vv| !vv.is_empty() && vv[0].as_map().is_some()))
    });
    if multi {
        y.as_vec().unwrap().iter().map(|x| parse_reference(x, st, ctxs, namer, false)).collect()
    } else {
        Ok(vec![parse_reference(y, st, ctxs, namer, false)?])
    }
}

fn map_from(pairs: Vec<(&str, Yaml)>) -> Yaml {
    Yaml::Map(pairs.into_iter().map(|(k, v)| (Yaml::Str(k.to_string()), v)).collect())
}

fn parse_match(map: &Yaml, st: &State, ctxs: &mut HashMap<String, Ctx>, namer: &mut Namer) -> Result<MatchPat, String> {
    let raw = map.get("match").and_then(|x| x.as_str()).ok_or("missing mandatory key 'match'")?;
    let regex = parse_regex(raw, st);
    let scope = map.get("scope").and_then(|x| x.as_str()).map(scopes_of).unwrap_or_default();
    let captures = match map.get("captures").and_then(|x| x.as_map()) {
        Some(m) => {
            let valid = consuming_capture_indexes(&regex);
            let mut caps = Vec::new();
            for (k, v) in m {
                if let (Some(ki), Some(vs)) = (k.as_i64(), v.as_str()) {
                    if ki >= 0 && valid.contains(&(ki as usize)) {
                        caps.push((ki as usize, scopes_of(vs)));
                    }
                }
            }
            Some(caps)
        }
        None => None,
    };
    let mut has_captures = false;
    let op = if map.get("pop").is_some() {
        has_captures = has_backref(&regex);
        Op::Pop
    } else if let Some(y) = map.get("push") {
        Op::Push(parse_pushargs(y, st, ctxs, namer)?)
    } else if let Some(y) = map.get("set") {
        Op::Set(parse_pushargs(y, st, ctxs, namer)?)
    } else if let Some(y) = map.get("embed") {
        let mut items = vec![map_from(vec![("meta_include_prototype", Yaml::Bool(false))])];
        if let Some(s) = map.get("embed_scope") {
            items.push(map_from(vec![("meta_content_scope", s.clone())]));
        }
        match map.get("escape") {
            Some(v) => {
                let mut mm = vec![("match", v.clone()), ("pop", Yaml::Bool(true))];
                if let Some(c) = map.get("escape_captures") {
                    mm.push(("captures", c.clone()));
                }
                items.push(map_from(mm));
                let esc_ctx = parse_context(&items, st, ctxs, false, namer)?;
                Op::Push(vec![Ref::Inline(esc_ctx), parse_reference(y, st, ctxs, namer, true)?])
            }
            None => return Err("missing mandatory key 'escape'".into()),
        }
    } else {
        Op::None
    };
    let with_proto = if let Some(v) = map.get("with_prototype").and_then(|x| x.as_vec()) {
        Some(Ref::Inline(parse_context(v, st, ctxs, true, namer)?))
    } else if let Some(v) = map.get("escape") {
        let sub = namer.next();
        let mut c = Ctx::new(false);
        let m = map_from(vec![
            ("match", Yaml::Str(format!("(?={})", v.as_str().unwrap_or("")))),
            ("pop", Yaml::Bool(true)),
        ]);
        let p = parse_match(&m, st, ctxs, namer)?;
        if p.has_captures {
            c.backrefs = true;
        }
        c.patterns.push(Pat::Match(p));
        ctxs.insert(sub.clone(), c);
        Some(Ref::Inline(sub))
    } else {
        None
    };
    Ok(MatchPat { has_captures, regex, scope, captures, op, with_proto })
}

fn parse_context(items: &[Yaml], st: &State, ctxs: &mut HashMap<String, Ctx>, is_proto: bool, namer: &mut Namer) -> Result<String, String> {
    let mut c = Ctx::new(!is_proto);
    let name = namer.next();
    for y in items {
        if y.as_map().is_none() {
            return Err("type mismatch in context".into());
        }
        let mut special = false;
        if let Some(x) = y.get("meta_scope").and_then(|x| x.as_str()) {
            c.meta_scope = scopes_of(x);
            special = true;
        }
        if let Some(x) = y.get("meta_content_scope").and_then(|x| x.as_str()) {
            c.meta_content_scope = scopes_of(x);
            special = true;
        }
        if let Some(x) = y.get("meta_include_prototype").and_then(|x| x.as_bool()) {
            c.mip = x;
            special = true;
        }
        if let Some(true) = y.get("clear_scopes").and_then(|x| x.as_bool()) {
            c.clear = Some(Clear::All);
            special = true;
        }
        if let Some(x) = y.get("clear_scopes").and_then(|x| x.as_i64()) {
            c.clear = Some(Clear::TopN(x as usize));
            special = true;
        }
        if !special {
            if let Some(x) = y.get("include") {
                let r = parse_reference(x, st, ctxs, namer, false)?;
                c.patterns.push(Pat::Include(r));
            } else {
                let p = parse_match(y, st, ctxs, namer)?;
                if p.has_captures {
                    c.backrefs = true;
                }
                c.patterns.push(Pat::Match(p));
            }
        }
    }
    ctxs.insert(name.clone(), c);
    Ok(name)
}

fn load_definition(text: &str, fallback_name: &str, path: &str) -> Result<Def, String> {
    let doc = yaml::load(text).ok_or("empty file")?;
    if doc.as_map().is_none() {
        return Err("type mismatch".into());
    }
    let mut variables: Vec<(String, String)> = Vec::new();
    if let Some(m) = doc.get("variables").and_then(|x| x.as_map()) {
        for (k, v) in m {
            if let (Some(ks), Some(vs)) = (k.as_str(), v.as_str()) {
                variables.retain(|(kk, _)| kk != ks);
                variables.push((ks.to_string(), vs.to_string()));
            }
        }
    }
    let contexts_map = doc.get("contexts").and_then(|x| x.as_map()).ok_or("missing mandatory key 'contexts'")?;
    let scope = doc.get("scope").and_then(|x| x.as_str()).ok_or("missing mandatory key 'scope'")?.trim().to_string();
    let st = State { variables: variables.iter().cloned().collect() };
    let mut ctxs: HashMap<String, Ctx> = HashMap::new();
    for (k, v) in contexts_map {
        if let (Some(name), Some(items)) = (k.as_str(), v.as_vec()) {
            let mut namer = Namer::new(name);
            parse_context(items, &st, &mut ctxs, name == "prototype", &mut namer)?;
        }
    }
    if !ctxs.contains_key("main") {
        return Err("main context missing".into());
    }
    // initial contexts
    let start_items = vec![
        map_from(vec![("meta_include_prototype", Yaml::Bool(false))]),
        map_from(vec![("match", Yaml::Str(String::new())), ("push", Yaml::Str("__main".into()))]),
    ];
    parse_context(&start_items, &st, &mut ctxs, false, &mut Namer::new("__start"))?;
    if let Some(s) = ctxs.get_mut("__start") {
        s.meta_content_scope = vec![scope.clone()];
    }
    let main_items = vec![map_from(vec![("include", Yaml::Str("main".into()))])];
    parse_context(&main_items, &st, &mut ctxs, false, &mut Namer::new("__main"))?;
    let (mip, ms, mcs) = {
        let m = &ctxs["main"];
        (m.mip, m.meta_scope.clone(), m.meta_content_scope.clone())
    };
    if let Some(om) = ctxs.get_mut("__main") {
        om.mip = mip;
        om.meta_scope = ms;
        om.meta_content_scope = mcs;
    }
    if let Some(m) = ctxs.get_mut("main") {
        m.meta_content_scope.insert(0, scope.clone());
    }
    let mut exts = Vec::new();
    for key in ["file_extensions", "hidden_file_extensions"] {
        if let Some(v) = doc.get(key).and_then(|x| x.as_vec()) {
            exts.extend(v.iter().filter_map(|y| y.as_str().map(|s| s.to_string())));
        }
    }
    Ok(Def {
        name: doc.get("name").and_then(|x| x.as_str()).unwrap_or(fallback_name).to_string(),
        exts,
        scope,
        flm: doc.get("first_line_match").and_then(|x| x.as_str()).map(|s| s.to_string()),
        hidden: doc.get("hidden").and_then(|x| x.as_bool()).unwrap_or(false),
        variables,
        contexts: ctxs,
        path: path.to_string(),
    })
}

/// Information about an already compiled syntax.
struct BaseSyntax {
    name: String,
    scope: String,
    raw: Vec<u8>,
    ids: HashMap<String, usize>,
    backrefs: Vec<bool>,
}

fn read_base(dump: &[u8]) -> Res<(Vec<BaseSyntax>, Vec<u8>)> {
    let mut r = Reader::new(dump);
    let n = r.usize()?;
    let mut out = Vec::new();
    for _ in 0..n {
        let start = r.pos;
        let name = r.string()?;
        let _exts = r.vec(|r| r.string())?;
        let scope = r.string()?;
        let _flm = r.option(|r| r.string())?;
        let _hidden = r.bool()?;
        let nv = r.usize()?;
        for _ in 0..nv {
            r.string()?;
            r.string()?;
        }
        let data = r.bytes()?;
        let end = r.pos;
        let raw_ctx = zlib_decode(data)?;
        let mut cr = Reader::new(&raw_ctx);
        let nids = cr.usize()?;
        let mut ids = HashMap::new();
        for _ in 0..nids {
            let k = cr.string()?;
            let _s = cr.usize()?;
            let i = cr.usize()?;
            ids.insert(k, i);
        }
        let set = crate::syntax::set::SyntaxSet::from_dump(&{
            let mut w = Writer::default();
            w.u64(1);
            w.out.extend_from_slice(&dump[start..end]);
            w.out
        })?;
        let backrefs: Vec<bool> = (0..nids)
            .map(|i| set.get_context(crate::syntax::set::ContextId { syntax: 0, index: i }).uses_backrefs)
            .collect();
        out.push(BaseSyntax { name, scope, raw: dump[start..end].to_vec(), ids, backrefs });
    }
    let paths = dump[r.pos..].to_vec();
    Ok((out, paths))
}

fn collect_syntax_files(dir: &Path, out: &mut Vec<PathBuf>) {
    let mut entries: Vec<PathBuf> = match std::fs::read_dir(dir) {
        Ok(rd) => rd.filter_map(|e| e.ok()).map(|e| e.path()).collect(),
        Err(_) => return,
    };
    entries.sort_by(|a, b| a.file_name().cmp(&b.file_name()));
    for p in entries {
        if p.is_dir() {
            collect_syntax_files(&p, out);
        } else if p.extension().map_or(false, |e| e == "sublime-syntax") {
            out.push(p);
        }
    }
}

fn write_ref(w: &mut Writer, r: &Ref) {
    match r {
        Ref::Named(s) => {
            w.out.extend_from_slice(&0u32.to_le_bytes());
            w.bytes(s.as_bytes());
        }
        Ref::ByScope { scope, sub, esc } => {
            w.out.extend_from_slice(&1u32.to_le_bytes());
            w.bytes(scope.as_bytes());
            write_opt_str(w, sub);
            w.u8(*esc as u8);
        }
        Ref::File { name, sub, esc } => {
            w.out.extend_from_slice(&2u32.to_le_bytes());
            w.bytes(name.as_bytes());
            write_opt_str(w, sub);
            w.u8(*esc as u8);
        }
        Ref::Inline(s) => {
            w.out.extend_from_slice(&3u32.to_le_bytes());
            w.bytes(s.as_bytes());
        }
        Ref::Direct(a, b) => {
            w.out.extend_from_slice(&4u32.to_le_bytes());
            w.u64(*a as u64);
            w.u64(*b as u64);
        }
    }
}

fn write_opt_str(w: &mut Writer, s: &Option<String>) {
    match s {
        Some(s) => {
            w.u8(1);
            w.bytes(s.as_bytes());
        }
        None => w.u8(0),
    }
}

fn write_scopes(w: &mut Writer, v: &[String]) {
    w.u64(v.len() as u64);
    for s in v {
        w.bytes(s.as_bytes());
    }
}

fn write_context(w: &mut Writer, c: &Ctx) {
    write_scopes(w, &c.meta_scope);
    write_scopes(w, &c.meta_content_scope);
    w.u8(c.mip as u8);
    match c.clear {
        Some(Clear::TopN(n)) => {
            w.u8(1);
            w.out.extend_from_slice(&0u32.to_le_bytes());
            w.u64(n as u64);
        }
        Some(Clear::All) => {
            w.u8(1);
            w.out.extend_from_slice(&1u32.to_le_bytes());
        }
        None => w.u8(0),
    }
    match c.proto {
        Some((a, b)) => {
            w.u8(1);
            w.u64(a as u64);
            w.u64(b as u64);
        }
        None => w.u8(0),
    }
    w.u8(c.backrefs as u8);
    w.u64(c.patterns.len() as u64);
    for p in &c.patterns {
        match p {
            Pat::Match(m) => {
                w.out.extend_from_slice(&0u32.to_le_bytes());
                w.u8(m.has_captures as u8);
                w.bytes(m.regex.as_bytes());
                write_scopes(w, &m.scope);
                match &m.captures {
                    Some(caps) => {
                        w.u8(1);
                        w.u64(caps.len() as u64);
                        for (i, s) in caps {
                            w.u64(*i as u64);
                            write_scopes(w, s);
                        }
                    }
                    None => w.u8(0),
                }
                match &m.op {
                    Op::Push(refs) | Op::Set(refs) => {
                        let tag: u32 = if matches!(m.op, Op::Push(_)) { 0 } else { 1 };
                        w.out.extend_from_slice(&tag.to_le_bytes());
                        w.u64(refs.len() as u64);
                        for r in refs {
                            write_ref(w, r);
                        }
                    }
                    Op::Pop => w.out.extend_from_slice(&2u32.to_le_bytes()),
                    Op::None => w.out.extend_from_slice(&3u32.to_le_bytes()),
                }
                match &m.with_proto {
                    Some(r) => {
                        w.u8(1);
                        write_ref(w, r);
                    }
                    None => w.u8(0),
                }
            }
            Pat::Include(r) => {
                w.out.extend_from_slice(&1u32.to_le_bytes());
                write_ref(w, r);
            }
        }
    }
}

struct Linker<'a> {
    base: &'a [BaseSyntax],
    defs: &'a [Def],
    ids: &'a [HashMap<String, usize>],
}

impl<'a> Linker<'a> {
    fn total(&self) -> usize {
        self.base.len() + self.defs.len()
    }
    fn name_of(&self, i: usize) -> &str {
        if i < self.base.len() {
            &self.base[i].name
        } else {
            &self.defs[i - self.base.len()].name
        }
    }
    fn scope_of(&self, i: usize) -> &str {
        if i < self.base.len() {
            &self.base[i].scope
        } else {
            &self.defs[i - self.base.len()].scope
        }
    }
    fn ctx_id(&self, i: usize, name: &str) -> Option<usize> {
        if i < self.base.len() {
            self.base[i].ids.get(name).copied()
        } else {
            self.ids[i - self.base.len()].get(name).copied()
        }
    }
    fn find(&self, sub: &Option<String>, pred: impl Fn(usize) -> bool) -> Option<(usize, usize)> {
        let ctx = sub.as_deref().unwrap_or("main");
        let i = (0..self.total()).rev().find(|&i| pred(i))?;
        self.ctx_id(i, ctx).map(|c| (i, c))
    }
    fn plain_fallback(&self, esc: bool, found: Option<(usize, usize)>) -> Option<(usize, usize)> {
        found.or_else(|| if esc { self.find(&None, |i| self.name_of(i) == "Plain Text") } else { None })
    }
    fn link_ref(&self, r: &mut Ref, own: usize) {
        let linked = match r {
            Ref::Named(s) | Ref::Inline(s) => {
                let s2 = if s == "$top_level_main" { "main".to_string() } else { s.clone() };
                self.ctx_id(own, &s2).map(|c| (own, c))
            }
            Ref::ByScope { scope, sub, esc } => {
                let sc = scope.clone();
                self.plain_fallback(*esc, self.find(sub, |i| self.scope_of(i) == sc))
            }
            Ref::File { name, sub, esc } => {
                let n = name.clone();
                self.plain_fallback(*esc, self.find(sub, |i| self.name_of(i) == n))
            }
            Ref::Direct(..) => None,
        };
        if let Some((a, b)) = linked {
            *r = Ref::Direct(a, b);
        }
    }
}

fn mark_no_proto(id: usize, ids: &HashMap<String, usize>, ctxs: &[Ctx], set: &mut HashSet<usize>) {
    if !set.insert(id) {
        return;
    }
    for p in &ctxs[id].patterns {
        match p {
            Pat::Match(m) => {
                if let Op::Push(refs) | Op::Set(refs) = &m.op {
                    for r in refs {
                        match r {
                            Ref::Inline(s) | Ref::Named(s) => {
                                if let Some(&i) = ids.get(s) {
                                    mark_no_proto(i, ids, ctxs, set);
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            Pat::Include(Ref::Named(s)) => {
                if let Some(&i) = ids.get(s) {
                    mark_no_proto(i, ids, ctxs, set);
                }
            }
            _ => {}
        }
    }
}

/// Build a syntax set dump from the base set plus all definitions in `dir`.
pub fn build_syntax_set(dir: &Path, base_dump: &[u8]) -> Result<Vec<u8>, String> {
    let (base, base_paths) = read_base(base_dump)?;
    let mut files = Vec::new();
    collect_syntax_files(dir, &mut files);
    let mut defs = Vec::new();
    for f in &files {
        let text = std::fs::read_to_string(f).map_err(|e| e.to_string())?;
        let stem = f.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
        let d = load_definition(&text, &stem, &f.to_string_lossy()).map_err(|e| format!("{}: {}", f.to_string_lossy(), e))?;
        defs.push(d);
    }
    // sort contexts by name and assign ids
    let mut sorted: Vec<Vec<(String, Ctx)>> = Vec::new();
    let mut ids: Vec<HashMap<String, usize>> = Vec::new();
    for d in &defs {
        let mut v: Vec<(String, Ctx)> = d.contexts.iter().map(|(k, c)| (k.clone(), c.clone())).collect();
        v.sort_by(|a, b| a.0.cmp(&b.0));
        ids.push(v.iter().enumerate().map(|(i, (k, _))| (k.clone(), i)).collect());
        sorted.push(v);
    }
    // link
    {
        let linker = Linker { base: &base, defs: &defs, ids: &ids };
        for (k, ctxs) in sorted.iter_mut().enumerate() {
            let own = base.len() + k;
            let plain: Vec<Ctx> = ctxs.iter().map(|(_, c)| c.clone()).collect();
            let proto = ids[k].get("prototype").copied();
            let mut no_proto = HashSet::new();
            if let Some(p) = proto {
                mark_no_proto(p, &ids[k], &plain, &mut no_proto);
            }
            for (i, (_, c)) in ctxs.iter_mut().enumerate() {
                if let Some(p) = proto {
                    if c.mip && !no_proto.contains(&i) {
                        c.proto = Some((own, p));
                    }
                }
                for p in c.patterns.iter_mut() {
                    match p {
                        Pat::Match(m) => {
                            if let Op::Push(refs) | Op::Set(refs) = &mut m.op {
                                for r in refs.iter_mut() {
                                    linker.link_ref(r, own);
                                }
                            }
                            if let Some(r) = &mut m.with_proto {
                                linker.link_ref(r, own);
                            }
                        }
                        Pat::Include(r) => linker.link_ref(r, own),
                    }
                }
            }
        }
    }
    // propagate backrefs through includes
    loop {
        let mut changed = false;
        for k in 0..sorted.len() {
            for i in 0..sorted[k].len() {
                if sorted[k][i].1.backrefs {
                    continue;
                }
                let inc = sorted[k][i].1.patterns.iter().any(|p| match p {
                    Pat::Include(Ref::Direct(s, c)) => {
                        if *s < base.len() {
                            base[*s].backrefs.get(*c).copied().unwrap_or(false)
                        } else {
                            sorted[*s - base.len()][*c].1.backrefs
                        }
                    }
                    _ => false,
                });
                if inc {
                    sorted[k][i].1.backrefs = true;
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
    // serialize
    let mut w = Writer::default();
    w.u64((base.len() + defs.len()) as u64);
    for b in &base {
        w.out.extend_from_slice(&b.raw);
    }
    for (k, d) in defs.iter().enumerate() {
        w.bytes(d.name.as_bytes());
        w.u64(d.exts.len() as u64);
        for e in &d.exts {
            w.bytes(e.as_bytes());
        }
        w.bytes(d.scope.as_bytes());
        write_opt_str(&mut w, &d.flm);
        w.u8(d.hidden as u8);
        w.u64(d.variables.len() as u64);
        for (a, b) in &d.variables {
            w.bytes(a.as_bytes());
            w.bytes(b.as_bytes());
        }
        let mut cw = Writer::default();
        cw.u64(sorted[k].len() as u64);
        let own = base.len() + k;
        for (i, (name, _)) in sorted[k].iter().enumerate() {
            cw.bytes(name.as_bytes());
            cw.u64(own as u64);
            cw.u64(i as u64);
        }
        cw.u64(sorted[k].len() as u64);
        for (_, c) in &sorted[k] {
            write_context(&mut cw, c);
        }
        w.bytes(&zlib_store(&cw.out));
    }
    // path_syntaxes
    let mut pr = Reader::new(&base_paths);
    let mut paths: Vec<(String, u64)> = Vec::new();
    if let Ok(n) = pr.usize() {
        for _ in 0..n {
            if let (Ok(p), Ok(i)) = (pr.string(), pr.u64()) {
                paths.push((p, i));
            }
        }
    }
    for (k, d) in defs.iter().enumerate() {
        paths.push((format!("/{}", d.path), (base.len() + k) as u64));
    }
    w.u64(paths.len() as u64);
    for (p, i) in paths {
        w.bytes(p.as_bytes());
        w.u64(i);
    }
    Ok(w.out)
}
